window.DC=window.DC||{};DC.curriculum=[{"n":1,"level":"A1","title":"Sich vorstellen: Personalpronomen, sein & haben","theme":"Ich und meine Familie","scene":"family","rec":[],"expl":["**Personalpronomen** ersetzen Namen: ich, du, er, sie, es, wir, ihr, sie, Sie (formell). **Sie** mit großem S benutzt man für fremde Erwachsene, Ärzte, Behörden.","**sein** (to be) und **haben** (to have) sind unregelmäßig und die wichtigsten Verben im Deutschen. Du brauchst sie für Name, Alter, Herkunft, Beruf, Familie und später für das Perfekt.","Achtung: Alter sagt man mit **sein**: __Ich bin 28 Jahre alt__ (nicht: ich habe 28 Jahre)."],"use":"Prüfung Teil 1 (Kontaktaufnahme): Name, Herkunft, Alter, Familie, Beruf.","table":[["Person","sein","haben","Beispiel"],["ich","bin","habe","Ich bin Ravi. Ich habe einen Bruder."],["du","bist","hast","Bist du müde? Hast du Zeit?"],["er / sie / es","ist","hat","Sie ist Lehrerin. Er hat Hunger."],["wir","sind","haben","Wir sind aus Indien."],["ihr","seid","habt","Seid ihr Studenten?"],["sie / Sie","sind","haben","Haben Sie Kinder?"]],"examples":[{"de":"Ich bin Ravi Sharma.","en":"I am Ravi Sharma."},{"de":"Ich bin 28 Jahre alt.","en":"I am 28 years old."},{"de":"Ich komme aus Indien.","en":"I come from India."},{"de":"Meine Schwester ist Ärztin.","en":"My sister is a doctor."},{"de":"Wir haben zwei Kinder.","en":"We have two children."},{"de":"Du bist sehr nett.","en":"You are very nice."},{"de":"Haben Sie ein Handy?","en":"Do you have a mobile phone?"},{"de":"Ihr seid neu hier, oder?","en":"You (pl.) are new here, right?"},{"de":"Er hat heute keine Zeit.","en":"He has no time today."},{"de":"Sind Sie Frau Weber?","en":"Are you Mrs. Weber?"}],"vocab":[{"de":"der Name, -n","en":"name"},{"de":"das Alter","en":"age"},{"de":"die Familie, -n","en":"family"},{"de":"der Vater, ¨","en":"father"},{"de":"die Mutter, ¨","en":"mother"},{"de":"der Bruder, ¨","en":"brother"},{"de":"die Schwester, -n","en":"sister"},{"de":"verheiratet / ledig","en":"married / single"},{"de":"der Beruf, -e","en":"profession"},{"de":"das Land, ¨er","en":"country"},{"de":"wohnen","en":"to live (reside)"},{"de":"kommen aus","en":"to come from"}],"reading":"Hallo! Ich bin Ravi Sharma. Ich bin 28 Jahre alt und komme aus Mumbai, Indien. Ich bin Ingenieur. Jetzt wohne ich in Berlin. Ich bin ledig. Meine Familie ist in Mumbai: Mein Vater ist Lehrer, meine Mutter ist Ärztin. Ich habe eine Schwester. Sie heißt Priya und ist 24. Meine Nachbarin heißt Anna Weber. Sie ist sehr nett. Sie hat einen Sohn und eine Tochter.","tasks":[{"q":"Ich ___ Ravi. (sein)","a":"bin"},{"q":"Du ___ aus Mumbai, oder? (kommen)","a":"kommst"},{"q":"Anna ___ zwei Kinder. (haben)","a":"hat"},{"q":"Wir ___ Nachbarn. (sein)","a":"sind"},{"q":"___ ihr Hunger? (haben)","a":"Habt"},{"q":"___ Sie Herr Müller? (sein)","a":"Sind"},{"q":"Priya ___ 24 Jahre alt. (sein)","a":"ist"},{"q":"Ersetze durch ein Pronomen: __Anna und Ravi__ sind Nachbarn.","a":"Sie sind Nachbarn."},{"q":"Ersetze: __Das Kind__ ist müde.","a":"Es ist müde."},{"q":"Fehler? „Ich habe 28 Jahre.“","a":"Ich bin 28 Jahre alt."}],"exam":[{"q":"Wie alt ist Ravi?","a":"28 Jahre."},{"q":"Was ist Ravis Mutter von Beruf?","a":"Ärztin."},{"q":"Richtig oder falsch: Ravis Familie wohnt in Berlin.","a":"Falsch (in Mumbai)."},{"q":"Ergänze: ___ du verheiratet?","a":"Bist"},{"q":"Ergänze: Meine Eltern ___ ein Haus.","a":"haben"},{"q":"Formell fragen: „Wie heißt du?“ → Sie-Form","a":"Wie heißen Sie?"},{"q":"Frage zur Antwort: „Ich komme aus Indien.“","a":"Woher kommst du / kommen Sie?"},{"q":"Stellen Sie sich vor: Name, Alter, Land, Wohnort, Beruf, Sprachen.","a":""},{"q":"Erzählen Sie über Ihre Familie (5 Sätze).","a":""},{"q":"Buchstabieren Sie Ihren Namen laut.","a":""}],"speak":["Wer ist auf dem Bild? Gib den Personen Namen: __Das ist … Er/Sie ist …__","Wie alt sind die Personen? Was sind sie von Beruf? (Vermutung)","Stell deine eigene Familie vor: __Ich habe … Mein Vater ist …__","Frage einen Partner: __Hast du Geschwister? Bist du verheiratet?__"]},{"n":2,"level":"A1","title":"Präsens: regelmäßige und unregelmäßige Verben","theme":"Alltag und Hobbys","scene":"park","rec":[1],"expl":["Im Präsens nimmst du den **Stamm** (Infinitiv ohne -en) und hängst Endungen an: **-e, -st, -t, -en, -t, -en**.","Stamm auf **-t/-d** (arbeiten, finden): du arbeit**est**, er arbeit**et**. Stamm auf **-s/-ß/-z** (heißen, tanzen): du hei**ßt**.","**Unregelmäßige Verben** ändern den Vokal nur bei **du** und **er/sie/es**: e → i (sprechen → spricht), e → ie (lesen → liest), a → ä (fahren → fährt).","Das Präsens benutzt man auch für die **Zukunft**: __Morgen fahre ich nach Hamburg.__"],"use":"Über Gewohnheiten, Hobbys und Pläne sprechen.","table":[["Person","spielen","arbeiten","fahren (a→ä)","sprechen (e→i)","lesen (e→ie)"],["ich","spiel**e**","arbeit**e**","fahr**e**","sprech**e**","les**e**"],["du","spiel**st**","arbeit**est**","f**ä**hr**st**","spr**i**ch**st**","l**ie**st"],["er/sie/es","spiel**t**","arbeit**et**","f**ä**hr**t**","spr**i**ch**t**","l**ie**st"],["wir","spiel**en**","arbeit**en**","fahr**en**","sprech**en**","les**en**"],["ihr","spiel**t**","arbeit**et**","fahr**t**","sprech**t**","les**t**"],["sie/Sie","spiel**en**","arbeit**en**","fahr**en**","sprech**en**","les**en**"]],"examples":[{"de":"Ich spiele gern Cricket.","en":"I like playing cricket."},{"de":"Du arbeitest viel.","en":"You work a lot."},{"de":"Anna liest jeden Abend.","en":"Anna reads every evening."},{"de":"Ravi spricht Hindi, Englisch und ein bisschen Deutsch.","en":"Ravi speaks Hindi, English and a bit of German."},{"de":"Fährst du mit dem Fahrrad?","en":"Do you go by bike?"},{"de":"Wir kochen am Sonntag zusammen.","en":"We cook together on Sunday."},{"de":"Er isst gern scharf.","en":"He likes eating spicy food."},{"de":"Was machst du am Wochenende?","en":"What are you doing at the weekend?"},{"de":"Sie schläft lange.","en":"She sleeps long."},{"de":"Morgen treffe ich Jonas.","en":"Tomorrow I'm meeting Jonas."}],"vocab":[{"de":"das Hobby, -s","en":"hobby"},{"de":"spielen","en":"to play"},{"de":"kochen","en":"to cook"},{"de":"lesen (liest)","en":"to read"},{"de":"schwimmen","en":"to swim"},{"de":"laufen (läuft)","en":"to run"},{"de":"tanzen","en":"to dance"},{"de":"die Musik","en":"music"},{"de":"das Wochenende, -n","en":"weekend"},{"de":"gern","en":"gladly (like doing)"},{"de":"oft / manchmal / nie","en":"often / sometimes / never"},{"de":"treffen (trifft)","en":"to meet"}],"reading":"Ravi arbeitet von Montag bis Freitag. Am Wochenende hat er Zeit. Er spielt gern Cricket, aber in Berlin spielt kaum jemand Cricket. Deshalb läuft er jetzt im Park. Seine Nachbarin Anna liest viel und tanzt gern. Ihr Sohn Max spielt Fußball. Anna fragt: „Was machst du gern, Ravi?“ Ravi sagt: „Ich koche gern indisch. Isst du gern scharf?“ Anna lacht: „Nicht so gern!“","tasks":[{"q":"Ravi ___ gern. (kochen)","a":"kocht"},{"q":"Du ___ gut Deutsch. (sprechen)","a":"sprichst"},{"q":"Anna ___ ein Buch. (lesen)","a":"liest"},{"q":"___ du am Montag? (arbeiten)","a":"Arbeitest"},{"q":"Max ___ mit dem Bus. (fahren)","a":"fährt"},{"q":"Wie ___ du? (heißen)","a":"heißt"},{"q":"Er ___ Jonas im Café. (treffen)","a":"trifft"},{"q":"[Mix] ___ du Zeit? Ich ___ heute frei. (haben / sein)","a":"Hast / bin"},{"q":"[Mix] Wir ___ aus Indien und ___ Hindi. (kommen / sprechen)","a":"kommen / sprechen"},{"q":"[Mix] Ersetze: __Anna__ läuft gern. → ___ läuft gern.","a":"Sie"}],"exam":[{"q":"Warum läuft Ravi jetzt im Park?","a":"Weil in Berlin kaum jemand Cricket spielt."},{"q":"Was macht Anna gern?","a":"Lesen und tanzen."},{"q":"Richtig oder falsch: Anna isst gern scharf.","a":"Falsch."},{"q":"Ergänze: ___ du gern Tee? (trinken)","a":"Trinkst"},{"q":"Ergänze: Sie ___ (Sg.) jeden Tag Zeitung. (lesen)","a":"liest"},{"q":"Ergänze: Der Zug ___ um 8 Uhr. (fahren)","a":"fährt"},{"q":"Frage zu: „Ich schwimme gern.“","a":"Was machst du gern?"},{"q":"Erzählen Sie über Ihre Hobbys (6 Sätze, mit oft/manchmal/nie).","a":""},{"q":"Was machen Sie am Wochenende?","a":""},{"q":"Fragen Sie Ihren Partner nach drei Hobbys.","a":""}],"speak":["Was machen die Leute im Park? __Der Mann … Die Frau …__","Was machst du gern im Park?","Wie oft machst du Sport? __Ich laufe …-mal pro Woche.__","Vergleiche: Was machen die Leute in Indien am Wochenende?"]},{"n":3,"level":"A1","title":"Satzbau: Das Verb steht auf Position 2","theme":"Mein Tag","scene":"city","rec":[1,2],"expl":["Im deutschen Hauptsatz steht das **konjugierte Verb immer auf Position 2**. Position 1 kann das Subjekt sein – oder eine Zeit, ein Ort, ein Objekt.","Steht etwas anderes auf Position 1, kommt das **Subjekt direkt nach dem Verb** (Inversion): __Heute **gehe ich** ins Kino.__","Eine Position kann aus mehreren Wörtern bestehen: __Am Montagmorgen um 8 Uhr__ = eine Position."],"use":"Abwechslungsreich sprechen: Sätze mit Zeit beginnen (Zuerst…, Dann…, Am Abend…).","table":[["Position 1","Position 2 (Verb)","Rest"],["Ich","fahre","morgen nach Hamburg."],["Morgen","fahre","ich nach Hamburg."],["Nach Hamburg","fahre","ich morgen."],["Am Montagmorgen","trinke","ich immer Chai."],["In Berlin","wohnt","Ravi seit März."]],"examples":[{"de":"Ich stehe um 7 Uhr auf.","en":"I get up at 7."},{"de":"Um 7 Uhr stehe ich auf.","en":"At 7 I get up."},{"de":"Morgens trinke ich Chai.","en":"In the morning I drink chai."},{"de":"Dann fahre ich ins Büro.","en":"Then I go to the office."},{"de":"Im Büro arbeite ich bis 17 Uhr.","en":"In the office I work until 5 pm."},{"de":"Am Abend koche ich.","en":"In the evening I cook."},{"de":"Heute hat Anna Geburtstag.","en":"Today it's Anna's birthday."},{"de":"Leider habe ich keine Zeit.","en":"Unfortunately I have no time."},{"de":"Am Wochenende spielt Max Fußball.","en":"At the weekend Max plays football."},{"de":"Danach lese ich ein bisschen.","en":"After that I read a little."}],"vocab":[{"de":"der Morgen / morgens","en":"morning / in the mornings"},{"de":"der Mittag / mittags","en":"noon"},{"de":"der Abend / abends","en":"evening"},{"de":"die Nacht / nachts","en":"night"},{"de":"heute / morgen / gestern","en":"today / tomorrow / yesterday"},{"de":"zuerst","en":"first"},{"de":"dann / danach","en":"then / after that"},{"de":"aufstehen","en":"to get up"},{"de":"frühstücken","en":"to have breakfast"},{"de":"das Büro, -s","en":"office"},{"de":"die U-Bahn","en":"underground train"},{"de":"leider","en":"unfortunately"}],"reading":"Ravis Tag ist voll. Um 6:30 Uhr klingelt der Wecker. Zuerst trinkt er Chai. Dann frühstückt er. Um 7:45 Uhr nimmt er die U-Bahn. Im Büro arbeitet er mit Jonas. Mittags essen sie zusammen. Am Nachmittag hat Ravi Meetings. Um 17 Uhr fährt er nach Hause. Am Abend lernt er Deutsch. Um 23 Uhr schläft er.","tasks":[{"q":"Stelle um (Beginne mit „Heute“): Ich lerne Deutsch.","a":"Heute lerne ich Deutsch."},{"q":"Stelle um (Beginne mit „Um 8 Uhr“): Ravi nimmt die U-Bahn.","a":"Um 8 Uhr nimmt Ravi die U-Bahn."},{"q":"Ordne: arbeitet / im Büro / Jonas / heute","a":"Heute arbeitet Jonas im Büro."},{"q":"Ordne: ich / abends / koche","a":"Abends koche ich."},{"q":"Ordne: dann / wir / Kaffee / trinken","a":"Dann trinken wir Kaffee."},{"q":"Fehler? „Morgen ich fahre nach Hamburg.“","a":"Morgen fahre ich nach Hamburg."},{"q":"Fehler? „Am Sonntag Anna liest.“","a":"Am Sonntag liest Anna."},{"q":"[Mix] Leider ___ ich keine Zeit. (haben)","a":"habe"},{"q":"[Mix] Am Wochenende ___ Max Fußball. (spielen)","a":"spielt"},{"q":"[Mix] Mittags ___ du mit Jonas? (essen)","a":"isst"}],"exam":[{"q":"Was macht Ravi zuerst?","a":"Er trinkt Chai."},{"q":"Mit wem isst Ravi mittags?","a":"Mit Jonas."},{"q":"Wann lernt Ravi Deutsch?","a":"Am Abend."},{"q":"Beginne mit „Am Abend“: Wir sehen fern.","a":"Am Abend sehen wir fern."},{"q":"Beginne mit „Leider“: Ich kann nicht kommen.","a":"Leider kann ich nicht kommen."},{"q":"Ordne: um 9 Uhr / der Kurs / beginnt","a":"Um 9 Uhr beginnt der Kurs."},{"q":"Ordne: gestern / Anna / war / krank","a":"Gestern war Anna krank."},{"q":"Beschreiben Sie Ihren Tagesablauf mit zuerst, dann, danach, am Abend.","a":""},{"q":"Was machen Sie am Montag anders als am Sonntag?","a":""},{"q":"Fragen Sie: Wann stehst du auf?","a":""}],"speak":["Beschreibe die Stadt: __Links sehe ich … Rechts steht …__","Was macht der Mann? Wohin fährt der Bus? (Vermutung)","Beschreibe deinen Weg zur Arbeit / zur Schule. Beginne jeden Satz anders.","Wie ist ein Tag in Mumbai? __In Mumbai fahren viele Leute …__"]},{"n":4,"level":"A1","title":"Fragen: Ja/Nein-Fragen und W-Fragen","theme":"Kennenlernen","scene":"classroom","rec":[1,2,3],"expl":["**W-Frage:** W-Wort auf Position 1, Verb auf Position 2: __**Wo wohnst** du?__","**Ja/Nein-Frage:** Das Verb steht auf **Position 1**: __**Wohnst** du in Berlin?__","Antwort auf eine **negative** Frage mit **doch** (= ja): __Kommst du nicht? – **Doch**, ich komme!__","Höflich mit Sie: __Können Sie mir helfen? Woher kommen Sie?__"],"use":"In der Prüfung stellst du deinem Partner Fragen (Teil 1 und nach der Präsentation).","table":[["Fragetyp","Position 1","Position 2","Rest","Antwort"],["W-Frage","Woher","kommst","du?","Aus Indien."],["W-Frage","Wie lange","wohnst","du schon hier?","Seit drei Monaten."],["Ja/Nein","Sprichst","du","Deutsch?","Ja / Nein, nur ein bisschen."],["Ja/Nein negativ","Hast","du","keinen Hunger?","Doch! / Nein."],["Höflich","Wie","heißen","Sie?","Ich heiße …"]],"examples":[{"de":"Wie heißt du?","en":"What's your name?"},{"de":"Woher kommen Sie?","en":"Where do you come from?"},{"de":"Was bist du von Beruf?","en":"What's your job?"},{"de":"Welche Sprachen sprichst du?","en":"Which languages do you speak?"},{"de":"Wie lange lernst du schon Deutsch?","en":"How long have you been learning German?"},{"de":"Hast du Geschwister?","en":"Do you have siblings?"},{"de":"Wohnst du allein?","en":"Do you live alone?"},{"de":"Warum lernst du Deutsch?","en":"Why are you learning German?"},{"de":"Wie oft machst du Sport?","en":"How often do you do sport?"},{"de":"Bist du nicht müde? – Doch!","en":"Aren't you tired? – Yes, I am!"}],"vocab":[{"de":"wer","en":"who"},{"de":"was","en":"what"},{"de":"wo / woher / wohin","en":"where / from where / to where"},{"de":"wann","en":"when"},{"de":"warum","en":"why"},{"de":"wie","en":"how"},{"de":"wie viel(e)","en":"how much / many"},{"de":"welch-","en":"which"},{"de":"seit","en":"since / for"},{"de":"der Kurs, -e","en":"course"},{"de":"die Sprache, -n","en":"language"},{"de":"doch","en":"yes (to negative question)"}],"reading":"Im Deutschkurs fragt Frau Klein: „Wer ist neu hier?“ Ravi sagt: „Ich.“ Leila fragt ihn: „Woher kommst du?“ – „Aus Indien. Und du?“ – „Aus dem Iran. Wie lange bist du schon in Berlin?“ – „Seit drei Monaten.“ – „Und warum lernst du Deutsch?“ – „Für meine Arbeit. Sprichst du auch Englisch?“ – „Ja, ein bisschen.“ – „Hast du keinen Hunger? Die Pause beginnt!“ – „Doch! Gehen wir.“","tasks":[{"q":"___ kommst du? – Aus dem Iran.","a":"Woher"},{"q":"___ heißt die Lehrerin? – Frau Klein.","a":"Wie"},{"q":"___ beginnt der Kurs? – Um 9 Uhr.","a":"Wann"},{"q":"___ Sprachen sprichst du? – Hindi und Englisch.","a":"Welche"},{"q":"___ Geschwister hast du? – Zwei.","a":"Wie viele"},{"q":"Mache eine Ja/Nein-Frage: Du wohnst in Berlin.","a":"Wohnst du in Berlin?"},{"q":"Mache eine Sie-Frage: Sie haben Zeit.","a":"Haben Sie Zeit?"},{"q":"Antworte positiv: Hast du keine Zeit?","a":"Doch, ich habe Zeit."},{"q":"[Mix] Frage mit „wann“: Ravi steht um 6:30 Uhr auf.","a":"Wann steht Ravi auf?"},{"q":"[Mix] Frage: Anna liest gern. (Was …?)","a":"Was macht Anna gern?"}],"exam":[{"q":"Woher kommt Leila?","a":"Aus dem Iran."},{"q":"Seit wann ist Ravi in Berlin?","a":"Seit drei Monaten."},{"q":"Warum lernt Ravi Deutsch?","a":"Für seine Arbeit."},{"q":"Frage zur Antwort: „Ich bin Ingenieur.“","a":"Was bist du von Beruf?"},{"q":"Frage zur Antwort: „Ich wohne in Pankow.“","a":"Wo wohnst du?"},{"q":"Frage zur Antwort: „Nein, ich bin ledig.“","a":"Bist du verheiratet?"},{"q":"Antworte: „Kommst du nicht mit?“ (positiv)","a":"Doch, ich komme mit."},{"q":"Stellen Sie Ihrem Partner 6 Fragen (Name, Land, Wohnort, Beruf, Sprachen, Hobby).","a":""},{"q":"Sie treffen einen neuen Kollegen. Stellen Sie 3 höfliche Fragen mit Sie.","a":""},{"q":"Welche Fragen stellt man beim ersten Treffen nicht? Warum?","a":""}],"speak":["Wer ist die Frau vorne? Was macht sie?","Stelle 5 Fragen zum Bild: __Wie viele Schüler …? Was steht an der Tafel?__","Rollenspiel: Du bist neu im Kurs. Stelle dich vor und frage den Nachbarn.","Warum lernen die Leute im Kurs Deutsch? (Vermutung)"]},{"n":5,"level":"A1","title":"Nomen: Genus, Artikel, Plural (Nominativ)","theme":"Wohnung und Möbel","scene":"apartment","rec":[1,2,3,4],"expl":["Jedes Nomen hat ein **Genus**: **der** (maskulin), **die** (feminin), **das** (neutral). Lerne jedes Nomen **immer mit Artikel und Plural**.","**Tipps:** -ung, -heit, -keit, -ion, -schaft, -e → meistens **die**. -chen, -lein, -ment, -um → **das**. Tage, Monate, Jahreszeiten, -er (Personen), -ismus → **der**.","**Plural:** Der Artikel im Plural ist immer **die**. Endungen: -e, -¨e, -er, -¨er, -n/-en, -s, oder keine Endung.","**Unbestimmt:** ein (der/das), eine (die), Plural ohne Artikel. Der **Nominativ** ist der Fall für das **Subjekt**."],"use":"Wohnung beschreiben, Dinge benennen, Bilder beschreiben.","table":[["Genus","bestimmt","unbestimmt","Beispiel","Plural"],["maskulin","der","ein","der Tisch","die Tisch**e**"],["feminin","die","eine","die Lampe","die Lampe**n**"],["neutral","das","ein","das Bett","die Bett**en**"],["neutral","das","ein","das Zimmer","die Zimmer (–)"],["maskulin","der","ein","der Stuhl","die St**ü**hl**e**"],["neutral","das","ein","das Sofa","die Sofa**s**"]],"examples":[{"de":"Das ist ein Sofa. Das Sofa ist neu.","en":"This is a sofa. The sofa is new."},{"de":"Die Wohnung hat zwei Zimmer.","en":"The flat has two rooms."},{"de":"Der Schrank ist groß.","en":"The wardrobe is big."},{"de":"Die Lampe ist kaputt.","en":"The lamp is broken."},{"de":"Das Bett steht im Schlafzimmer.","en":"The bed is in the bedroom."},{"de":"Die Stühle sind bequem.","en":"The chairs are comfortable."},{"de":"Ist das ein Regal? – Ja, das ist ein Regal.","en":"Is that a shelf? – Yes."},{"de":"Die Bücher sind im Regal.","en":"The books are on the shelf."},{"de":"Wie viel kostet der Teppich?","en":"How much is the carpet?"},{"de":"Die Küche ist klein, aber hell.","en":"The kitchen is small but bright."}],"vocab":[{"de":"die Wohnung, -en","en":"flat"},{"de":"das Zimmer, -","en":"room"},{"de":"die Küche, -n","en":"kitchen"},{"de":"das Bad, ¨er","en":"bathroom"},{"de":"der Tisch, -e","en":"table"},{"de":"der Stuhl, ¨e","en":"chair"},{"de":"das Bett, -en","en":"bed"},{"de":"der Schrank, ¨e","en":"wardrobe"},{"de":"das Regal, -e","en":"shelf"},{"de":"die Lampe, -n","en":"lamp"},{"de":"der Teppich, -e","en":"carpet"},{"de":"die Miete, -n","en":"rent"}],"reading":"Ravi hat jetzt eine Wohnung in Pankow. Die Wohnung hat zwei Zimmer, eine Küche und ein Bad. Das Wohnzimmer ist hell. Dort stehen ein Sofa und ein Regal. Das Regal ist voll: Die Bücher sind aus Indien. Im Schlafzimmer steht ein Bett. Die Lampe ist leider kaputt. Die Küche ist klein. Die Miete ist nicht billig, aber die Wohnung ist schön.","tasks":[{"q":"___ Wohnung (der/die/das)","a":"die"},{"q":"___ Zimmer","a":"das"},{"q":"___ Tisch","a":"der"},{"q":"___ Zeitung (Tipp: -ung)","a":"die"},{"q":"___ Mädchen (Tipp: -chen)","a":"das"},{"q":"Plural: der Stuhl → die ___","a":"Stühle"},{"q":"Plural: das Buch → die ___","a":"Bücher"},{"q":"[Mix] Das ist ___ Lampe. ___ Lampe ___ kaputt. (ein/e, der/die/das, sein)","a":"eine / Die / ist"},{"q":"[Mix] Frage: ___ kostet das Sofa?","a":"Wie viel / Was"},{"q":"[Mix] Ordne: steht / im Zimmer / ein Bett","a":"Im Zimmer steht ein Bett."}],"exam":[{"q":"Wo wohnt Ravi?","a":"In Pankow."},{"q":"Wie viele Zimmer hat die Wohnung?","a":"Zwei."},{"q":"Was ist kaputt?","a":"Die Lampe."},{"q":"Artikel + Plural: Küche","a":"die Küche, die Küchen"},{"q":"Artikel + Plural: Bad","a":"das Bad, die Bäder"},{"q":"Artikel + Plural: Schrank","a":"der Schrank, die Schränke"},{"q":"Artikel: Freiheit / Dokument / Montag","a":"die / das / der"},{"q":"Beschreiben Sie Ihre Wohnung: Wie viele Zimmer? Was steht wo?","a":""},{"q":"Was ist Ihr Lieblingszimmer? Warum?","a":""},{"q":"Wie wohnt man in Indien? Vergleichen Sie kurz.","a":""}],"speak":["Welche Zimmer siehst du? __Links ist das …, rechts ist das …__","Nenne 8 Möbel mit Artikel.","Wie findest du die Wohnung? __Das Sofa ist … Die Lampe ist …__","Beschreibe dein Traumhaus."]},{"n":6,"level":"A1","title":"Der Akkusativ","theme":"Einkaufen","scene":"shop","rec":[1,2,3,5],"expl":["Der **Akkusativ** ist das **direkte Objekt**: Wen oder was? __Ich kaufe **den** Apfel.__","**Nur maskulin ändert sich**: der → **den**, ein → **einen**. Feminin, neutral und Plural bleiben gleich.","Verben mit Akkusativ: haben, kaufen, brauchen, möchten, nehmen, essen, trinken, sehen, suchen, finden, besuchen, es gibt.","**es gibt + Akkusativ**: __Es gibt **einen** Supermarkt hier.__"],"use":"Einkaufen, bestellen, sagen, was man braucht oder hat.","table":[["Fall","maskulin","feminin","neutral","Plural"],["Nominativ","der / ein Käse","die / eine Milch","das / ein Brot","die / – Äpfel"],["Akkusativ","**den / einen** Käse","die / eine Milch","das / ein Brot","die / – Äpfel"],["Pronomen Nom.","er","sie","es","sie"],["Pronomen Akk.","**ihn**","sie","es","sie"]],"examples":[{"de":"Ich brauche einen Einkaufswagen.","en":"I need a shopping trolley."},{"de":"Ravi kauft den Reis.","en":"Ravi buys the rice."},{"de":"Möchtest du eine Tüte?","en":"Would you like a bag?"},{"de":"Wir nehmen das Brot.","en":"We'll take the bread."},{"de":"Es gibt hier einen Markt.","en":"There is a market here."},{"de":"Ich suche den Joghurt. – Er ist dort.","en":"I'm looking for the yoghurt. – It's there."},{"de":"Den Käse finde ich lecker.","en":"I find the cheese tasty."},{"de":"Kaufst du den Tee? – Ja, ich kaufe ihn.","en":"Are you buying the tea? – Yes, I'm buying it."},{"de":"Sie trinkt einen Kaffee.","en":"She drinks a coffee."},{"de":"Wir haben keine Zeit, aber einen Plan.","en":"We have no time but a plan."}],"vocab":[{"de":"der Supermarkt, ¨e","en":"supermarket"},{"de":"der Apfel, ¨","en":"apple"},{"de":"der Reis","en":"rice"},{"de":"der Käse","en":"cheese"},{"de":"die Milch","en":"milk"},{"de":"das Brot, -e","en":"bread"},{"de":"das Ei, -er","en":"egg"},{"de":"die Tomate, -n","en":"tomato"},{"de":"die Tüte, -n","en":"bag"},{"de":"die Kasse, -n","en":"checkout"},{"de":"kosten","en":"to cost"},{"de":"das Angebot, -e","en":"special offer"}],"reading":"Am Samstag geht Ravi in den Supermarkt. Er braucht einen Liter Milch, ein Brot, einen Käse und Tomaten. Er sucht auch den Basmatireis, aber er findet ihn nicht. Er fragt eine Verkäuferin. Sie sagt: „Den Reis haben wir dort hinten.“ An der Kasse sieht Ravi ein Angebot: Äpfel für 1,99 €. Er nimmt einen Kilo. Die Kassiererin fragt: „Brauchen Sie eine Tüte?“ – „Nein danke, ich habe einen Rucksack.“","tasks":[{"q":"Ich brauche ___ Apfel. (ein)","a":"einen"},{"q":"Ravi kauft ___ Milch. (die)","a":"die"},{"q":"Wir nehmen ___ Käse. (der)","a":"den"},{"q":"Hast du ___ Tüte? (ein)","a":"eine"},{"q":"Es gibt hier ___ Bäcker. (ein)","a":"einen"},{"q":"Siehst du den Mann? – Ja, ich sehe ___.","a":"ihn"},{"q":"Wo ist die Butter? Ich finde ___ nicht.","a":"sie"},{"q":"[Mix] ___ Kinder brauchen neue Stühle. (Artikel Plural)","a":"Die"},{"q":"[Mix] Ordne: kauft / am Samstag / Ravi / einen Käse","a":"Am Samstag kauft Ravi einen Käse."},{"q":"[Mix] Frage: Ich suche den Reis. (Was …?)","a":"Was suchst du?"}],"exam":[{"q":"Was braucht Ravi?","a":"Milch, Brot, Käse, Tomaten (und Reis)."},{"q":"Wo ist der Reis?","a":"Dort hinten."},{"q":"Warum braucht Ravi keine Tüte?","a":"Er hat einen Rucksack."},{"q":"Nominativ oder Akkusativ? „Der Mann kauft den Tee.“ – der Mann = ?","a":"Nominativ"},{"q":"Ergänze: Ich möchte ___ Kaffee und ___ Wasser. (ein)","a":"einen / ein"},{"q":"Ersetze: Ich kaufe __den Apfel__.","a":"Ich kaufe ihn."},{"q":"Ergänze: Gibt es hier ___ Bank? (ein)","a":"eine"},{"q":"Sie planen eine Party. Was kaufen Sie? Machen Sie eine Liste mit Artikeln.","a":""},{"q":"Was kaufen Sie jede Woche? Was kaufen Sie nie?","a":""},{"q":"Rollenspiel: Sie suchen im Supermarkt etwas und fragen einen Verkäufer.","a":""}],"speak":["Was siehst du im Supermarkt? __Ich sehe einen Mann, einen Wagen …__","Was kauft der Mann? Was kostet das Angebot?","Was brauchst du heute? Nenne 6 Sachen mit ein/eine/einen.","Wo kaufst du lieber ein: Markt oder Supermarkt? Warum?"]},{"n":7,"level":"A1","title":"Negation: nicht und kein","theme":"Essen und Trinken","scene":"kitchen","rec":[2,3,5,6],"expl":["**kein** verneint ein **Nomen ohne Artikel oder mit ein**: __Ich habe **keine** Zeit. Das ist **kein** Tee.__ Kein hat die Endungen von ein (+ Plural: keine).","**nicht** verneint **alles andere**: Verben, Adjektive, Nomen mit der/mein, Orte, Zeiten.","Position von nicht: meistens **am Ende**, aber **vor** Adjektiv, Ort, Präposition und zweitem Verbteil: __Ich komme **nicht** aus Berlin. Das ist **nicht** gut.__","**sondern** nach nicht/kein: __Ich trinke keinen Kaffee, **sondern** Tee.__"],"use":"Etwas ablehnen, Vorlieben sagen, im Restaurant bestellen.","table":[["Positiv","Negativ","Regel"],["Ich habe einen Hund.","Ich habe **keinen** Hund.","ein → kein (Akk. m. keinen)"],["Ich trinke Milch.","Ich trinke **keine** Milch.","ohne Artikel → kein"],["Ich esse das Fleisch.","Ich esse das Fleisch **nicht**.","der/die/das → nicht"],["Das Essen ist scharf.","Das Essen ist **nicht** scharf.","vor Adjektiv"],["Er wohnt in Berlin.","Er wohnt **nicht** in Berlin.","vor Ort"],["Ich koche heute.","Ich koche heute **nicht**.","am Ende"]],"examples":[{"de":"Ich esse kein Fleisch.","en":"I don't eat meat."},{"de":"Das ist nicht mein Teller.","en":"That's not my plate."},{"de":"Wir haben keine Eier mehr.","en":"We have no more eggs."},{"de":"Die Suppe ist nicht heiß.","en":"The soup isn't hot."},{"de":"Ravi trinkt keinen Alkohol.","en":"Ravi doesn't drink alcohol."},{"de":"Anna kocht heute nicht.","en":"Anna isn't cooking today."},{"de":"Das ist kein Curry, sondern ein Dal.","en":"That's not a curry but a dal."},{"de":"Ich mag Fisch nicht.","en":"I don't like fish."},{"de":"Er isst nicht gern süß.","en":"He doesn't like eating sweet things."},{"de":"Haben Sie keinen Hunger? – Doch.","en":"Aren't you hungry? – Yes, I am."}],"vocab":[{"de":"das Fleisch","en":"meat"},{"de":"der Fisch, -e","en":"fish"},{"de":"das Gemüse","en":"vegetables"},{"de":"das Obst","en":"fruit"},{"de":"die Suppe, -n","en":"soup"},{"de":"der Teller, -","en":"plate"},{"de":"scharf","en":"spicy"},{"de":"süß / salzig","en":"sweet / salty"},{"de":"mögen (mag)","en":"to like"},{"de":"vegetarisch","en":"vegetarian"},{"de":"der Hunger / der Durst","en":"hunger / thirst"},{"de":"schmecken","en":"to taste (good)"}],"reading":"Anna und Max essen bei Ravi. Ravi kocht Dal und Reis. Anna fragt: „Ist das Essen scharf?“ Ravi sagt: „Nein, es ist nicht scharf. Heute koche ich nicht so scharf.“ Max isst kein Gemüse, aber er mag den Reis. Anna trinkt keinen Wein, sondern Wasser. „Hast du keinen Nachtisch?“, fragt Max. „Doch! Es gibt Gulab Jamun. Aber sie sind sehr süß.“ Max sagt: „Das ist kein Problem!“","tasks":[{"q":"Ich habe ___ Hunger.","a":"keinen"},{"q":"Das ist ___ Suppe, sondern Soße.","a":"keine"},{"q":"Das Essen schmeckt ___.","a":"nicht"},{"q":"Ravi isst ___ Fleisch.","a":"kein"},{"q":"Ich mag den Fisch ___.","a":"nicht"},{"q":"Max ist ___ müde.","a":"nicht"},{"q":"Wir haben ___ Eier.","a":"keine"},{"q":"[Mix] Verneine: Ich kaufe einen Apfel.","a":"Ich kaufe keinen Apfel."},{"q":"[Mix] Verneine: Heute kocht Anna.","a":"Heute kocht Anna nicht."},{"q":"[Mix] Antworte positiv: Isst du kein Gemüse?","a":"Doch, ich esse Gemüse."}],"exam":[{"q":"Was kocht Ravi?","a":"Dal und Reis."},{"q":"Was trinkt Anna?","a":"Wasser."},{"q":"Was isst Max nicht?","a":"Gemüse."},{"q":"Verneine: Das ist ein Problem.","a":"Das ist kein Problem."},{"q":"Verneine: Ich wohne in München.","a":"Ich wohne nicht in München."},{"q":"Verneine: Er hat Kinder.","a":"Er hat keine Kinder."},{"q":"Ergänze: Ich trinke keinen Kaffee, ___ Tee.","a":"sondern"},{"q":"Was essen Sie gern, was nicht? Nennen Sie 6 Beispiele.","a":""},{"q":"Sie sind im Restaurant. Sagen Sie, was Sie nicht essen, und bestellen Sie.","a":""},{"q":"Was ist typisch für das Essen in Ihrem Land?","a":""}],"speak":["Was machen die Personen in der Küche?","Was ist im Kühlschrank? Was ist nicht da? __Es gibt keine …__","Du kochst für Gäste. Frag: __Essen Sie kein Fleisch? Mögen Sie …?__","Was isst du nie? Warum nicht?"]},{"n":8,"level":"A1","title":"Possessivartikel (Nominativ und Akkusativ)","theme":"Familie und Freunde","scene":"family","rec":[1,5,6,7],"expl":["Possessivartikel zeigen, **wem** etwas gehört: mein, dein, sein, ihr, unser, euer, ihr/Ihr.","Sie haben **dieselben Endungen wie ein/kein**: mein Bruder, mein**e** Schwester, mein Kind, mein**e** Kinder. Akkusativ maskulin: mein**en** Bruder.","**sein** = von ihm (er/es), **ihr** = von ihr (sie) oder von ihnen (Plural). **Ihr** (groß) = formell.","**euer** verliert das e mit Endung: eu**re** Mutter."],"use":"Über Familie und Besitz sprechen: __Das ist meine Mutter. Ich besuche meinen Onkel.__","table":[["Person","m. Nom.","m. Akk.","f. Nom./Akk.","n. Nom./Akk.","Plural"],["ich","mein","mein**en**","mein**e**","mein","mein**e**"],["du","dein","dein**en**","dein**e**","dein","dein**e**"],["er / es","sein","sein**en**","sein**e**","sein","sein**e**"],["sie","ihr","ihr**en**","ihr**e**","ihr","ihr**e**"],["wir","unser","unser**en**","unser**e**","unser","unser**e**"],["ihr","euer","eur**en**","eur**e**","euer","eur**e**"],["sie / Sie","ihr / Ihr","ihr**en** / Ihr**en**","ihr**e** / Ihr**e**","ihr / Ihr","ihr**e** / Ihr**e**"]],"examples":[{"de":"Das ist meine Schwester Priya.","en":"This is my sister Priya."},{"de":"Mein Vater ist Lehrer.","en":"My father is a teacher."},{"de":"Ich vermisse meinen Bruder.","en":"I miss my brother."},{"de":"Anna liebt ihren Sohn.","en":"Anna loves her son."},{"de":"Max sucht seine Schuhe.","en":"Max is looking for his shoes."},{"de":"Wo ist dein Handy?","en":"Where's your phone?"},{"de":"Unsere Oma wohnt in Pune.","en":"Our grandma lives in Pune."},{"de":"Besucht ihr eure Eltern?","en":"Are you visiting your parents?"},{"de":"Ist das Ihr Koffer?","en":"Is that your suitcase? (formal)"},{"de":"Die Kinder spielen mit ihrem Hund.","en":"The children play with their dog."}],"vocab":[{"de":"die Eltern (Pl.)","en":"parents"},{"de":"die Großeltern (Pl.)","en":"grandparents"},{"de":"der Onkel, -","en":"uncle"},{"de":"die Tante, -n","en":"aunt"},{"de":"der Cousin / die Cousine","en":"cousin"},{"de":"der Sohn, ¨e","en":"son"},{"de":"die Tochter, ¨","en":"daughter"},{"de":"der Freund, -e / die Freundin, -nen","en":"friend / boyfriend, girlfriend"},{"de":"vermissen","en":"to miss"},{"de":"besuchen","en":"to visit"},{"de":"lieben","en":"to love"},{"de":"das Foto, -s","en":"photo"}],"reading":"Ravi zeigt Anna ein Foto. „Das ist meine Familie. Das ist mein Vater, und das ist meine Mutter. Das hier ist mein Onkel. Seine Frau ist auch auf dem Foto.“ Anna fragt: „Und wer ist das Mädchen?“ – „Das ist meine Schwester Priya. Ihr Hund heißt Moti.“ Anna sagt: „Eure Familie ist groß! Vermisst du deine Eltern?“ – „Ja, sehr. Ich besuche meine Eltern im Dezember.“","tasks":[{"q":"Das ist ___ Mutter. (ich)","a":"meine"},{"q":"Wie heißt ___ Bruder? (du)","a":"dein"},{"q":"Anna liebt ___ Sohn. (sie)","a":"ihren"},{"q":"Max sucht ___ Ball. (er)","a":"seinen"},{"q":"Wir besuchen ___ Großeltern. (wir)","a":"unsere"},{"q":"Wo ist ___ Auto? (ihr)","a":"euer"},{"q":"Ist das ___ Tasche, Frau Weber? (Sie)","a":"Ihre"},{"q":"[Mix] Ich habe ___ Auto. (kein)","a":"kein"},{"q":"[Mix] Verneine: Das ist mein Stift.","a":"Das ist nicht mein Stift."},{"q":"[Mix] Frage: ___ ist das? – Das ist meine Tante.","a":"Wer"}],"exam":[{"q":"Wen zeigt Ravi auf dem Foto?","a":"Seine Familie (Vater, Mutter, Onkel, Tante, Schwester)."},{"q":"Wie heißt Priyas Hund?","a":"Moti."},{"q":"Wann besucht Ravi seine Eltern?","a":"Im Dezember."},{"q":"Ergänze: Priya und ___ Freund (sie) gehen ins Kino.","a":"ihr"},{"q":"Ergänze: Ravi ruft ___ Mutter an. (er)","a":"seine"},{"q":"Ergänze: Kinder, wo sind ___ Jacken? (ihr)","a":"eure"},{"q":"sein oder ihr? Max und ___ Schwester.","a":"seine"},{"q":"Zeigen Sie ein Familienfoto (oder erfinden Sie eins) und beschreiben Sie es.","a":""},{"q":"Wer ist Ihr bester Freund / Ihre beste Freundin? Erzählen Sie.","a":""},{"q":"Wen vermissen Sie? Warum?","a":""}],"speak":["Stell dir vor, das ist deine Familie: __Das ist mein …, das ist meine …__","Was isst die Familie? Wer sitzt neben wem?","Frag den Partner: __Wie heißt dein …? Was macht deine …?__","Wie groß ist deine Familie? Wo wohnen deine Verwandten?"]},{"n":9,"level":"A1","title":"Zahlen, Uhrzeit und Zeitangaben (am, um, im)","theme":"Termine","scene":"office","rec":[2,3,4,6],"expl":["**Uhrzeit offiziell:** 14:30 = vierzehn Uhr dreißig. **Inoffiziell:** halb drei (= 2:30!), Viertel nach zwei (2:15), Viertel vor drei (2:45), fünf nach zwei.","**Achtung:** __halb drei__ = 2:30 (eine halbe Stunde **vor** drei).","**Präpositionen:** **um** + Uhrzeit, **am** + Tag/Datum/Tageszeit, **im** + Monat/Jahreszeit, **von … bis**, Jahr ohne Präposition (__2026__ oder __im Jahr 2026__).","**Datum:** am ersten (1.) Mai, am dritten (3.) Juni, am zwanzigsten (20.)."],"use":"Termine machen, Öffnungszeiten, Verabredungen, Arzttermine.","table":[["Frage","Präposition","Beispiel"],["Um wie viel Uhr?","um","um 8 Uhr, um halb neun"],["Wann? (Tag)","am","am Montag, am Wochenende, am Abend"],["Wann? (Datum)","am","am 3. Oktober (am dritten Oktober)"],["Wann? (Monat/Jahreszeit)","im","im Mai, im Sommer"],["Wie lange?","von … bis","von 9 bis 17 Uhr"],["Wie spät ist es?","–","Es ist Viertel nach drei (15:15)."]],"examples":[{"de":"Wie spät ist es? – Es ist halb neun.","en":"What time is it? – It's half past eight."},{"de":"Der Kurs beginnt um 18 Uhr.","en":"The course starts at 6 pm."},{"de":"Am Montag habe ich einen Termin.","en":"On Monday I have an appointment."},{"de":"Im Winter ist es kalt.","en":"In winter it's cold."},{"de":"Mein Geburtstag ist am 12. April.","en":"My birthday is on 12th April."},{"de":"Das Büro ist von 9 bis 17 Uhr geöffnet.","en":"The office is open 9 to 5."},{"de":"Um Viertel vor acht nehme ich den Bus.","en":"At quarter to eight I take the bus."},{"de":"Hast du am Freitagabend Zeit?","en":"Do you have time on Friday evening?"},{"de":"Ravi kommt 2025 nach Deutschland.","en":"Ravi comes to Germany in 2025."},{"de":"Das Meeting dauert eine Stunde.","en":"The meeting lasts one hour."}],"vocab":[{"de":"die Uhr, -en","en":"clock / o'clock"},{"de":"die Stunde, -n","en":"hour"},{"de":"die Minute, -n","en":"minute"},{"de":"der Termin, -e","en":"appointment"},{"de":"der Tag, -e","en":"day"},{"de":"die Woche, -n","en":"week"},{"de":"der Monat, -e","en":"month"},{"de":"das Jahr, -e","en":"year"},{"de":"geöffnet / geschlossen","en":"open / closed"},{"de":"dauern","en":"to last"},{"de":"beginnen","en":"to begin"},{"de":"pünktlich","en":"on time"}],"reading":"Jonas fragt Ravi: „Hast du am Donnerstag Zeit? Wir haben ein Meeting mit dem Chef.“ – „Um wie viel Uhr?“ – „Um halb zehn. Es dauert bis elf Uhr.“ – „Am Donnerstag um 9:30 Uhr? Das geht. Aber um 12 Uhr habe ich einen Arzttermin.“ – „Kein Problem. Und im Oktober haben wir ein Teamessen, am 17.“ Ravi schreibt den Termin in seinen Kalender. Er ist immer pünktlich.","tasks":[{"q":"Es ist 7:30 Uhr = Es ist ___ acht.","a":"halb"},{"q":"Es ist 4:15 = Es ist Viertel ___ vier.","a":"nach"},{"q":"Es ist 10:45 = Es ist Viertel ___ elf.","a":"vor"},{"q":"Wir treffen uns ___ 8 Uhr.","a":"um"},{"q":"___ Sonntag schlafe ich lange.","a":"Am"},{"q":"___ August fliege ich nach Indien.","a":"Im"},{"q":"Das Geschäft ist ___ 8 ___ 20 Uhr geöffnet.","a":"von / bis"},{"q":"[Mix] Ordne: habe / am Montag / ich / einen Termin","a":"Am Montag habe ich einen Termin."},{"q":"[Mix] Frage zur Antwort: „Um 9 Uhr.“","a":"Um wie viel Uhr / Wann beginnt …?"},{"q":"[Mix] Verneine: Ich habe am Freitag Zeit.","a":"Ich habe am Freitag keine Zeit."}],"exam":[{"q":"Wann ist das Meeting?","a":"Am Donnerstag um 9:30 Uhr."},{"q":"Was hat Ravi um 12 Uhr?","a":"Einen Arzttermin."},{"q":"Wann ist das Teamessen?","a":"Am 17. Oktober."},{"q":"Schreibe inoffiziell: 18:30","a":"halb sieben"},{"q":"Schreibe inoffiziell: 9:45","a":"Viertel vor zehn"},{"q":"Ergänze: ___ Frühling fahre ich nach Wien.","a":"Im"},{"q":"Lies laut: 1.487 / 2026 / 23,50 €","a":"tausendvierhundertsiebenundachtzig / zweitausendsechsundzwanzig / dreiundzwanzig Euro fünfzig"},{"q":"Rufen Sie beim Arzt an und machen Sie einen Termin.","a":""},{"q":"Wann haben Sie Geburtstag? Wie feiern Sie?","a":""},{"q":"Sagen Sie Ihrem Partner, wann Sie diese Woche Zeit haben.","a":""}],"speak":["Wie spät ist es vielleicht im Büro? Was machen die Leute?","Mach einen Termin mit der Kollegin: __Hast du am … um … Zeit?__","Was machst du um 7 Uhr, um 13 Uhr, um 20 Uhr?","Wann sind die Geschäfte in Indien geöffnet? Und in Deutschland?"]},{"n":10,"level":"A1","title":"Trennbare Verben","theme":"Tagesablauf","scene":"apartment","rec":[2,3,9],"expl":["Viele Verben haben eine **Vorsilbe**, die sich im Satz **trennt** und **ans Ende** geht: auf|stehen → __Ich **stehe** um 7 Uhr **auf**.__","Trennbar sind z. B.: **ab-, an-, auf-, aus-, ein-, mit-, nach-, vor-, weg-, zu-, zurück-, fern-**. Die Betonung liegt auf der Vorsilbe: __AUFstehen__.","**Nicht trennbar**: **be-, ver-, er-, ent-, ge-, zer-, emp-, miss-** (besuchen, verstehen, erklären).","Im Nebensatz und mit Modalverb bleibt das Verb zusammen (später: __weil ich früh aufstehe__)."],"use":"Tagesablauf beschreiben, telefonieren, einkaufen, Termine.","table":[["Infinitiv","Satz","Frage"],["aufstehen","Ich **stehe** um 7 Uhr **auf**.","Wann **stehst** du **auf**?"],["einkaufen","Ravi **kauft** am Samstag **ein**.","**Kaufst** du heute **ein**?"],["anrufen","Ich **rufe** dich morgen **an**.","**Rufst** du mich **an**?"],["fernsehen","Anna **sieht** abends **fern**.","**Siehst** du oft **fern**?"],["mitkommen","**Kommst** du **mit**?","Wer **kommt mit**?"],["besuchen (untrennbar)","Ich **besuche** meine Oma.","–"]],"examples":[{"de":"Ich stehe um 6:30 Uhr auf.","en":"I get up at 6:30."},{"de":"Der Zug fährt um 8 Uhr ab.","en":"The train leaves at 8."},{"de":"Ruf mich bitte heute Abend an!","en":"Please call me tonight."},{"de":"Wir kaufen im Supermarkt ein.","en":"We shop at the supermarket."},{"de":"Der Film fängt um 20 Uhr an.","en":"The film starts at 8 pm."},{"de":"Ravi räumt am Sonntag die Wohnung auf.","en":"Ravi tidies the flat on Sunday."},{"de":"Kommst du mit ins Kino?","en":"Are you coming to the cinema?"},{"de":"Ich lade dich zum Essen ein.","en":"I'm inviting you to dinner."},{"de":"Wann kommst du zurück?","en":"When are you coming back?"},{"de":"Ich verstehe die Frage nicht.","en":"I don't understand the question."}],"vocab":[{"de":"aufstehen","en":"to get up"},{"de":"einschlafen","en":"to fall asleep"},{"de":"anrufen","en":"to call"},{"de":"einkaufen","en":"to shop"},{"de":"aufräumen","en":"to tidy up"},{"de":"anfangen (fängt an)","en":"to begin"},{"de":"aufhören","en":"to stop"},{"de":"mitkommen","en":"to come along"},{"de":"einladen (lädt ein)","en":"to invite"},{"de":"fernsehen (sieht fern)","en":"to watch TV"},{"de":"zurückkommen","en":"to come back"},{"de":"abholen","en":"to pick up"}],"reading":"Am Sonntag steht Ravi spät auf. Zuerst ruft er seine Mutter in Mumbai an. Dann räumt er die Wohnung auf. Mittags kauft er ein. Um 15 Uhr holt er Leila ab. Sie gehen zusammen spazieren. Leila fragt: „Kommst du am Mittwoch mit ins Kino? Der Film fängt um 19 Uhr an.“ – „Gern!“ Abends sieht Ravi ein bisschen fern. Um 23 Uhr schläft er ein.","tasks":[{"q":"Ich ___ um 7 Uhr ___. (aufstehen)","a":"stehe / auf"},{"q":"Ravi ___ seine Mutter ___. (anrufen)","a":"ruft / an"},{"q":"Wann ___ der Kurs ___? (anfangen)","a":"fängt / an"},{"q":"___ du mit? (mitkommen)","a":"Kommst"},{"q":"Anna ___ abends ___. (fernsehen)","a":"sieht / fern"},{"q":"Ich ___ dich am Bahnhof ___. (abholen)","a":"hole / ab"},{"q":"Ich ___ meine Tante. (besuchen)","a":"besuche"},{"q":"[Mix] Beginne mit „Am Samstag“: Wir kaufen ein.","a":"Am Samstag kaufen wir ein."},{"q":"[Mix] Verneine: Ich rufe dich an.","a":"Ich rufe dich nicht an."},{"q":"[Mix] Um ___ Uhr (7:30 inoffiziell) stehe ich auf.","a":"halb acht"}],"exam":[{"q":"Wen ruft Ravi zuerst an?","a":"Seine Mutter."},{"q":"Wann holt Ravi Leila ab?","a":"Um 15 Uhr."},{"q":"Wann beginnt der Film?","a":"Um 19 Uhr (am Mittwoch)."},{"q":"Bilde einen Satz: einladen / Anna / Ravi / zum Essen","a":"Anna lädt Ravi zum Essen ein."},{"q":"Bilde eine Frage: du / aufräumen / heute?","a":"Räumst du heute auf?"},{"q":"Trennbar oder nicht? verkaufen / einkaufen","a":"verkaufen: nicht trennbar; einkaufen: trennbar"},{"q":"Ergänze: Der Bus ___ um 9 Uhr ___. (abfahren)","a":"fährt / ab"},{"q":"Beschreiben Sie Ihren Sonntag mit mindestens 5 trennbaren Verben.","a":""},{"q":"Laden Sie einen Freund zu etwas ein.","a":""},{"q":"Was machen Sie am Abend, bevor Sie schlafen?","a":""}],"speak":["Was macht man im Schlafzimmer, was im Wohnzimmer? __Im Wohnzimmer sieht man fern…__","Beschreibe deinen Morgen: __Ich stehe … auf, dann …__","Lade deinen Partner ein: __Kommst du am … mit …?__","Wer räumt bei dir zu Hause auf?"]},{"n":11,"level":"A1","title":"Modalverben","theme":"Regeln und Wünsche","scene":"station","rec":[2,3,6,7,9,10],"expl":["Modalverben: **können** (can), **müssen** (must), **wollen** (want), **sollen** (should, Auftrag), **dürfen** (may, erlaubt), **möchten** (would like).","Das **Modalverb** steht auf **Position 2**, das **Infinitiv** am **Ende**: __Ich **muss** heute **arbeiten**.__ Trennbare Verben bleiben am Ende zusammen: __Ich muss früh **aufstehen**.__","Ich und er/sie/es haben **keine Endung**: ich kann, er kann.","**nicht müssen** = not have to. **nicht dürfen** = must not! __Hier darf man nicht rauchen.__"],"use":"Planen, erlauben, verbieten, Wünsche äußern, Pflichten nennen.","table":[["Person","können","müssen","wollen","dürfen","sollen","möchten"],["ich","kann","muss","will","darf","soll","möchte"],["du","kannst","musst","willst","darfst","sollst","möchtest"],["er/sie/es","kann","muss","will","darf","soll","möchte"],["wir","können","müssen","wollen","dürfen","sollen","möchten"],["ihr","könnt","müsst","wollt","dürft","sollt","möchtet"],["sie/Sie","können","müssen","wollen","dürfen","sollen","möchten"]],"examples":[{"de":"Ich möchte eine Fahrkarte nach München.","en":"I'd like a ticket to Munich."},{"de":"Kann ich mit Karte zahlen?","en":"Can I pay by card?"},{"de":"Du musst am Gleis 7 einsteigen.","en":"You have to board at platform 7."},{"de":"Hier darf man nicht rauchen.","en":"You're not allowed to smoke here."},{"de":"Ravi will im Sommer nach Wien fahren.","en":"Ravi wants to go to Vienna in summer."},{"de":"Wir müssen in Hamburg umsteigen.","en":"We have to change in Hamburg."},{"de":"Der Arzt sagt, ich soll viel trinken.","en":"The doctor says I should drink a lot."},{"de":"Darf ich hier sitzen?","en":"May I sit here?"},{"de":"Du musst nicht kommen.","en":"You don't have to come."},{"de":"Kannst du mich vom Bahnhof abholen?","en":"Can you pick me up from the station?"}],"vocab":[{"de":"der Bahnhof, ¨e","en":"station"},{"de":"der Zug, ¨e","en":"train"},{"de":"das Gleis, -e","en":"platform"},{"de":"die Fahrkarte, -n","en":"ticket"},{"de":"einsteigen / aussteigen","en":"to get on / off"},{"de":"umsteigen","en":"to change (trains)"},{"de":"die Verspätung, -en","en":"delay"},{"de":"abfahren / ankommen","en":"to depart / arrive"},{"de":"reservieren","en":"to reserve"},{"de":"der Koffer, -","en":"suitcase"},{"de":"rauchen","en":"to smoke"},{"de":"erlaubt / verboten","en":"allowed / forbidden"}],"reading":"Ravi will am Freitag nach München fahren. Er möchte seinen Freund Arjun besuchen. Am Schalter fragt er: „Ich möchte eine Fahrkarte nach München. Muss ich umsteigen?“ – „Nein, der ICE fährt direkt. Sie können auch einen Platz reservieren.“ – „Kann ich mit Karte zahlen?“ – „Ja, natürlich.“ Am Bahnhof sieht Ravi ein Schild: „Rauchen verboten.“ Der Zug hat Verspätung. Ravi muss 20 Minuten warten.","tasks":[{"q":"Ich ___ nach München fahren. (wollen)","a":"will"},{"q":"___ du mir helfen? (können)","a":"Kannst"},{"q":"Hier ___ man nicht parken. (dürfen)","a":"darf"},{"q":"Wir ___ in Köln umsteigen. (müssen)","a":"müssen"},{"q":"Ich ___ einen Tee, bitte. (möchten)","a":"möchte"},{"q":"Ordne: muss / früh / ich / aufstehen / morgen","a":"Morgen muss ich früh aufstehen."},{"q":"„Du musst nicht kommen“ bedeutet: a) verboten b) nicht nötig","a":"b) nicht nötig"},{"q":"[Mix] Ich ___ dich morgen ___. (können + anrufen)","a":"kann / anrufen"},{"q":"[Mix] Du ___ keinen Alkohol trinken. (dürfen)","a":"darfst"},{"q":"[Mix] Um ___ Uhr (14:15 inoffiziell: Viertel nach …) muss ich los.","a":"Viertel nach zwei"}],"exam":[{"q":"Wen will Ravi besuchen?","a":"Seinen Freund Arjun."},{"q":"Muss Ravi umsteigen?","a":"Nein."},{"q":"Wie lange muss Ravi warten?","a":"20 Minuten."},{"q":"Umformen mit „können“: Ich spreche Deutsch.","a":"Ich kann Deutsch sprechen."},{"q":"Umformen mit „müssen“: Er räumt auf.","a":"Er muss aufräumen."},{"q":"Frage höflich mit „dürfen“: hier / telefonieren","a":"Darf ich hier telefonieren?"},{"q":"Welches Modalverb? Der Chef sagt: „Schreiben Sie den Bericht!“ → Ich ___ den Bericht schreiben.","a":"soll"},{"q":"Was dürfen Kinder in Ihrem Land (nicht)? Nennen Sie 4 Regeln.","a":""},{"q":"Sie kaufen am Schalter eine Fahrkarte. Spielen Sie das Gespräch.","a":""},{"q":"Was möchten Sie in Deutschland machen? Was müssen Sie noch lernen?","a":""}],"speak":["Wohin fährt der Zug? Was müssen die Leute machen?","Was darf man im Zug (nicht) machen?","Du willst nach Hamburg. Frag am Schalter: __Ich möchte … Muss ich …?__","Was kann man in Berlin am Wochenende machen?"]},{"n":12,"level":"A1","title":"Imperativ","theme":"Tipps und Anweisungen","scene":"doctor","rec":[2,6,7,10,11],"expl":["Mit dem **Imperativ** gibt man Bitten, Tipps und Anweisungen. Drei Formen:","**du:** Stamm ohne -st und ohne du: du kommst → **Komm!** Vokal e→i bleibt: du sprichst → **Sprich!** Aber a→ä nicht: du fährst → **Fahr!**","**ihr:** ihr-Form ohne ihr: **Kommt!** · **Sie:** Verb + Sie: **Kommen Sie!**","**sein:** Sei! Seid! Seien Sie! Mit **bitte**, **doch**, **mal** klingt es freundlicher. Trennbare Vorsilbe am Ende: **Ruf** mich **an**!"],"use":"Tipps geben, Wege erklären, Rezepte, beim Arzt.","table":[["Infinitiv","du","ihr","Sie"],["kommen","Komm!","Kommt!","Kommen Sie!"],["nehmen","Nimm!","Nehmt!","Nehmen Sie!"],["fahren","Fahr!","Fahrt!","Fahren Sie!"],["anrufen","Ruf an!","Ruft an!","Rufen Sie an!"],["arbeiten","Arbeite!","Arbeitet!","Arbeiten Sie!"],["sein","Sei!","Seid!","Seien Sie!"]],"examples":[{"de":"Nehmen Sie die Tabletten dreimal am Tag.","en":"Take the tablets three times a day."},{"de":"Trink viel Wasser!","en":"Drink a lot of water!"},{"de":"Bleib im Bett!","en":"Stay in bed!"},{"de":"Ruf mich bitte an!","en":"Please call me!"},{"de":"Seien Sie bitte pünktlich.","en":"Please be on time."},{"de":"Macht die Hausaufgaben!","en":"Do your homework! (pl.)"},{"de":"Iss nicht so viel Zucker!","en":"Don't eat so much sugar!"},{"de":"Geh doch mal zum Arzt!","en":"Why don't you go to the doctor!"},{"de":"Warten Sie bitte einen Moment.","en":"Please wait a moment."},{"de":"Sprich bitte langsam!","en":"Please speak slowly!"}],"vocab":[{"de":"der Arzt, ¨e / die Ärztin, -nen","en":"doctor"},{"de":"die Praxis, Praxen","en":"practice"},{"de":"krank / gesund","en":"ill / healthy"},{"de":"der Kopf / Kopfschmerzen","en":"head / headache"},{"de":"der Bauch / Bauchschmerzen","en":"belly / stomach ache"},{"de":"das Fieber","en":"fever"},{"de":"die Erkältung, -en","en":"cold"},{"de":"die Tablette, -n","en":"tablet"},{"de":"das Rezept, -e","en":"prescription / recipe"},{"de":"die Apotheke, -n","en":"pharmacy"},{"de":"sich ausruhen","en":"to rest"},{"de":"die Krankmeldung","en":"sick note"}],"reading":"Ravi hat Fieber und Halsschmerzen. Er geht zur Ärztin. Die Ärztin sagt: „Machen Sie bitte den Mund auf. Sie haben eine Erkältung. Bleiben Sie drei Tage zu Hause und ruhen Sie sich aus. Trinken Sie viel Tee. Nehmen Sie diese Tabletten zweimal am Tag.“ Ravi ruft Jonas an. Jonas sagt: „Werd schnell gesund! Und arbeite nicht von zu Hause!“ Anna bringt Suppe: „Iss die Suppe, solange sie heiß ist!“","tasks":[{"q":"du: (trinken) ___ viel Wasser!","a":"Trink"},{"q":"du: (nehmen) ___ die Tablette!","a":"Nimm"},{"q":"Sie: (warten) ___ bitte!","a":"Warten Sie"},{"q":"ihr: (sein) ___ leise!","a":"Seid"},{"q":"du: (anrufen) ___ mich morgen ___!","a":"Ruf / an"},{"q":"du: (fahren) ___ vorsichtig!","a":"Fahr"},{"q":"du: (sein) ___ nicht traurig!","a":"Sei"},{"q":"[Mix] Umformen: Du musst im Bett bleiben. → Imperativ","a":"Bleib im Bett!"},{"q":"[Mix] Verneine: Iss Fleisch!","a":"Iss kein Fleisch!"},{"q":"[Mix] Sie-Form: Kannst du langsam sprechen?","a":"Sprechen Sie bitte langsam!"}],"exam":[{"q":"Was hat Ravi?","a":"Eine Erkältung (Fieber, Halsschmerzen)."},{"q":"Wie oft soll er die Tabletten nehmen?","a":"Zweimal am Tag."},{"q":"Was bringt Anna?","a":"Suppe."},{"q":"du-Imperativ: lesen","a":"Lies!"},{"q":"ihr-Imperativ: aufräumen","a":"Räumt auf!"},{"q":"Sie-Imperativ: sich setzen","a":"Setzen Sie sich!"},{"q":"Mach höflich: „Tür zu!“ (Sie)","a":"Machen Sie bitte die Tür zu!"},{"q":"Ihr Freund hat Kopfschmerzen. Geben Sie 4 Tipps im Imperativ.","a":""},{"q":"Erklären Sie ein einfaches Rezept aus Ihrem Land.","a":""},{"q":"Welche Tipps geben Sie einem neuen Deutschlerner?","a":""}],"speak":["Was sagt die Ärztin zum Patienten? __Nehmen Sie … Bleiben Sie …__","Was fehlt dem Patienten vielleicht?","Gib einem Freund Tipps gegen Stress (du-Form).","Was macht man in Indien bei einer Erkältung? __Trink … mit Ingwer!__"]},{"n":13,"level":"A2","title":"Der Dativ: Artikel, Pronomen und Dativ-Verben","theme":"Hilfe und Gefallen","scene":"office","rec":[1,6,8,11],"expl":["Der **Dativ** antwortet auf **Wem?** Er zeigt meistens die **Person**, die etwas bekommt oder für die etwas passiert.","Artikel: der → **dem**, die → **der**, das → **dem**, Plural die → **den + n** (den Kinder**n**). ein → **einem/einer**, mein → **meinem/meiner**.","**Dativ-Verben** (nur Dativ-Objekt!): helfen, danken, gefallen, gehören, schmecken, passen, stehen (Kleidung), antworten, gratulieren, zuhören, fehlen, wehtun.","Wichtige Ausdrücke: __Wie geht es **dir**? **Mir** ist kalt. Das ist **mir** egal. Es tut **mir** leid.__"],"use":"Hilfe anbieten, Gefallen/Meinung ausdrücken, Befinden sagen.","table":[["Fall","maskulin","feminin","neutral","Plural","Pronomen"],["Nominativ","der / ein","die / eine","das / ein","die","ich, du, er, sie, wir, ihr, sie"],["Akkusativ","den / einen","die / eine","das / ein","die","mich, dich, ihn, sie, uns, euch, sie"],["Dativ","**dem / einem**","**der / einer**","**dem / einem**","**den … -n**","**mir, dir, ihm, ihr, uns, euch, ihnen**"]],"examples":[{"de":"Kannst du mir helfen?","en":"Can you help me?"},{"de":"Ravi hilft dem Kollegen.","en":"Ravi helps the colleague."},{"de":"Das Büro gefällt ihm.","en":"He likes the office."},{"de":"Gehört der Laptop dir?","en":"Does the laptop belong to you?"},{"de":"Ich danke Ihnen für die Hilfe.","en":"Thank you for the help."},{"de":"Die Jacke passt meiner Schwester nicht.","en":"The jacket doesn't fit my sister."},{"de":"Wie geht es Ihnen? – Mir geht es gut.","en":"How are you? – I'm fine."},{"de":"Das Essen schmeckt den Kindern.","en":"The children like the food."},{"de":"Wir gratulieren unserer Chefin.","en":"We congratulate our boss."},{"de":"Mir ist kalt. Dir auch?","en":"I'm cold. You too?"}],"vocab":[{"de":"der Kollege, -n / die Kollegin, -nen","en":"colleague"},{"de":"der Chef, -s / die Chefin, -nen","en":"boss"},{"de":"helfen (hilft)","en":"to help"},{"de":"gefallen (gefällt)","en":"to please (like)"},{"de":"gehören","en":"to belong"},{"de":"danken","en":"to thank"},{"de":"passen","en":"to fit / suit"},{"de":"antworten","en":"to answer"},{"de":"gratulieren","en":"to congratulate"},{"de":"wehtun","en":"to hurt"},{"de":"leidtun","en":"to be sorry"},{"de":"egal","en":"doesn't matter"}],"reading":"Ravi ist neu im Team. Jonas hilft ihm viel. Er zeigt ihm das System und antwortet ihm immer schnell. Die neue Arbeit gefällt Ravi sehr. Heute hat die Chefin, Frau Berger, Geburtstag. Alle gratulieren ihr. Ravi schenkt ihr indischen Tee. Der Tee schmeckt der Chefin. Sie dankt ihm: „Das ist sehr nett von Ihnen!“ Später fragt Jonas: „Gehört die Tasse dir?“ – „Nein, sie gehört meiner Kollegin Mia.“","tasks":[{"q":"Ich helfe ___ Mann. (der)","a":"dem"},{"q":"Das Kleid gefällt ___ Frau. (die)","a":"der"},{"q":"Der Ball gehört ___ Kind. (das)","a":"dem"},{"q":"Wir danken ___ Kinder___. (die, Pl.)","a":"den / Kindern"},{"q":"Kannst du ___ helfen? (ich)","a":"mir"},{"q":"Wie geht es ___? (du)","a":"dir"},{"q":"Die Schuhe passen ___ nicht. (er)","a":"ihm"},{"q":"[Mix] Ich kaufe ___ Tee und schenke ___ Chefin ___ Tee. (der, meine, der)","a":"den / meiner / den"},{"q":"[Mix] ___ mir bitte! (helfen, du-Imperativ)","a":"Hilf"},{"q":"[Mix] Ich ___ dir morgen helfen. (können)","a":"kann"}],"exam":[{"q":"Wer hilft Ravi?","a":"Jonas."},{"q":"Was schenkt Ravi der Chefin?","a":"Indischen Tee."},{"q":"Wem gehört die Tasse?","a":"Mias (seiner Kollegin Mia)."},{"q":"Akk. oder Dat.? „Ich sehe den Mann.“ / „Ich helfe dem Mann.“","a":"Akkusativ / Dativ"},{"q":"Ergänze: Das Buch gehört ___ Lehrerin.","a":"der"},{"q":"Ersetze: Ich danke __meinem Vater__.","a":"Ich danke ihm."},{"q":"Ergänze: Es tut ___ leid. (ich)","a":"mir"},{"q":"Was gefällt Ihnen in Deutschland? Was gefällt Ihnen nicht?","a":""},{"q":"Wem helfen Sie oft? Wie?","a":""},{"q":"Ihr Kollege ist neu. Bieten Sie ihm Hilfe an.","a":""}],"speak":["Wer hilft wem im Büro? __Die Kollegin hilft dem Mann …__","Gefällt dir das Büro? Warum (nicht)?","Frag deinen Partner: __Wem gehört …? Kannst du mir … helfen?__","Wie geht es dir heute? Antworte mit __Mir ist … / Mir geht es …__"]},{"n":14,"level":"A2","title":"Dativ und Akkusativ im selben Satz","theme":"Geschenke","scene":"party","rec":[6,8,13],"expl":["Verben wie **geben, schenken, zeigen, bringen, schicken, erklären, empfehlen, kaufen, leihen** haben zwei Objekte: **Person (Dativ)** und **Sache (Akkusativ)**.","**Reihenfolge:** Zwei Nomen → **Dativ vor Akkusativ**: __Ich schenke **meiner Mutter** **einen Schal**.__","Ein Pronomen → **Pronomen zuerst**: __Ich schenke **ihn** meiner Mutter. / Ich schenke **ihr** einen Schal.__","Zwei Pronomen → **Akkusativ vor Dativ**: __Ich schenke **ihn ihr**.__"],"use":"Über Geschenke, Empfehlungen, Erklärungen sprechen (Teil 1 Planung: Geschenk kaufen!).","table":[["Fall","Satz","Regel"],["Nomen + Nomen","Ich gebe **dem Kind** **den Ball**.","Dativ → Akkusativ"],["Pronomen + Nomen","Ich gebe **ihm** **den Ball**.","Pronomen zuerst"],["Nomen + Pronomen","Ich gebe **ihn** **dem Kind**.","Pronomen zuerst"],["Pronomen + Pronomen","Ich gebe **ihn ihm**.","Akkusativ → Dativ"]],"examples":[{"de":"Ich schenke meinem Vater ein Buch.","en":"I give my father a book."},{"de":"Ich schenke es ihm zum Geburtstag.","en":"I give it to him for his birthday."},{"de":"Zeig mir bitte das Foto!","en":"Show me the photo, please."},{"de":"Kannst du mir den Weg erklären?","en":"Can you explain the way to me?"},{"de":"Anna bringt den Kindern Kuchen.","en":"Anna brings the children cake."},{"de":"Ich empfehle dir diesen Film.","en":"I recommend this film to you."},{"de":"Schick ihn mir bitte per E-Mail!","en":"Please send it to me by email."},{"de":"Er leiht seiner Freundin das Fahrrad.","en":"He lends his girlfriend the bike."},{"de":"Wir kaufen unserer Oma eine Blume.","en":"We buy our grandma a flower."},{"de":"Gib es ihr!","en":"Give it to her!"}],"vocab":[{"de":"das Geschenk, -e","en":"present"},{"de":"der Geburtstag, -e","en":"birthday"},{"de":"schenken","en":"to give (as present)"},{"de":"geben (gibt)","en":"to give"},{"de":"zeigen","en":"to show"},{"de":"schicken","en":"to send"},{"de":"erklären","en":"to explain"},{"de":"leihen","en":"to lend"},{"de":"empfehlen (empfiehlt)","en":"to recommend"},{"de":"der Gutschein, -e","en":"voucher"},{"de":"die Kerze, -n","en":"candle"},{"de":"der Blumenstrauß, ¨e","en":"bouquet"}],"reading":"Anna hat am Samstag Geburtstag. Ravi und Leila überlegen: „Was schenken wir ihr?“ Leila sagt: „Wir können ihr einen Gutschein schenken.“ Ravi zeigt Leila einen schönen Schal im Internet. „Kaufen wir ihn ihr?“ – „Ja! Und Max, ihrem Sohn, bringen wir ein kleines Spiel mit.“ Am Samstag gibt Ravi Anna den Schal. Anna freut sich sehr: „Danke! Wer hat ihn euch empfohlen?“ – „Niemand. Wir haben gute Ideen!“","tasks":[{"q":"Ich schenke ___ Mutter ___ Kette. (meine, eine)","a":"meiner / eine"},{"q":"Er gibt ___ Kind ___ Apfel. (das, ein)","a":"dem / einen"},{"q":"Zeig ___ (ich) das Handy!","a":"mir"},{"q":"Ordne: dem Lehrer / ich / das Heft / gebe","a":"Ich gebe dem Lehrer das Heft."},{"q":"Ersetze das Heft: Ich gebe ___ dem Lehrer.","a":"es"},{"q":"Ersetze beides: Ich gebe ___ ___.","a":"es ihm"},{"q":"Ordne: erklärt / ihr / die Chefin / den Plan","a":"Die Chefin erklärt ihr den Plan."},{"q":"[Mix] Wir müssen ___ Oma ___ Geschenk kaufen. (unsere, ein)","a":"unserer / ein"},{"q":"[Mix] Kannst du ___ ___ schicken? (es, ich)","a":"es mir"},{"q":"[Mix] Imperativ (Sie): mir / zeigen / den Pass","a":"Zeigen Sie mir den Pass!"}],"exam":[{"q":"Wer hat Geburtstag?","a":"Anna."},{"q":"Was bekommt Anna?","a":"Einen Schal."},{"q":"Was bringen sie Max mit?","a":"Ein kleines Spiel."},{"q":"Ersetze: Ich schenke __meiner Schwester__ __die Blumen__.","a":"Ich schenke sie ihr."},{"q":"Ergänze: Kannst du ___ (wir) ___ Weg erklären?","a":"uns / den"},{"q":"Ordne: ihm / ihn / gebe / ich","a":"Ich gebe ihn ihm."},{"q":"Ergänze: Ich empfehle ___ Gästen ___ Restaurant. (die, das)","a":"den / das"},{"q":"Planen Sie mit Ihrem Partner ein Geschenk für eine Kollegin. Was, wie teuer, wer kauft es?","a":""},{"q":"Was war Ihr schönstes Geschenk? Wer hat es Ihnen geschenkt?","a":""},{"q":"Was schenkt man in Ihrem Land zur Hochzeit?","a":""}],"speak":["Was schenken die Personen? Wem?","Was ist im Paket? (Vermutung) __Vielleicht schenkt sie ihm …__","Plane eine Überraschung für einen Freund. __Wir kaufen ihm … und geben es ihm …__","Welche Geschenke findest du gut, welche nicht?"]},{"n":15,"level":"A2","title":"Präpositionen mit Akkusativ und mit Dativ","theme":"Wege in der Stadt","scene":"city","rec":[6,9,11,13],"expl":["**Immer Akkusativ:** durch, für, gegen, ohne, um, bis (Merke: **DOGFU** = durch, ohne, gegen, für, um).","**Immer Dativ:** aus, bei, mit, nach, seit, von, zu, gegenüber (Merke: **aus-bei-mit-nach-von-seit-zu**).","**Wichtig:** __nach__ + Städte/Länder ohne Artikel (__nach Berlin__), __zu__ + Personen/Orte (__zum Arzt, zu Anna__), __nach Hause__ (Richtung) / __zu Hause__ (Ort).","Kontraktionen: zu dem → **zum**, zu der → **zur**, bei dem → **beim**, von dem → **vom**."],"use":"Wege beschreiben, Verkehrsmittel nennen, Herkunft und Zeit angeben.","table":[["Präposition","Fall","Beispiel","Bedeutung"],["für","Akk.","für den Chef","for"],["ohne","Akk.","ohne meinen Schlüssel","without"],["durch","Akk.","durch den Park","through"],["mit","Dat.","mit dem Bus","with / by"],["zu","Dat.","zum Bahnhof, zur Post","to"],["bei","Dat.","beim Arzt, bei meiner Tante","at (someone's)"],["aus","Dat.","aus dem Haus, aus Indien","out of / from"],["seit","Dat.","seit einem Jahr","since / for"]],"examples":[{"de":"Ich fahre mit der U-Bahn zur Arbeit.","en":"I go to work by underground."},{"de":"Gehen Sie durch den Park!","en":"Go through the park!"},{"de":"Das Geschenk ist für meinen Bruder.","en":"The present is for my brother."},{"de":"Ravi wohnt seit einem Jahr in Berlin.","en":"Ravi has lived in Berlin for a year."},{"de":"Ich komme gerade vom Arzt.","en":"I'm just coming from the doctor."},{"de":"Heute Abend bin ich bei Leila.","en":"Tonight I'm at Leila's."},{"de":"Gegenüber der Bank ist ein Café.","en":"Opposite the bank is a café."},{"de":"Ohne dich gehe ich nicht.","en":"I'm not going without you."},{"de":"Nach dem Kurs fahre ich nach Hause.","en":"After the course I go home."},{"de":"Wir gehen um den See.","en":"We walk around the lake."}],"vocab":[{"de":"die Haltestelle, -n","en":"stop"},{"de":"die Straße, -n","en":"street"},{"de":"die Ampel, -n","en":"traffic light"},{"de":"die Kreuzung, -en","en":"crossing"},{"de":"geradeaus","en":"straight ahead"},{"de":"links / rechts","en":"left / right"},{"de":"abbiegen","en":"to turn"},{"de":"die Post","en":"post office"},{"de":"die Bank, -en","en":"bank"},{"de":"das Rathaus, ¨er","en":"town hall"},{"de":"das Fahrrad, ¨er","en":"bike"},{"de":"zu Fuß","en":"on foot"}],"reading":"Leila besucht Ravi zum ersten Mal. Sie ruft ihn an: „Ich bin am Bahnhof. Wie komme ich zu dir?“ – „Nimm den Bus 100. Fahr bis zur Haltestelle Rathaus. Dann geh zu Fuß durch den Park. Gegenüber dem Park ist eine Bäckerei. Mein Haus ist neben der Bäckerei.“ – „Ohne Stadtplan ist das schwer!“ – „Kein Problem, ich hole dich von der Haltestelle ab.“ Nach zehn Minuten sind sie zusammen bei Ravi.","tasks":[{"q":"Ich fahre ___ Bus. (mit + der)","a":"mit dem"},{"q":"Das ist ___ meine Mutter. (für)","a":"für"},{"q":"Ravi kommt ___ Indien.","a":"aus"},{"q":"Ich gehe ___ Arzt. (zu + der)","a":"zum"},{"q":"Sie wohnt ___ drei Jahren hier.","a":"seit"},{"q":"Wir gehen ___ Park. (durch + der)","a":"durch den"},{"q":"Er arbeitet ___ Siemens.","a":"bei"},{"q":"[Mix] Ich fahre heute ___ Hause, ich bin nicht gern ___ Hause.","a":"nach / zu"},{"q":"[Mix] Kannst du ___ (ich) ___ Hause bringen?","a":"mich / nach"},{"q":"[Mix] ___ geradeaus bis ___ Ampel! (gehen, du; zu + die)","a":"Geh / zur"}],"exam":[{"q":"Welchen Bus nimmt Leila?","a":"Den Bus 100."},{"q":"Wo ist Ravis Haus?","a":"Neben der Bäckerei (gegenüber dem Park)."},{"q":"Wer holt Leila ab?","a":"Ravi."},{"q":"Ergänze: Wir treffen uns ___ Bahnhof. (an + dem)","a":"am"},{"q":"Ergänze: Wir fliegen ___ Mumbai.","a":"nach"},{"q":"Ergänze: Ich gehe ___ Freundin. (zu + meine)","a":"zu meiner"},{"q":"Ergänze: Das ist ein Film ___ Kinder.","a":"für"},{"q":"Beschreiben Sie den Weg von Ihrer Wohnung zum Supermarkt.","a":""},{"q":"Wie fahren Sie zur Arbeit / zum Kurs? Wie lange dauert das?","a":""},{"q":"Ein Tourist fragt Sie nach dem Weg zum Bahnhof. Helfen Sie.","a":""}],"speak":["Wohin fährt der Bus? Wie kommt der Mann zum Bahnhof?","Erkläre den Weg: __Geh geradeaus bis zur …, dann …__","Womit fährst du lieber: mit dem Bus, mit dem Rad oder mit dem Auto? Warum?","Wie ist der Verkehr in Mumbai im Vergleich zu Berlin?"]},{"n":16,"level":"A2","title":"Wechselpräpositionen: Wo? (Dativ) und Wohin? (Akkusativ)","theme":"Umzug und Einrichten","scene":"moving","rec":[5,6,13,15],"expl":["**an, auf, hinter, in, neben, über, unter, vor, zwischen** können Dativ oder Akkusativ haben.","**Wo?** (Position, keine Bewegung) → **Dativ**: __Das Buch liegt **auf dem** Tisch.__","**Wohin?** (Richtung, Bewegung zum Ziel) → **Akkusativ**: __Ich lege das Buch **auf den** Tisch.__","Verbpaare: **stellen → stehen**, **legen → liegen**, **setzen → sitzen**, **hängen → hängen**. Die Verben mit Bewegung (stellen, legen, setzen, hängen) = Akkusativ."],"use":"Umzug, Zimmer beschreiben, Bildbeschreibung (Wo ist was?).","table":[["Präp.","Wo? (Dativ)","Wohin? (Akkusativ)"],["in","Ich bin **im** Büro.","Ich gehe **ins** Büro."],["auf","Die Tasse steht **auf dem** Tisch.","Ich stelle die Tasse **auf den** Tisch."],["an","Das Bild hängt **an der** Wand.","Ich hänge das Bild **an die** Wand."],["neben","Der Stuhl steht **neben dem** Bett.","Ich stelle den Stuhl **neben das** Bett."],["unter","Die Katze liegt **unter dem** Sofa.","Die Katze läuft **unter das** Sofa."],["zwischen","Die Lampe steht **zwischen den** Sesseln.","Ich stelle sie **zwischen die** Sessel."]],"examples":[{"de":"Stell den Karton in die Küche!","en":"Put the box in the kitchen!"},{"de":"Der Karton steht in der Küche.","en":"The box is in the kitchen."},{"de":"Ich lege die Bücher ins Regal.","en":"I put the books on the shelf."},{"de":"Die Bücher liegen im Regal.","en":"The books are on the shelf."},{"de":"Wir hängen die Lampe über den Tisch.","en":"We hang the lamp above the table."},{"de":"Die Lampe hängt über dem Tisch.","en":"The lamp hangs above the table."},{"de":"Setz dich auf das Sofa!","en":"Sit down on the sofa!"},{"de":"Max sitzt auf dem Sofa.","en":"Max is sitting on the sofa."},{"de":"Der Schlüssel liegt unter der Zeitung.","en":"The key is under the newspaper."},{"de":"Wir fahren morgen in die Stadt.","en":"Tomorrow we're going into town."}],"vocab":[{"de":"der Umzug, ¨e","en":"house move"},{"de":"umziehen","en":"to move house"},{"de":"der Karton, -s","en":"cardboard box"},{"de":"die Wand, ¨e","en":"wall"},{"de":"der Boden, ¨","en":"floor"},{"de":"die Ecke, -n","en":"corner"},{"de":"stellen / stehen","en":"to put (upright) / to stand"},{"de":"legen / liegen","en":"to lay / to lie"},{"de":"hängen","en":"to hang"},{"de":"setzen / sitzen","en":"to seat / to sit"},{"de":"der Sessel, -","en":"armchair"},{"de":"die Möbel (Pl.)","en":"furniture"}],"reading":"Ravi zieht um. Jonas und Anna helfen ihm. Ravi sagt: „Stellt die Kartons bitte ins Wohnzimmer.“ Jonas stellt das Sofa an die Wand. Anna legt die Bücher ins Regal. „Wohin hängen wir das Bild?“ – „Über das Sofa.“ Am Abend ist alles fertig: Das Sofa steht an der Wand, das Bild hängt über dem Sofa, die Bücher liegen im Regal. Nur der Schlüssel fehlt! Endlich findet Ravi ihn: Er liegt unter einem Karton.","tasks":[{"q":"Ich stelle die Vase auf ___ Tisch.","a":"den"},{"q":"Die Vase steht auf ___ Tisch.","a":"dem"},{"q":"Das Bild hängt an ___ Wand.","a":"der"},{"q":"Leg das Handy in ___ Tasche!","a":"die"},{"q":"Ich gehe ___ Kino. (in + das)","a":"ins"},{"q":"Die Katze liegt unter ___ Bett.","a":"dem"},{"q":"Wählen: Ich ___ den Teller auf den Tisch. (stelle/stehe)","a":"stelle"},{"q":"[Mix] Wo ist das Buch? – ___ liegt ___ Regal. (es, in + das)","a":"Es / im"},{"q":"[Mix] Stell ___ (er = der Stuhl) neben ___ Tür!","a":"ihn / die"},{"q":"[Mix] Wir müssen die Kartons ___ Keller bringen. (in + der)","a":"in den"}],"exam":[{"q":"Wer hilft Ravi beim Umzug?","a":"Jonas und Anna."},{"q":"Wo hängt das Bild?","a":"Über dem Sofa."},{"q":"Wo ist der Schlüssel?","a":"Unter einem Karton."},{"q":"Wo oder wohin? „Ich fahre in die Stadt.“","a":"Wohin → Akkusativ"},{"q":"Ergänze: Das Auto steht vor ___ Haus.","a":"dem"},{"q":"Ergänze: Setz dich neben ___ (ich)!","a":"mich"},{"q":"Ergänze: Ich hänge die Jacke in ___ Schrank.","a":"den"},{"q":"Beschreiben Sie Ihr Zimmer genau: Was steht / liegt / hängt wo?","a":""},{"q":"Sie ziehen um. Geben Sie Ihren Freunden Anweisungen.","a":""},{"q":"Was war schwierig bei Ihrem letzten Umzug?","a":""}],"speak":["Wo stehen die Kartons? Wo steht das Sofa? __Links neben dem …__","Was machen die Männer? Wohin tragen sie den Karton?","Gib Anweisungen: __Stell den Karton in … Leg die Bücher auf …__","Beschreibe ein Bild in deinem Zimmer: Wo hängt es?"]},{"n":17,"level":"A2","title":"Das Perfekt","theme":"Erlebnisse und Wochenende","scene":"park","rec":[2,9,10,15,16],"expl":["Das **Perfekt** ist die wichtigste Vergangenheit **beim Sprechen**. Form: **haben/sein (Position 2) + Partizip II (Ende)**.","**Partizip II:** regelmäßig **ge-…-t** (gemacht, gekauft), unregelmäßig **ge-…-en** oft mit Vokalwechsel (gegessen, getrunken, geschrieben).","**Trennbare Verben:** ge in der Mitte: auf**ge**standen, ein**ge**kauft. **Ohne ge-:** Verben auf **-ieren** (studiert) und mit untrennbarer Vorsilbe be-/ver-/er-… (besucht, verstanden).","**sein** bei Bewegung (fahren, gehen, fliegen, kommen) und Veränderung (aufstehen, einschlafen, werden) + sein, bleiben, passieren. Sonst **haben**."],"use":"Prüfung: Erfahrungen erzählen („Ich habe schon … gemacht“), Wochenende, Reisen.","table":[["Typ","Infinitiv","Perfekt"],["regelmäßig","machen","Ich **habe** Sport **gemacht**."],["unregelmäßig","essen","Wir **haben** Pizza **gegessen**."],["trennbar","einkaufen","Er **hat** **eingekauft**."],["-ieren","telefonieren","Sie **hat** lange **telefoniert**."],["untrennbar","besuchen","Ich **habe** Oma **besucht**."],["sein: Bewegung","fahren","Wir **sind** nach Potsdam **gefahren**."],["sein: Veränderung","aufstehen","Ich **bin** spät **aufgestanden**."]],"examples":[{"de":"Am Wochenende habe ich viel gelesen.","en":"At the weekend I read a lot."},{"de":"Wir sind in den Park gegangen.","en":"We went to the park."},{"de":"Hast du schon gegessen?","en":"Have you eaten already?"},{"de":"Ravi ist nach Potsdam gefahren.","en":"Ravi went to Potsdam."},{"de":"Ich habe dich gestern angerufen.","en":"I called you yesterday."},{"de":"Leila hat in Teheran Medizin studiert.","en":"Leila studied medicine in Tehran."},{"de":"Was ist passiert?","en":"What happened?"},{"de":"Ich habe die Frage nicht verstanden.","en":"I didn't understand the question."},{"de":"Max ist beim Film eingeschlafen.","en":"Max fell asleep during the film."},{"de":"Seid ihr schon mal geflogen?","en":"Have you ever flown?"}],"vocab":[{"de":"gestern / vorgestern","en":"yesterday / day before yesterday"},{"de":"letzte Woche","en":"last week"},{"de":"schon / noch nicht","en":"already / not yet"},{"de":"der Ausflug, ¨e","en":"trip, outing"},{"de":"spazieren gehen","en":"to go for a walk"},{"de":"das Picknick, -s","en":"picnic"},{"de":"der See, -n","en":"lake"},{"de":"passieren","en":"to happen"},{"de":"erleben","en":"to experience"},{"de":"fotografieren","en":"to take photos"},{"de":"grillen","en":"to barbecue"},{"de":"Spaß machen","en":"to be fun"}],"reading":"Letztes Wochenende hat Ravi viel erlebt. Am Samstag ist er früh aufgestanden und mit Leila und Jonas nach Potsdam gefahren. Sie haben ein Picknick am See gemacht und viel fotografiert. Jonas hat Würstchen gegrillt, aber Ravi hat nur Gemüse gegessen. Am Nachmittag sind sie im Park spazieren gegangen. Am Sonntag hat Ravi seine Eltern angerufen und ihnen alles erzählt. Am Abend ist er vor dem Fernseher eingeschlafen.","tasks":[{"q":"Ich ___ gestern Fußball ___. (spielen)","a":"habe / gespielt"},{"q":"Wir ___ nach Hamburg ___. (fahren)","a":"sind / gefahren"},{"q":"Anna ___ ein Buch ___. (lesen)","a":"hat / gelesen"},{"q":"___ du schon ___? (frühstücken)","a":"Hast / gefrühstückt"},{"q":"Er ___ um 6 Uhr ___. (aufstehen)","a":"ist / aufgestanden"},{"q":"Ich ___ im Supermarkt ___. (einkaufen)","a":"habe / eingekauft"},{"q":"Sie ___ in Köln ___. (studieren)","a":"hat / studiert"},{"q":"[Mix] Ich ___ meiner Mutter Blumen ___. (schenken)","a":"habe / geschenkt"},{"q":"[Mix] Wir ___ in den Park ___. (gehen)","a":"sind / gegangen"},{"q":"[Mix] Wo hast du den Schlüssel hingelegt? – Ich habe ihn auf ___ Tisch gelegt.","a":"den"}],"exam":[{"q":"Wohin ist Ravi am Samstag gefahren?","a":"Nach Potsdam."},{"q":"Was hat Jonas gemacht?","a":"Er hat Würstchen gegrillt."},{"q":"Wen hat Ravi am Sonntag angerufen?","a":"Seine Eltern."},{"q":"Perfekt: Ich trinke Kaffee.","a":"Ich habe Kaffee getrunken."},{"q":"Perfekt: Er kommt spät nach Hause.","a":"Er ist spät nach Hause gekommen."},{"q":"Perfekt: Wir verstehen alles.","a":"Wir haben alles verstanden."},{"q":"haben oder sein? Ich ___ zu Hause geblieben.","a":"bin"},{"q":"Was haben Sie letztes Wochenende gemacht? (8 Sätze)","a":""},{"q":"Erzählen Sie von Ihrer schönsten Reise.","a":""},{"q":"Was haben Sie in Deutschland zum ersten Mal gemacht?","a":""}],"speak":["Was haben die Leute im Park gemacht? __Der Mann ist gejoggt …__","Erzähl die Geschichte vom Hund: Was ist passiert?","Was hast du gestern gemacht? Mindestens 6 Verben im Perfekt.","Frag deinen Partner: __Bist du schon mal …? Hast du schon mal …?__"]},{"n":18,"level":"A2","title":"Präteritum von sein, haben und Modalverben","theme":"Früher und heute","scene":"family","rec":[1,8,11,17],"expl":["Beim Sprechen benutzt man für **sein, haben** und **Modalverben** fast immer das **Präteritum** (nicht das Perfekt): __Ich **war** krank.__ (statt: Ich bin krank gewesen.)","**sein:** war, warst, war, waren, wart, waren. **haben:** hatte, hattest, hatte, hatten, hattet, hatten.","**Modalverben:** Stamm ohne Umlaut + **-te**: konnte, musste, durfte, wollte, sollte. **möchten → wollte**.","Auch häufig: **es gab** (there was), **wusste** (wissen)."],"use":"Über die Kindheit, früher und heute sprechen; Entschuldigungen: __Ich konnte nicht kommen, ich hatte keine Zeit.__","table":[["Person","sein","haben","können","müssen","wollen","dürfen"],["ich","war","hatte","konnte","musste","wollte","durfte"],["du","warst","hattest","konntest","musstest","wolltest","durftest"],["er/sie/es","war","hatte","konnte","musste","wollte","durfte"],["wir","waren","hatten","konnten","mussten","wollten","durften"],["ihr","wart","hattet","konntet","musstet","wolltet","durftet"],["sie/Sie","waren","hatten","konnten","mussten","wollten","durften"]],"examples":[{"de":"Gestern war ich müde.","en":"Yesterday I was tired."},{"de":"Als Kind hatte ich einen Hund.","en":"As a child I had a dog."},{"de":"Ich konnte nicht kommen.","en":"I couldn't come."},{"de":"Wir mussten lange warten.","en":"We had to wait a long time."},{"de":"Früher wollte ich Pilot werden.","en":"I used to want to be a pilot."},{"de":"Als Kinder durften wir nicht allein ausgehen.","en":"As children we weren't allowed out alone."},{"de":"Wo warst du?","en":"Where were you?"},{"de":"Früher gab es kein Internet.","en":"In the past there was no internet."},{"de":"Hattet ihr einen schönen Urlaub?","en":"Did you have a nice holiday?"},{"de":"Ich wusste das nicht.","en":"I didn't know that."}],"vocab":[{"de":"früher","en":"in the past"},{"de":"heute","en":"today, nowadays"},{"de":"die Kindheit","en":"childhood"},{"de":"als Kind","en":"as a child"},{"de":"die Schule, -n","en":"school"},{"de":"der Lehrer, -","en":"teacher"},{"de":"streng","en":"strict"},{"de":"das Dorf, ¨er","en":"village"},{"de":"die Großstadt, ¨e","en":"big city"},{"de":"es gab","en":"there was / were"},{"de":"werden (wurde)","en":"to become"},{"de":"damals","en":"back then"}],"reading":"Ravis Vater erzählt am Telefon: „Früher war alles anders. Als Kind hatte ich kein eigenes Zimmer. Wir waren sechs Kinder. Wir wollten immer draußen spielen, aber wir mussten zuerst unseren Eltern helfen. Es gab kein Handy und keinen Fernseher. Mein Lehrer war sehr streng. Ich durfte nie zu spät kommen.“ Ravi sagt: „Heute habe ich ein Handy, eine Wohnung und keine strengen Lehrer. Aber ich konnte als Kind auch nicht so viel spielen!“","tasks":[{"q":"Gestern ___ ich krank. (sein)","a":"war"},{"q":"Wir ___ keine Zeit. (haben)","a":"hatten"},{"q":"Ich ___ nicht kommen. (können)","a":"konnte"},{"q":"Er ___ lange arbeiten. (müssen)","a":"musste"},{"q":"___ du gestern im Kurs? (sein)","a":"Warst"},{"q":"Als Kind ___ ich nicht fernsehen. (dürfen)","a":"durfte"},{"q":"Ihr ___ ins Kino gehen, oder? (wollen)","a":"wolltet"},{"q":"[Mix] Früher ___ es hier keinen Supermarkt. (geben)","a":"gab"},{"q":"[Mix] Letztes Jahr ___ ich nach Indien geflogen.","a":"bin"},{"q":"[Mix] Als Kind ___ meine Schwester ___ Katze. (haben, eine)","a":"hatte / eine"}],"exam":[{"q":"Wie viele Kinder waren sie in der Familie von Ravis Vater?","a":"Sechs."},{"q":"Was mussten die Kinder zuerst machen?","a":"Den Eltern helfen."},{"q":"Wie war der Lehrer?","a":"Sehr streng."},{"q":"Präteritum: Ich bin im Urlaub.","a":"Ich war im Urlaub."},{"q":"Präteritum: Wir müssen früh aufstehen.","a":"Wir mussten früh aufstehen."},{"q":"Präteritum: Hast du Glück?","a":"Hattest du Glück?"},{"q":"Präteritum: Sie können gut schwimmen.","a":"Sie konnten gut schwimmen."},{"q":"Wie war Ihre Kindheit? Was durften / mussten Sie machen?","a":""},{"q":"Früher und heute: Was ist in Ihrer Stadt anders?","a":""},{"q":"Sie waren nicht im Kurs. Entschuldigen Sie sich und erklären Sie warum.","a":""}],"speak":["Stell dir vor, das ist die Familie vor 30 Jahren. Wie war das Leben?","Was durftest du als Kind nicht? Was musstest du machen?","Vergleiche: __Früher hatten wir … heute haben wir …__","Was wolltest du als Kind werden?"]},{"n":19,"level":"A2","title":"Reflexive Verben","theme":"Gesundheit und Körper","scene":"doctor","rec":[12,13,17,18],"expl":["Bei **reflexiven Verben** zeigt ein **Reflexivpronomen** zurück auf das Subjekt: __Ich wasche **mich**.__","**Akkusativ** (normal): mich, dich, **sich**, uns, euch, **sich**.","**Dativ**, wenn es schon ein Akkusativ-Objekt gibt: __Ich wasche **mir** die Hände. Ich putze **mir** die Zähne.__ (mir, dir, sich, uns, euch, sich)","Viele reflexive Verben haben eine feste **Präposition**: sich freuen **auf/über**, sich interessieren **für**, sich ärgern **über**, sich kümmern **um**. Im Perfekt immer **haben**: __Ich habe mich gefreut.__"],"use":"Gefühle, Körperpflege, Gesundheit, Interessen ausdrücken.","table":[["Person","Akkusativ","Dativ","Beispiel"],["ich","mich","mir","Ich ziehe **mich** an. / Ich ziehe **mir** die Jacke an."],["du","dich","dir","Beeil **dich**! / Wasch **dir** die Hände!"],["er/sie/es","sich","sich","Er rasiert **sich**."],["wir","uns","uns","Wir treffen **uns** um 8."],["ihr","euch","euch","Habt ihr **euch** erholt?"],["sie/Sie","sich","sich","Setzen Sie **sich** bitte!"]],"examples":[{"de":"Ich fühle mich nicht gut.","en":"I don't feel well."},{"de":"Du musst dich ausruhen.","en":"You must rest."},{"de":"Ich putze mir zweimal am Tag die Zähne.","en":"I brush my teeth twice a day."},{"de":"Ravi hat sich erkältet.","en":"Ravi has caught a cold."},{"de":"Wir freuen uns auf den Urlaub.","en":"We're looking forward to the holiday."},{"de":"Interessierst du dich für Sport?","en":"Are you interested in sport?"},{"de":"Setzen Sie sich bitte!","en":"Please sit down."},{"de":"Ich habe mich über das Geschenk gefreut.","en":"I was happy about the present."},{"de":"Beeil dich, der Bus kommt!","en":"Hurry up, the bus is coming!"},{"de":"Er kümmert sich um seine Mutter.","en":"He takes care of his mother."}],"vocab":[{"de":"sich fühlen","en":"to feel"},{"de":"sich erkälten","en":"to catch a cold"},{"de":"sich ausruhen","en":"to rest"},{"de":"sich waschen","en":"to wash (oneself)"},{"de":"sich die Zähne putzen","en":"to brush one's teeth"},{"de":"sich anziehen","en":"to get dressed"},{"de":"sich beeilen","en":"to hurry"},{"de":"sich freuen auf / über","en":"to look forward to / be happy about"},{"de":"sich interessieren für","en":"to be interested in"},{"de":"sich ärgern über","en":"to be annoyed about"},{"de":"sich kümmern um","en":"to take care of"},{"de":"sich erholen","en":"to recover"}],"reading":"Nach dem Ausflug hat sich Ravi erkältet. Er fühlt sich schlecht und muss sich ausruhen. Die Ärztin sagt: „Setzen Sie sich bitte. Waschen Sie sich oft die Hände und ziehen Sie sich warm an.“ Ravi ärgert sich: Am Samstag wollte er zum Konzert gehen. Er hatte sich so darauf gefreut! Aber Leila kümmert sich um ihn und bringt ihm Tee. Nach vier Tagen hat er sich erholt und freut sich auf das nächste Wochenende.","tasks":[{"q":"Ich fühle ___ nicht gut.","a":"mich"},{"q":"Wasch ___ die Hände! (du)","a":"dir"},{"q":"Er hat ___ erkältet.","a":"sich"},{"q":"Wir treffen ___ im Café.","a":"uns"},{"q":"Ich putze ___ die Zähne.","a":"mir"},{"q":"Interessierst du ___ für Musik?","a":"dich"},{"q":"Setzen Sie ___!","a":"sich"},{"q":"[Mix] Perfekt: Ich freue mich über den Brief.","a":"Ich habe mich über den Brief gefreut."},{"q":"[Mix] Ihr müsst ___ beeilen!","a":"euch"},{"q":"[Mix] Imperativ (du): sich warm anziehen","a":"Zieh dich warm an!"}],"exam":[{"q":"Warum geht Ravi zur Ärztin?","a":"Er hat sich erkältet."},{"q":"Warum ärgert sich Ravi?","a":"Er kann nicht zum Konzert gehen."},{"q":"Wer kümmert sich um Ravi?","a":"Leila."},{"q":"Ergänze: Ich ziehe ___ die Schuhe an.","a":"mir"},{"q":"Ergänze: Anna freut ___ ___ den Sommer.","a":"sich / auf"},{"q":"Ergänze: Kümmerst du ___ ___ die Katze?","a":"dich / um"},{"q":"Perfekt: Wir erholen uns gut.","a":"Wir haben uns gut erholt."},{"q":"Was machen Sie, wenn Sie sich nicht gut fühlen?","a":""},{"q":"Worauf freuen Sie sich? Worüber ärgern Sie sich?","a":""},{"q":"Wofür interessieren Sie sich? Erzählen Sie.","a":""}],"speak":["Wie fühlt sich der Patient? Was sagt die Ärztin?","Was macht man jeden Morgen? __Ich wasche mich, ich putze mir …__","Worüber freust du dich diese Woche?","Rollenspiel beim Arzt: __Ich fühle mich … Ich habe mich …__"]},{"n":20,"level":"A2","title":"Konjunktionen: und, aber, oder, denn, sondern","theme":"Freizeit und Meinung","scene":"park","rec":[3,7,17,19],"expl":["Diese Konjunktionen stehen auf **Position 0** – sie zählen nicht mit. Danach kommt ein **normaler Hauptsatz** (Verb auf Position 2).","**und** (and), **aber** (but), **oder** (or), **denn** (because – wie weil, aber mit Hauptsatz!), **sondern** (but rather – nur nach Negation).","Vor aber, denn, sondern steht ein **Komma**. Bei und/oder kann das Subjekt wegfallen: __Ich gehe nach Hause und (ich) koche.__","Merke **ADUSO**: aber, denn, und, sondern, oder."],"use":"Sätze verbinden, Gründe geben, Kontraste zeigen – mehr Punkte für „Kohärenz“ in der Prüfung.","table":[["Satz 1","Pos. 0","Pos. 1","Pos. 2","Rest"],["Ich bleibe zu Hause,","denn","ich","bin","krank."],["Ich mag Tee,","aber","Kaffee","trinke","ich nicht."],["Gehen wir ins Kino","oder","bleiben","wir","zu Hause? (Frage)"],["Er fährt nicht mit dem Bus,","sondern","er","geht","zu Fuß."],["Ich koche","und","du","deckst","den Tisch."]],"examples":[{"de":"Ich gehe joggen, denn ich will fit bleiben.","en":"I go jogging because I want to stay fit."},{"de":"Das Wetter ist schön, aber es ist kalt.","en":"The weather is nice but it's cold."},{"de":"Spielen wir Tennis oder gehen wir schwimmen?","en":"Shall we play tennis or go swimming?"},{"de":"Ich wohne nicht in München, sondern in Berlin.","en":"I don't live in Munich but in Berlin."},{"de":"Ravi kocht und Leila macht den Salat.","en":"Ravi cooks and Leila makes the salad."},{"de":"Ich habe keine Zeit, denn ich muss arbeiten.","en":"I have no time because I have to work."},{"de":"Er ist müde, aber er geht noch ins Kino.","en":"He's tired but still goes to the cinema."},{"de":"Wir sind nicht gefahren, sondern (wir sind) gelaufen.","en":"We didn't drive, we walked."},{"de":"Ich mag Yoga, denn es entspannt mich.","en":"I like yoga because it relaxes me."},{"de":"Möchtest du Wasser oder lieber Saft?","en":"Would you like water or rather juice?"}],"vocab":[{"de":"die Freizeit","en":"free time"},{"de":"das Fitnessstudio, -s","en":"gym"},{"de":"joggen","en":"to jog"},{"de":"das Yoga","en":"yoga"},{"de":"wandern","en":"to hike"},{"de":"fit / entspannt","en":"fit / relaxed"},{"de":"die Mannschaft, -en","en":"team"},{"de":"der Verein, -e","en":"club"},{"de":"das Konzert, -e","en":"concert"},{"de":"langweilig / spannend","en":"boring / exciting"},{"de":"lieber","en":"rather"},{"de":"die Meinung, -en","en":"opinion"}],"reading":"Ravi und Leila sprechen über ihre Freizeit. Ravi joggt dreimal pro Woche, denn er will fit bleiben. Er möchte auch in einen Cricket-Verein gehen, aber in Berlin gibt es nicht viele. Leila macht kein Joggen, sondern Yoga. Sie sagt: „Yoga ist nicht langweilig, sondern sehr entspannend.“ Am Wochenende wandern sie zusammen oder sie gehen auf ein Konzert. Letzten Samstag waren sie im Konzert, aber Ravi ist fast eingeschlafen!","tasks":[{"q":"Ich lerne Deutsch, ___ ich will hier arbeiten.","a":"denn"},{"q":"Das Essen ist gut, ___ teuer.","a":"aber"},{"q":"Trinkst du Tee ___ Kaffee?","a":"oder"},{"q":"Er ist nicht Arzt, ___ Lehrer.","a":"sondern"},{"q":"Verbinde mit denn: Ich bleibe zu Hause. Ich bin müde.","a":"Ich bleibe zu Hause, denn ich bin müde."},{"q":"Verbinde mit aber: Ich möchte kommen. Ich habe keine Zeit.","a":"Ich möchte kommen, aber ich habe keine Zeit."},{"q":"Fehler? „…, denn ich bin müde bin.“","a":"…, denn ich bin müde."},{"q":"[Mix] Ich habe nicht gekocht, ___ ich ___ im Restaurant ___. (sondern, essen – Perfekt)","a":"sondern / habe / gegessen"},{"q":"[Mix] Leila ärgert ___, denn der Bus ___ zu spät. (sich, kommen)","a":"sich / kommt"},{"q":"[Mix] Ich wollte kommen, aber ich ___ nicht. (können, Präteritum)","a":"konnte"}],"exam":[{"q":"Warum joggt Ravi?","a":"Er will fit bleiben."},{"q":"Was macht Leila?","a":"Yoga."},{"q":"Was ist beim Konzert passiert?","a":"Ravi ist fast eingeschlafen."},{"q":"Verbinde mit sondern: Ich trinke keinen Wein. Ich trinke Saft.","a":"Ich trinke keinen Wein, sondern Saft."},{"q":"Verbinde mit oder: Wir gehen ins Kino. Wir bleiben zu Hause.","a":"Wir gehen ins Kino oder (wir) bleiben zu Hause."},{"q":"Verbinde mit denn: Er kommt nicht. Er ist krank.","a":"Er kommt nicht, denn er ist krank."},{"q":"Ergänze: Das ist nicht mein Handy, ___ deins.","a":"sondern"},{"q":"Was machen Sie in der Freizeit und warum? (mit denn, aber)","a":""},{"q":"Ist Sport wichtig für Sie? Begründen Sie Ihre Meinung.","a":""},{"q":"Sie möchten mit Ihrem Partner etwas unternehmen. Machen Sie zwei Vorschläge (oder).","a":""}],"speak":["Was machen die Leute im Park und warum? (mit denn)","Möchtest du lieber joggen oder auf der Bank sitzen? Warum?","Beschreibe das Bild mit und / aber / oder.","Was ist besser: Sport allein oder in der Gruppe?"]},{"n":21,"level":"A2","title":"Nebensätze mit weil, dass, wenn, ob","theme":"Arbeit und Beruf","scene":"office","rec":[11,17,18,20],"expl":["Im **Nebensatz** steht das **konjugierte Verb am Ende**: __…, **weil** ich müde **bin**.__","**weil** = Grund (because). **dass** = Inhalt nach Verben wie denken, glauben, finden, wissen, hoffen, sagen. **wenn** = Bedingung (if) / Wiederholung (whenever). **ob** = indirekte Ja/Nein-Frage (whether).","Mit Modalverb / Perfekt: Hilfsverb ganz am Ende: __…, weil ich arbeiten **muss** / weil ich lange gearbeitet **habe**.__ Trennbare Verben zusammen: __…, wenn ich früh **aufstehe**.__","**Nebensatz zuerst** → Hauptsatz beginnt mit **Verb**: __Wenn ich Zeit habe, **komme** ich.__"],"use":"In der Prüfung: Meinung (Ich finde, dass…), Gründe (weil…), Bedingungen (wenn…). Sehr wichtig!","table":[["Hauptsatz","Konj.","Subjekt","Mitte","Verb (Ende)"],["Ich komme nicht,","weil","ich","keine Zeit","habe."],["Ich glaube,","dass","er","heute","kommt."],["Ich weiß nicht,","ob","der Chef","heute im Büro","ist."],["Ich rufe dich an,","wenn","ich","morgen früh","aufstehe."],["Ravi ist müde,","weil","er","lange","gearbeitet hat."],["—","Wenn","ich","Zeit","habe, **komme** ich."]],"examples":[{"de":"Ich lerne Deutsch, weil ich hier arbeiten möchte.","en":"I learn German because I'd like to work here."},{"de":"Ich finde, dass die Arbeit interessant ist.","en":"I think the work is interesting."},{"de":"Wenn ich Zeit habe, gehe ich schwimmen.","en":"When I have time, I go swimming."},{"de":"Weißt du, ob Jonas heute kommt?","en":"Do you know whether Jonas is coming today?"},{"de":"Ravi hofft, dass er die Stelle bekommt.","en":"Ravi hopes he gets the job."},{"de":"Ich bin müde, weil ich spät eingeschlafen bin.","en":"I'm tired because I fell asleep late."},{"de":"Wenn es regnet, nehme ich die U-Bahn.","en":"If it rains, I take the underground."},{"de":"Die Chefin fragt, ob wir morgen arbeiten können.","en":"The boss asks whether we can work tomorrow."},{"de":"Es ist wichtig, dass man pünktlich ist.","en":"It's important to be punctual."},{"de":"Weil der Zug Verspätung hatte, bin ich zu spät gekommen.","en":"Because the train was late, I came late."}],"vocab":[{"de":"die Stelle, -n","en":"job, position"},{"de":"sich bewerben","en":"to apply"},{"de":"die Bewerbung, -en","en":"application"},{"de":"das Vorstellungsgespräch, -e","en":"job interview"},{"de":"der Lebenslauf, ¨e","en":"CV"},{"de":"die Erfahrung, -en","en":"experience"},{"de":"verdienen","en":"to earn"},{"de":"das Gehalt, ¨er","en":"salary"},{"de":"die Überstunde, -n","en":"overtime"},{"de":"der Vertrag, ¨e","en":"contract"},{"de":"kündigen","en":"to quit"},{"de":"hoffen","en":"to hope"}],"reading":"Jonas erzählt Ravi, dass er eine neue Stelle sucht. „Ich möchte wechseln, weil ich zu viele Überstunden mache.“ Ravi fragt, ob er schon eine Bewerbung geschrieben hat. „Ja, und ich hoffe, dass ich bald ein Vorstellungsgespräch habe.“ Ravi sagt: „Wenn du Hilfe beim Lebenslauf brauchst, sag Bescheid. Aber ich finde es schade, dass du gehst!“ Jonas lacht: „Keine Sorge. Wenn ich die Stelle bekomme, lade ich dich zum Essen ein.“","tasks":[{"q":"Ich komme nicht, weil ich krank ___. (sein)","a":"bin"},{"q":"Ich glaube, dass er Recht ___. (haben)","a":"hat"},{"q":"Ich weiß nicht, ___ sie verheiratet ist.","a":"ob"},{"q":"___ ich Hunger habe, esse ich.","a":"Wenn"},{"q":"Verbinde mit weil: Ich bleibe zu Hause. Ich muss lernen.","a":"Ich bleibe zu Hause, weil ich lernen muss."},{"q":"Verbinde mit dass: Ich finde. Deutsch ist schwer.","a":"Ich finde, dass Deutsch schwer ist."},{"q":"Verbinde (Nebensatz zuerst): wenn / das Wetter schön ist / wir gehen in den Park","a":"Wenn das Wetter schön ist, gehen wir in den Park."},{"q":"[Mix] Er ist müde, weil er gestern spät ___ ___. (einschlafen, Perfekt)","a":"eingeschlafen ist"},{"q":"[Mix] Weißt du, ob er ___ ___ hilft? (wir, Dativ)","a":"uns"},{"q":"[Mix] denn → weil: Ich komme nicht, denn ich habe keine Zeit.","a":"Ich komme nicht, weil ich keine Zeit habe."}],"exam":[{"q":"Warum will Jonas wechseln?","a":"Weil er zu viele Überstunden macht."},{"q":"Was hofft Jonas?","a":"Dass er bald ein Vorstellungsgespräch hat."},{"q":"Was macht Jonas, wenn er die Stelle bekommt?","a":"Er lädt Ravi zum Essen ein."},{"q":"Indirekte Frage: „Kommst du morgen?“ → Ich frage dich, …","a":"ob du morgen kommst."},{"q":"Verbinde: Ich bin froh. Du bist hier. (dass)","a":"Ich bin froh, dass du hier bist."},{"q":"Verbinde: Ich kann nicht kommen. Ich muss arbeiten. (weil)","a":"Ich kann nicht kommen, weil ich arbeiten muss."},{"q":"Beginne mit „Wenn“: Ich trinke Tee, wenn ich krank bin.","a":"Wenn ich krank bin, trinke ich Tee."},{"q":"Was ist Ihnen bei der Arbeit wichtig? (Ich finde es wichtig, dass …)","a":""},{"q":"Warum lernen Sie Deutsch? Nennen Sie 3 Gründe mit weil.","a":""},{"q":"Was machen Sie, wenn Sie Stress bei der Arbeit haben?","a":""}],"speak":["Warum arbeiten die zwei zusammen? __Ich glaube, dass …__","Was machst du, wenn du im Büro müde bist?","Ist Homeoffice gut? __Ich finde, dass … weil …__","Frag den Partner indirekt: __Ich möchte wissen, ob …__"]},{"n":22,"level":"A2","title":"Komparativ und Superlativ","theme":"Vergleichen: Städte und Wohnen","scene":"city","rec":[5,17,20,21],"expl":["**Komparativ:** Adjektiv + **-er** (+ **als**): __Berlin ist groß**er als** München.__ Gleichheit: **so … wie**: __so groß wie__.","**Superlativ:** **am** + Adjektiv + **-sten**: __am schönsten__. Vor Nomen: __der schönst**e** Park__.","Einsilbige Adjektive mit a/o/u bekommen oft **Umlaut**: alt → älter → am ältesten, groß → größer → am größten.","**Unregelmäßig:** gut – besser – am besten · viel – mehr – am meisten · gern – lieber – am liebsten · hoch – höher – am höchsten · nah – näher – am nächsten."],"use":"Prüfung Teil 2: Vorteile/Nachteile, Heimatland vergleichen. Bilder vergleichen.","table":[["Grundform","Komparativ","Superlativ","Beispiel"],["klein","kleiner","am kleinsten","Mein Zimmer ist kleiner als deins."],["alt","älter","am ältesten","Mumbai ist älter als …"],["teuer","teurer","am teuersten","München ist am teuersten."],["gut","besser","am besten","Tee finde ich besser als Kaffee."],["viel","mehr","am meisten","In Mumbai wohnen mehr Menschen."],["gern","lieber","am liebsten","Am liebsten fahre ich Rad."]],"examples":[{"de":"Berlin ist kleiner als Mumbai.","en":"Berlin is smaller than Mumbai."},{"de":"Im Sommer ist es in Mumbai heißer als in Berlin.","en":"In summer it's hotter in Mumbai than in Berlin."},{"de":"Die Miete ist hier nicht so hoch wie in München.","en":"The rent here isn't as high as in Munich."},{"de":"Das Fahrrad ist schneller als der Bus.","en":"The bike is faster than the bus."},{"de":"Ich trinke lieber Chai als Kaffee.","en":"I prefer chai to coffee."},{"de":"Am liebsten esse ich Biryani.","en":"Most of all I like eating biryani."},{"de":"Das ist das beste Restaurant in der Stadt.","en":"That's the best restaurant in town."},{"de":"Welche Stadt findest du am schönsten?","en":"Which city do you find most beautiful?"},{"de":"Heute arbeite ich mehr als gestern.","en":"Today I'm working more than yesterday."},{"de":"Der Bahnhof ist näher, als ich dachte.","en":"The station is closer than I thought."}],"vocab":[{"de":"die Stadt, ¨e","en":"city"},{"de":"das Land","en":"countryside"},{"de":"laut / ruhig","en":"loud / quiet"},{"de":"teuer / billig (günstig)","en":"expensive / cheap"},{"de":"sauber / schmutzig","en":"clean / dirty"},{"de":"modern / alt","en":"modern / old"},{"de":"schnell / langsam","en":"fast / slow"},{"de":"der Verkehr","en":"traffic"},{"de":"die Luft","en":"air"},{"de":"die Einwohner (Pl.)","en":"inhabitants"},{"de":"der Vorteil / der Nachteil","en":"advantage / disadvantage"},{"de":"vergleichen","en":"to compare"}],"reading":"Leila fragt Ravi: „Wo lebst du lieber, in Mumbai oder in Berlin?“ Ravi denkt nach: „Mumbai ist größer und lauter als Berlin. Dort wohnen viel mehr Menschen. In Berlin ist die Luft sauberer und der Verkehr ist nicht so schlimm wie in Mumbai. Aber das Essen in Mumbai ist am besten! Und im Winter ist Berlin viel kälter.“ Leila lacht: „Also, was magst du am liebsten?“ – „Am liebsten wohne ich in Berlin und esse in Mumbai!“","tasks":[{"q":"Berlin ist ___ als Hamburg. (groß)","a":"größer"},{"q":"Der Zug ist ___ als das Auto. (schnell)","a":"schneller"},{"q":"Mein Bruder ist so ___ wie ich. (alt)","a":"alt"},{"q":"Ich trinke ___ Tee als Kaffee. (gern)","a":"lieber"},{"q":"Das ist das ___ Hotel. (gut, Superlativ)","a":"beste"},{"q":"Im Juli ist es am ___. (heiß)","a":"heißesten"},{"q":"Hier ist es nicht so ___ wie in München. (teuer)","a":"teuer"},{"q":"[Mix] Ich finde, dass Berlin ___ ist als Köln. (interessant)","a":"interessanter"},{"q":"[Mix] Früher war die Miete ___ als heute. (niedrig)","a":"niedriger"},{"q":"[Mix] Ich fahre lieber mit ___ Rad, denn es ist ___. (das, schnell – Komparativ)","a":"dem / schneller"}],"exam":[{"q":"Welche Stadt ist lauter?","a":"Mumbai."},{"q":"Wo ist die Luft sauberer?","a":"In Berlin."},{"q":"Wo ist das Essen am besten (für Ravi)?","a":"In Mumbai."},{"q":"Vergleiche: Zug / Bus / schnell","a":"Der Zug ist schneller als der Bus."},{"q":"Superlativ: Das Wetter ist im Mai ___ (schön).","a":"am schönsten"},{"q":"Ergänze: Ich esse ___ (viel) Reis als Brot.","a":"mehr"},{"q":"Ergänze: Sie spricht so gut ___ ein Deutscher.","a":"wie"},{"q":"Vergleichen Sie Ihre Heimatstadt mit Ihrer Stadt in Deutschland.","a":""},{"q":"Stadt oder Land: Wo lebt man besser? Nennen Sie Vor- und Nachteile.","a":""},{"q":"Was ist Ihr liebstes Essen, Ihr liebster Ort, Ihre liebste Jahreszeit?","a":""}],"speak":["Vergleiche die Häuser: __Das rote Haus ist kleiner als …__","Was ist schneller: der Bus oder der Mann zu Fuß?","Vergleiche Berlin und deine Stadt (5 Sätze).","Was machst du am liebsten in einer Stadt?"]},{"n":23,"level":"A2","title":"Adjektivdeklination (Endungen)","theme":"Kleidung und Aussehen","scene":"shop","rec":[5,6,13,14,22],"expl":["Steht ein Adjektiv **vor einem Nomen**, bekommt es eine Endung. Nach **sein** hat es **keine** Endung: __Die Jacke ist **blau**.__ aber __die blau**e** Jacke__.","**Typ 1 (der/die/das):** nur -e oder -en. Nominativ Singular + Akkusativ fem./neutr. = **-e**, sonst **-en**.","**Typ 2 (ein/kein/mein):** wie Typ 1, aber wo „ein“ keine Endung hat: mask. Nom. **-er**, neutr. Nom./Akk. **-es**.","**Typ 3 (ohne Artikel):** Das Adjektiv zeigt den Fall wie der Artikel: kalt**er** Kaffee, heiß**e** Suppe, frisch**es** Brot. Siehe Referenz 2."],"use":"Kleidung, Personen, Dinge, Bilder beschreiben – macht dein Deutsch genauer.","table":[["Fall","mask.","fem.","neutr.","Plural"],["Nom. (der)","der rote Pulli","die rote Jacke","das rote Hemd","die roten Schuhe"],["Akk. (der)","den rot**en** Pulli","die rote Jacke","das rote Hemd","die roten Schuhe"],["Dat. (der)","dem rot**en** Pulli","der rot**en** Jacke","dem rot**en** Hemd","den rot**en** Schuhen"],["Nom. (ein)","ein rot**er** Pulli","eine rote Jacke","ein rot**es** Hemd","rote Schuhe"],["Akk. (ein)","einen rot**en** Pulli","eine rote Jacke","ein rot**es** Hemd","rote Schuhe"],["Dat. (ein)","einem rot**en** Pulli","einer rot**en** Jacke","einem rot**en** Hemd","rot**en** Schuhen"]],"examples":[{"de":"Ich suche eine warme Jacke.","en":"I'm looking for a warm jacket."},{"de":"Der blaue Pulli gefällt mir.","en":"I like the blue jumper."},{"de":"Hast du einen schwarzen Gürtel?","en":"Do you have a black belt?"},{"de":"Ravi trägt ein weißes Hemd.","en":"Ravi is wearing a white shirt."},{"de":"Mit dem neuen Mantel ist mir nicht kalt.","en":"With the new coat I'm not cold."},{"de":"Anna hat lange, braune Haare.","en":"Anna has long brown hair."},{"de":"Ich trinke gern heißen Tee.","en":"I like drinking hot tea."},{"de":"Die grünen Schuhe sind zu klein.","en":"The green shoes are too small."},{"de":"Das ist ein schönes Geschenk für meine kleine Schwester.","en":"That's a nice present for my little sister."},{"de":"Ich wohne in einer großen Wohnung.","en":"I live in a big flat."}],"vocab":[{"de":"die Kleidung","en":"clothes"},{"de":"die Hose, -n","en":"trousers"},{"de":"der Pullover (Pulli), -","en":"jumper"},{"de":"die Jacke, -n","en":"jacket"},{"de":"der Mantel, ¨","en":"coat"},{"de":"das Hemd, -en","en":"shirt"},{"de":"das Kleid, -er","en":"dress"},{"de":"der Schuh, -e","en":"shoe"},{"de":"anprobieren","en":"to try on"},{"de":"die Größe, -n","en":"size"},{"de":"tragen (trägt)","en":"to wear / carry"},{"de":"die Farbe, -n","en":"colour"}],"reading":"Der Winter kommt, und Ravi braucht warme Kleidung. Mit Anna geht er in ein großes Kaufhaus. „Ich suche einen dicken Mantel“, sagt er. Die Verkäuferin zeigt ihm einen schwarzen Mantel und einen blauen Mantel. Ravi probiert den blauen Mantel an. Anna sagt: „Die blaue Farbe steht dir gut!“ Er kauft auch warme Handschuhe und einen roten Schal. Mit der neuen Kleidung freut er sich sogar auf den kalten Berliner Winter.","tasks":[{"q":"Ich kaufe einen ___ Pulli. (warm)","a":"warmen"},{"q":"Das ist ein ___ Kleid. (schön)","a":"schönes"},{"q":"Die ___ Hose ist zu lang. (grau)","a":"graue"},{"q":"Ich suche den ___ Schal. (rot)","a":"roten"},{"q":"Er wohnt mit einer ___ Freundin zusammen. (nett)","a":"netten"},{"q":"Ich trinke ___ Kaffee. (schwarz, ohne Artikel)","a":"schwarzen"},{"q":"Das ist ein ___ Mann. (alt)","a":"alter"},{"q":"[Mix] Ich schenke meiner ___ Schwester einen ___ Rock. (klein, kurz)","a":"kleinen / kurzen"},{"q":"[Mix] Dieser Mantel ist ___ als der ___ Mantel. (warm – Komp., blau)","a":"wärmer / blaue"},{"q":"[Mix] Ich habe mir ___ ___ Schuhe gekauft. (neu, ohne Artikel, Pl.)","a":"neue"}],"exam":[{"q":"Was sucht Ravi?","a":"Einen dicken Mantel."},{"q":"Welchen Mantel probiert er an?","a":"Den blauen Mantel."},{"q":"Was kauft er noch?","a":"Warme Handschuhe und einen roten Schal."},{"q":"Ergänze: Ich brauche ___ neu___ Handy. (ein)","a":"ein neues"},{"q":"Ergänze: Wir wohnen in ___ klein___ Stadt. (eine)","a":"einer kleinen"},{"q":"Ergänze: Sie trägt ___ gelb___ Rock. (der, Akk.)","a":"den gelben"},{"q":"Ergänze: Mit gut___ Freunden ist alles leichter.","a":"guten"},{"q":"Beschreiben Sie, was Sie heute tragen.","a":""},{"q":"Beschreiben Sie eine Person aus Ihrer Familie genau.","a":""},{"q":"Sie kaufen im Geschäft eine Hose. Spielen Sie das Gespräch.","a":""}],"speak":["Beschreibe die Personen: __Der Mann trägt eine blaue …__","Was liegt in den Regalen? __Es gibt rote, grüne …__","Was ist dein Lieblingskleidungsstück?","Beschreibe dein Traumoutfit für eine Party."]},{"n":24,"level":"A2","title":"Zeit: seit, vor, nach, ab, bis + Reihenfolge (zuerst, dann, danach)","theme":"Reisen und Urlaub","scene":"station","rec":[9,15,17,18,21],"expl":["Temporale Präpositionen mit **Dativ**: **seit** (seit einem Jahr – dauert noch an, Präsens!), **vor** (vor zwei Tagen = ago), **nach** (nach dem Essen), **ab** (ab Montag), **bei** (beim Frühstück).","Mit **Akkusativ**: **für** (für eine Woche), **bis** (bis nächsten Freitag), **über** (über das Wochenende).","**Reihenfolge-Adverbien** (Position 1 → Inversion!): **zuerst, dann, danach, später, anschließend, am Ende / zum Schluss**.","Achtung: __Ich wohne **seit** drei Jahren hier__ (nicht: habe gewohnt)."],"use":"Reisen erzählen, Pläne machen, Präsentation strukturieren.","table":[["Präposition","Fall","Beispiel","English"],["seit","Dat.","seit einem Monat","for / since (still now)"],["vor","Dat.","vor einer Woche","ago"],["nach","Dat.","nach der Arbeit","after"],["ab","Dat.","ab nächster Woche","from … on"],["für","Akk.","für zwei Wochen","for (planned)"],["bis","Akk.","bis nächsten Montag","until"]],"examples":[{"de":"Ich lerne seit sechs Monaten Deutsch.","en":"I have been learning German for six months."},{"de":"Vor zwei Wochen war ich in Wien.","en":"Two weeks ago I was in Vienna."},{"de":"Nach dem Frühstück sind wir losgefahren.","en":"After breakfast we set off."},{"de":"Ab Montag habe ich Urlaub.","en":"From Monday I'm on holiday."},{"de":"Wir fahren für eine Woche an die Ostsee.","en":"We're going to the Baltic Sea for a week."},{"de":"Das Hotel ist bis Sonntag gebucht.","en":"The hotel is booked until Sunday."},{"de":"Zuerst haben wir den Dom besichtigt.","en":"First we visited the cathedral."},{"de":"Danach sind wir mit dem Schiff gefahren.","en":"After that we went by boat."},{"de":"Zum Schluss haben wir Sachertorte gegessen.","en":"Finally we ate Sachertorte."},{"de":"Beim Packen hört Ravi Musik.","en":"While packing Ravi listens to music."}],"vocab":[{"de":"der Urlaub, -e","en":"holiday"},{"de":"die Reise, -n","en":"journey"},{"de":"buchen","en":"to book"},{"de":"das Hotel, -s","en":"hotel"},{"de":"die Unterkunft, ¨e","en":"accommodation"},{"de":"packen","en":"to pack"},{"de":"besichtigen","en":"to visit (sights)"},{"de":"die Sehenswürdigkeit, -en","en":"sight"},{"de":"das Schiff, -e","en":"ship"},{"de":"der Strand, ¨e","en":"beach"},{"de":"das Gepäck","en":"luggage"},{"de":"anschließend","en":"subsequently"}],"reading":"Vor drei Wochen hat Ravi eine Reise nach Wien gemacht. Er hat für vier Tage ein Hotel gebucht. Zuerst ist er mit dem Zug nach Wien gefahren. Die Fahrt hat acht Stunden gedauert. Nach der Ankunft hat er sich ausgeruht. Am nächsten Tag hat er zuerst das Schloss Schönbrunn besichtigt, danach ist er in ein Café gegangen. Zum Schluss hat er eine Schifffahrt auf der Donau gemacht. Seit dieser Reise liebt er Wien. Ab Januar spart er für die nächste Reise.","tasks":[{"q":"Ich wohne ___ zwei Jahren in Berlin.","a":"seit"},{"q":"___ einer Woche war ich krank. (ago)","a":"Vor"},{"q":"___ dem Kurs gehe ich einkaufen. (after)","a":"Nach"},{"q":"Ich fahre ___ drei Tage nach Paris.","a":"für"},{"q":"Das Angebot gilt ___ Freitag. (until)","a":"bis"},{"q":"___ nächstem Monat arbeite ich Teilzeit. (from)","a":"Ab"},{"q":"Ordne: zuerst / wir / haben / gefrühstückt","a":"Zuerst haben wir gefrühstückt."},{"q":"[Mix] Danach ___ wir ins Museum ___. (gehen, Perfekt)","a":"sind / gegangen"},{"q":"[Mix] Seit ___ Umzug fühle ich ___ wohler. (mein, sich)","a":"meinem / mich"},{"q":"[Mix] Ich weiß nicht, ob das Hotel ___ Sonntag frei ___. (bis, sein)","a":"bis / ist"}],"exam":[{"q":"Wann war Ravi in Wien?","a":"Vor drei Wochen."},{"q":"Wie lange hat die Zugfahrt gedauert?","a":"Acht Stunden."},{"q":"Was hat er zum Schluss gemacht?","a":"Eine Schifffahrt auf der Donau."},{"q":"Ergänze: Ich warte ___ einer Stunde! (still waiting)","a":"seit"},{"q":"Ergänze: Wir haben uns ___ fünf Jahren kennengelernt. (ago)","a":"vor"},{"q":"Ergänze: ___ dem Essen putze ich mir die Zähne.","a":"Nach"},{"q":"Korrigiere: Ich habe seit 2023 in Berlin gewohnt (wohne immer noch).","a":"Ich wohne seit 2023 in Berlin."},{"q":"Erzählen Sie von Ihrer letzten Reise: zuerst, dann, danach, zum Schluss.","a":""},{"q":"Planen Sie einen Wochenendausflug mit Ihrem Partner.","a":""},{"q":"Wie lange lernen Sie schon Deutsch? Was war vor einem Jahr anders?","a":""}],"speak":["Wohin fahren die Leute? Wie lange bleiben sie? (Vermutung)","Erzähl eine Reise mit zuerst – dann – danach – zum Schluss.","Was packst du für eine Woche Urlaub ein?","Wo warst du vor einem Jahr? Seit wann bist du hier?"]},{"n":25,"level":"B1","title":"Konjunktiv II: würde, hätte, wäre, könnte","theme":"Wünsche und Träume","scene":"party","rec":[11,18,21,22],"expl":["Der **Konjunktiv II** drückt **Wünsche, Träume, irreale Situationen** und **Höflichkeit** aus.","Form: meistens **würde + Infinitiv**: __Ich **würde** gern reisen.__ Bei **sein, haben** und **Modalverben** nimmt man eigene Formen: **wäre, hätte, könnte, müsste, dürfte, sollte**.","**Irreale Bedingung:** __**Wenn** ich Zeit **hätte**, **würde** ich mehr Sport machen.__ (Ich habe keine Zeit.)","**Höflich:** __**Könnten** Sie mir helfen? Ich **hätte** gern einen Kaffee. **Wäre** es möglich, …?__"],"use":"Prüfung Teil 1: höflich vorschlagen. Teil 2: Wünsche/Meinung. Sehr häufig in B1!","table":[["Person","werden → würde","haben → hätte","sein → wäre","können → könnte"],["ich","würde","hätte","wäre","könnte"],["du","würdest","hättest","wär(e)st","könntest"],["er/sie/es","würde","hätte","wäre","könnte"],["wir","würden","hätten","wären","könnten"],["ihr","würdet","hättet","wär(e)t","könntet"],["sie/Sie","würden","hätten","wären","könnten"]],"examples":[{"de":"Ich würde gern eine Weltreise machen.","en":"I'd like to travel around the world."},{"de":"Wenn ich reich wäre, würde ich ein Haus am Meer kaufen.","en":"If I were rich, I'd buy a house by the sea."},{"de":"Könnten Sie das bitte wiederholen?","en":"Could you repeat that, please?"},{"de":"Ich hätte gern ein Glas Wasser.","en":"I'd like a glass of water."},{"de":"Wenn ich mehr Zeit hätte, würde ich Gitarre lernen.","en":"If I had more time, I'd learn guitar."},{"de":"Wäre es möglich, den Termin zu verschieben?","en":"Would it be possible to postpone the appointment?"},{"de":"An deiner Stelle würde ich zum Arzt gehen.","en":"If I were you, I'd go to the doctor."},{"de":"Wir könnten am Samstag grillen.","en":"We could have a barbecue on Saturday."},{"de":"Ich wünschte, meine Familie wäre hier.","en":"I wish my family were here."},{"de":"Würdest du mir kurz helfen?","en":"Would you help me for a moment?"}],"vocab":[{"de":"der Wunsch, ¨e","en":"wish"},{"de":"der Traum, ¨e","en":"dream"},{"de":"träumen von","en":"to dream of"},{"de":"sich wünschen","en":"to wish for"},{"de":"reich","en":"rich"},{"de":"die Weltreise, -n","en":"world trip"},{"de":"möglich","en":"possible"},{"de":"verschieben","en":"to postpone"},{"de":"höflich","en":"polite"},{"de":"die Feier, -n","en":"celebration"},{"de":"die Überraschung, -en","en":"surprise"},{"de":"das Glück","en":"luck / happiness"}],"reading":"Auf Annas Geburtstagsfeier fragt Leila: „Was würdet ihr machen, wenn ihr eine Million Euro hättet?“ Jonas sagt: „Ich würde sofort kündigen und eine Weltreise machen.“ Anna meint: „Ich hätte gern ein Haus mit Garten. Dann könnten die Kinder draußen spielen.“ Ravi denkt nach: „Wenn ich reich wäre, würde ich meine Eltern nach Berlin einladen. Und ich würde eine kleine Schule in Mumbai bauen.“ Leila lächelt: „Das wäre wirklich schön.“","tasks":[{"q":"Ich ___ gern nach Japan fliegen. (werden)","a":"würde"},{"q":"Wenn ich Zeit ___, würde ich kommen. (haben)","a":"hätte"},{"q":"Wenn er hier ___, wäre alles leichter. (sein)","a":"wäre"},{"q":"___ Sie mir bitte helfen? (können)","a":"Könnten"},{"q":"Ich ___ gern ein Stück Kuchen. (haben)","a":"hätte"},{"q":"Umformen (irreal): Ich habe kein Auto. Ich fahre nicht ans Meer.","a":"Wenn ich ein Auto hätte, würde ich ans Meer fahren."},{"q":"Höflich: Gib mir das Salz!","a":"Könntest du mir bitte das Salz geben?"},{"q":"[Mix] Wenn ich ___ Chef wäre, würde ich ___ Mitarbeitern mehr Urlaub geben. (der, die – Dativ)","a":"der / den"},{"q":"[Mix] Ich würde ___ gern mit dir treffen. (sich)","a":"mich"},{"q":"[Mix] Es wäre schön, wenn du am Samstag ___. (mitkommen)","a":"mitkommen würdest / mitkämst"}],"exam":[{"q":"Was würde Jonas mit einer Million machen?","a":"Kündigen und eine Weltreise machen."},{"q":"Was hätte Anna gern?","a":"Ein Haus mit Garten."},{"q":"Wen würde Ravi einladen?","a":"Seine Eltern."},{"q":"Höflich: Haben Sie Zeit?","a":"Hätten Sie Zeit?"},{"q":"Irreal: Ich bin nicht krank, ich gehe zur Arbeit. → Wenn …","a":"Wenn ich krank wäre, würde ich nicht zur Arbeit gehen."},{"q":"Ergänze: ___ es möglich, früher zu kommen?","a":"Wäre"},{"q":"Ergänze: Wir ___ uns am Montag treffen. (können, höflich)","a":"könnten"},{"q":"Was würden Sie machen, wenn Sie Bundeskanzler(in) wären?","a":""},{"q":"Wovon träumen Sie? Beschreiben Sie Ihr Traumleben in 10 Jahren.","a":""},{"q":"Bitten Sie im Hotel höflich um drei Dinge.","a":""}],"speak":["Was würdest du auf dieser Party machen?","Wenn du Geburtstag hättest, wie würdest du feiern?","Die Party ist zu laut. Bitte die Nachbarn höflich: __Könnten Sie …?__","Wenn du einen Wunsch frei hättest, …"]},{"n":26,"level":"B1","title":"Ratschläge und Empfehlungen geben","theme":"Probleme lösen","scene":"doctor","rec":[12,19,21,25],"expl":["Für **Ratschläge** gibt es mehrere Strukturen. Von direkt bis höflich:","**Imperativ:** __Geh zum Arzt!__ → **sollte (Konj. II)**: __Du **solltest** zum Arzt gehen.__ → **An deiner Stelle würde ich …** → **Ich empfehle / rate dir, … zu …** → **Es wäre gut / besser, wenn du …** → **Wie wäre es, wenn du …?**","**sollen (Präsens)** = Auftrag von anderen: __Der Arzt sagt, ich **soll** …__. **sollte (Konj. II)** = Rat: __Du **solltest** …__","Nachfragen/Reagieren: __Das ist ein guter Tipp. Das habe ich schon versucht. Meinst du wirklich?__"],"use":"Prüfung (Goethe Teil 3 / telc): Feedback, Tipps geben; Forumsbeitrag schreiben; Alltag.","table":[["Struktur","Beispiel","Stärke"],["Imperativ","Mach eine Pause!","direkt"],["du solltest + Inf.","Du solltest mehr schlafen.","normal"],["An deiner Stelle würde ich …","An deiner Stelle würde ich früher ins Bett gehen.","höflich"],["Ich empfehle dir, … zu + Inf.","Ich empfehle dir, Yoga zu machen.","höflich"],["Es wäre besser, wenn …","Es wäre besser, wenn du weniger Kaffee trinken würdest.","sehr höflich"],["Wie wäre es mit …? / Warum … nicht …?","Wie wäre es mit einem Spaziergang?","Vorschlag"]],"examples":[{"de":"Du solltest mehr Wasser trinken.","en":"You should drink more water."},{"de":"An deiner Stelle würde ich mit dem Chef sprechen.","en":"If I were you, I'd talk to the boss."},{"de":"Ich empfehle Ihnen, einen Termin zu machen.","en":"I recommend you make an appointment."},{"de":"Es wäre gut, wenn du dich ausruhen würdest.","en":"It would be good if you rested."},{"de":"Warum machst du nicht einen Deutschkurs?","en":"Why don't you take a German course?"},{"de":"Ihr solltet nicht so spät ins Bett gehen.","en":"You shouldn't go to bed so late."},{"de":"Wie wäre es mit einem Tandempartner?","en":"How about a tandem partner?"},{"de":"Mein Tipp: Hör jeden Tag deutsche Podcasts.","en":"My tip: listen to German podcasts every day."},{"de":"Der Arzt sagt, ich soll weniger Zucker essen.","en":"The doctor says I should eat less sugar."},{"de":"Das ist ein guter Rat, danke!","en":"That's good advice, thanks!"}],"vocab":[{"de":"der Rat / der Ratschlag, ¨e","en":"advice"},{"de":"der Tipp, -s","en":"tip"},{"de":"raten (rät)","en":"to advise"},{"de":"empfehlen","en":"to recommend"},{"de":"das Problem, -e","en":"problem"},{"de":"der Stress","en":"stress"},{"de":"schlafen / der Schlaf","en":"to sleep / sleep"},{"de":"die Ernährung","en":"diet, nutrition"},{"de":"sich bewegen","en":"to exercise, move"},{"de":"versuchen","en":"to try"},{"de":"aufhören mit","en":"to stop doing"},{"de":"nützlich","en":"useful"}],"reading":"Jonas schläft schlecht und hat viel Stress. Er fragt Ravi um Rat. Ravi sagt: „Du solltest abends nicht so lange am Handy sein. An deiner Stelle würde ich eine Stunde vor dem Schlafen lesen.“ Leila ist Ärztin und gibt auch Tipps: „Ich empfehle dir, dich mehr zu bewegen. Und es wäre besser, wenn du nach 16 Uhr keinen Kaffee mehr trinken würdest.“ Jonas lacht: „Kein Kaffee? Das ist schwer! Aber ich versuche es.“","tasks":[{"q":"Du ___ mehr schlafen. (sollen, Rat)","a":"solltest"},{"q":"An deiner Stelle ___ ich zu Hause bleiben.","a":"würde"},{"q":"Ich empfehle dir, früher ___ ___. (aufstehen)","a":"aufzustehen"},{"q":"Es wäre besser, wenn du weniger ___ ___. (arbeiten)","a":"arbeiten würdest"},{"q":"Wie wäre es ___ einem Spaziergang?","a":"mit"},{"q":"Umformen (sollte): Geh zum Arzt!","a":"Du solltest zum Arzt gehen."},{"q":"Umformen (An deiner Stelle): Du solltest das Angebot annehmen.","a":"An deiner Stelle würde ich das Angebot annehmen."},{"q":"[Mix] Du solltest ___ nicht so viel ärgern. (sich)","a":"dich"},{"q":"[Mix] Wenn ich du ___, ___ ich mehr Deutsch sprechen. (sein, werden)","a":"wäre / würde"},{"q":"[Mix] Ihr solltet ___ ___ Gesundheit kümmern. (sich, um, eure)","a":"euch / um eure"}],"exam":[{"q":"Welche Probleme hat Jonas?","a":"Er schläft schlecht und hat Stress."},{"q":"Was soll Jonas vor dem Schlafen machen (Ravi)?","a":"Eine Stunde lesen."},{"q":"Was ist für Jonas schwer?","a":"Nach 16 Uhr keinen Kaffee zu trinken."},{"q":"Gib einen Rat mit „sollte“: Mein Deutsch ist schlecht.","a":"Du solltest jeden Tag üben."},{"q":"Gib einen Rat mit „An deiner Stelle“: Ich habe Zahnschmerzen.","a":"An deiner Stelle würde ich zum Zahnarzt gehen."},{"q":"sollen oder sollte? Der Chef sagt, ich ___ den Bericht schreiben.","a":"soll"},{"q":"Ergänze: Ich rate dir, mehr Obst ___ ___.","a":"zu essen"},{"q":"Ein Freund findet keine Wohnung. Geben Sie 4 Ratschläge.","a":""},{"q":"Schreiben Sie einen Forumsbeitrag: Tipps für neue Deutschlerner.","a":""},{"q":"Welchen Rat würden Sie jemandem geben, der nach Deutschland ziehen möchte?","a":""}],"speak":["Welchen Rat gibt die Ärztin dem Patienten?","Der Patient hat Stress. Gib ihm 3 Tipps mit verschiedenen Strukturen.","Was rätst du jemandem, der nicht schlafen kann?","Welcher Rat war für dich im Leben am wichtigsten?"]},{"n":27,"level":"B1","title":"Vorschläge machen und gemeinsam planen","theme":"Eine Feier organisieren","scene":"party","rec":[13,14,21,25,26],"expl":["Das ist **Prüfungsteil „Gemeinsam etwas planen“**. Du musst **vorschlagen, reagieren, zustimmen/ablehnen, Alternativen nennen** und am Ende **eine Lösung** finden.","**Vorschlagen:** Wie wäre es mit … / wenn wir …? · Was hältst du davon, wenn …? · Wir könnten … · Lass uns … · Sollen wir …? · Ich schlage vor, dass …","**Zustimmen:** Gute Idee! · Einverstanden. · Das machen wir so. **Ablehnen:** Das finde ich nicht so gut, weil … · Ich weiß nicht … · Lieber …","**Einigen:** Also, wir machen es so: … · Wer kümmert sich um …? · Ich übernehme …"],"use":"Goethe Sprechen Teil 1, telc Teil 3: Party, Ausflug, Besuch, Geschenk planen.","table":[["Funktion","Redemittel","Grammatik"],["Vorschlag","Wie wäre es, wenn wir am Samstag feiern würden?","Konj. II + wenn"],["Vorschlag","Was hältst du davon, wenn wir im Park grillen?","wenn-Satz"],["Vorschlag","Lass uns / Wir könnten einen Kuchen backen.","Imperativ / Konj. II"],["Zustimmen","Die Idee gefällt mir, denn …","Dativ + denn"],["Ablehnen","Das finde ich keine gute Idee, weil …","weil-Satz"],["Einigen","Also: Du kaufst die Getränke und ich kümmere mich um das Essen.","Reflexiv + um"]],"examples":[{"de":"Wie wäre es, wenn wir eine Überraschungsparty machen?","en":"How about we throw a surprise party?"},{"de":"Was hältst du davon, wenn wir im Garten feiern?","en":"What do you think about celebrating in the garden?"},{"de":"Lass uns zuerst die Gästeliste schreiben.","en":"Let's write the guest list first."},{"de":"Wir könnten Pizza bestellen.","en":"We could order pizza."},{"de":"Das ist eine gute Idee, aber das ist zu teuer.","en":"That's a good idea but it's too expensive."},{"de":"Ich schlage vor, dass jeder etwas mitbringt.","en":"I suggest everyone brings something."},{"de":"Wer kümmert sich um die Musik?","en":"Who takes care of the music?"},{"de":"Ich übernehme die Einladungen.","en":"I'll take care of the invitations."},{"de":"Sollen wir uns um 18 Uhr treffen?","en":"Shall we meet at 6 pm?"},{"de":"Also, dann machen wir es so!","en":"OK, then let's do it that way!"}],"vocab":[{"de":"die Party, -s","en":"party"},{"de":"organisieren","en":"to organise"},{"de":"die Gästeliste, -n","en":"guest list"},{"de":"die Einladung, -en","en":"invitation"},{"de":"die Getränke (Pl.)","en":"drinks"},{"de":"dekorieren","en":"to decorate"},{"de":"mitbringen","en":"to bring along"},{"de":"übernehmen (übernimmt)","en":"to take on"},{"de":"sich kümmern um","en":"to take care of"},{"de":"einverstanden","en":"agreed"},{"de":"der Vorschlag, ¨e","en":"suggestion"},{"de":"die Aufgabe, -n","en":"task"}],"reading":"Frau Berger geht in Rente. Ravi und Mia planen eine Feier im Büro. Mia: „Wie wäre es, wenn wir am Freitagnachmittag feiern?“ – Ravi: „Gute Idee. Was hältst du davon, wenn wir ein Buffet machen?“ – Mia: „Hm, das ist viel Arbeit. Wir könnten doch Essen bestellen.“ – Ravi: „Einverstanden. Und ein Geschenk?“ – Mia: „Ich schlage vor, dass alle Kollegen zehn Euro geben.“ – Ravi: „Gut. Also: Du kümmerst dich um das Geschenk, ich übernehme das Essen und die Einladungen.“","tasks":[{"q":"Wie ___ es mit einem Picknick?","a":"wäre"},{"q":"Was ___ du davon, wenn wir ins Kino gehen?","a":"hältst"},{"q":"___ uns morgen früh losfahren!","a":"Lass"},{"q":"Wir ___ einen Kuchen backen. (können, Vorschlag)","a":"könnten"},{"q":"Ich schlage vor, dass wir den Bus ___. (nehmen)","a":"nehmen"},{"q":"Wer kümmert sich ___ ___ Getränke?","a":"um die"},{"q":"Ablehnen mit weil: Grillen? (es regnet)","a":"Das finde ich nicht so gut, weil es regnet."},{"q":"[Mix] Ich ___ die Einladungen. (übernehmen, Präsens)","a":"übernehme"},{"q":"[Mix] Wir könnten ___ Chefin ___ Blumenstrauß schenken. (die, ein)","a":"der / einen"},{"q":"[Mix] Wie wäre es, wenn wir die Party ___ Samstag ___ 19 Uhr machen würden?","a":"am / um"}],"exam":[{"q":"Warum machen Ravi und Mia eine Feier?","a":"Frau Berger geht in Rente."},{"q":"Warum wollen sie kein Buffet machen?","a":"Das ist viel Arbeit."},{"q":"Wer kümmert sich um das Geschenk?","a":"Mia."},{"q":"Mache einen Vorschlag mit „Wie wäre es, wenn …“: zusammen kochen","a":"Wie wäre es, wenn wir zusammen kochen würden?"},{"q":"Reagiere positiv und gib einen Grund.","a":"z. B. Gute Idee, denn das macht Spaß."},{"q":"Reagiere negativ und mache eine Alternative.","a":"z. B. Das finde ich nicht so gut. Lieber …"},{"q":"Formuliere eine Einigung mit zwei Aufgaben.","a":"z. B. Also: Du kaufst …, ich kümmere mich um …"},{"q":"Planen Sie mit Ihrem Partner: Ein Kollege hat ein Baby bekommen. Was schenken Sie? (Geschenk, Kosten, wer kauft, wann übergeben)","a":""},{"q":"Planen Sie einen Ausflug mit dem Deutschkurs (Ziel, Datum, Fahrt, Essen).","a":""},{"q":"Planen Sie einen Besuch bei einer kranken Freundin.","a":""}],"speak":["Die Feier ist morgen. Plant zu zweit: Essen, Musik, Deko, Geschenk.","Was fehlt noch auf dem Bild? Mach Vorschläge.","Lehne zwei Vorschläge deines Partners höflich ab und nenne Alternativen.","Fasst am Ende zusammen: __Also, wir machen es so: …__"]},{"n":28,"level":"B1","title":"Infinitiv mit zu","theme":"Lernen und Weiterbildung","scene":"classroom","rec":[21,25,26,27],"expl":["Nach vielen Verben, Nomen und Adjektiven folgt ein **Infinitiv mit zu** am **Satzende**: __Ich habe keine Lust, **zu kochen**.__","**Nach Verben:** anfangen, aufhören, versuchen, vergessen, vorhaben, hoffen, beschließen, sich freuen, empfehlen, bitten, erlauben, verbieten.","**Nach Nomen + haben:** Lust, Zeit, Angst, Spaß, die Möglichkeit. **Nach es ist + Adjektiv:** wichtig, schwer, leicht, schön, verboten.","**Trennbare Verben:** zu in der Mitte: an**zu**rufen, auf**zu**stehen. Mit Modalverb **kein zu**: __Ich muss lernen.__","Wenn Subjekt gleich ist → zu-Infinitiv statt dass-Satz: __Ich hoffe, dass ich bestehe = Ich hoffe, die Prüfung **zu bestehen**.__"],"use":"Prüfung: Meinung (Es ist wichtig, … zu …), Pläne (Ich habe vor, …), Gefühle.","table":[["Auslöser","Hauptsatz","zu-Infinitiv (Ende)"],["Verb","Ich versuche,","jeden Tag Deutsch **zu sprechen**."],["Verb (trennbar)","Vergiss nicht,","mich **anzurufen**."],["Nomen","Ich habe keine Zeit,","ins Kino **zu gehen**."],["Adjektiv","Es ist wichtig,","pünktlich **zu sein**."],["Perfekt-Inhalt","Ich freue mich,","dich kennengelernt **zu haben**."]],"examples":[{"de":"Ich habe vor, die B1-Prüfung im Dezember zu machen.","en":"I plan to take the B1 exam in December."},{"de":"Es ist nicht leicht, eine neue Sprache zu lernen.","en":"It's not easy to learn a new language."},{"de":"Ravi hat angefangen, deutsche Bücher zu lesen.","en":"Ravi has started reading German books."},{"de":"Vergiss nicht, die Hausaufgaben zu machen!","en":"Don't forget to do the homework!"},{"de":"Ich habe keine Lust, heute zu lernen.","en":"I don't feel like studying today."},{"de":"Es macht Spaß, mit Leila Deutsch zu sprechen.","en":"It's fun to speak German with Leila."},{"de":"Hast du Zeit, mir kurz zu helfen?","en":"Do you have time to help me quickly?"},{"de":"Die Lehrerin empfiehlt uns, Filme auf Deutsch anzusehen.","en":"The teacher recommends we watch films in German."},{"de":"Ich hoffe, die Prüfung zu bestehen.","en":"I hope to pass the exam."},{"de":"Er hat Angst, Fehler zu machen.","en":"He's afraid of making mistakes."}],"vocab":[{"de":"die Weiterbildung, -en","en":"further training"},{"de":"die Prüfung, -en","en":"exam"},{"de":"bestehen","en":"to pass"},{"de":"durchfallen","en":"to fail"},{"de":"üben","en":"to practise"},{"de":"wiederholen","en":"to revise, repeat"},{"de":"der Fehler, -","en":"mistake"},{"de":"vorhaben","en":"to plan"},{"de":"beschließen","en":"to decide"},{"de":"die Lust","en":"desire, mood"},{"de":"die Möglichkeit, -en","en":"possibility"},{"de":"das Zertifikat, -e","en":"certificate"}],"reading":"Ravi hat beschlossen, im Dezember die B1-Prüfung zu machen. Es ist wichtig für ihn, das Zertifikat zu bekommen, denn er hat vor, sich später um eine bessere Stelle zu bewerben. Frau Klein empfiehlt ihm, jeden Tag zu üben. Manchmal hat Ravi keine Lust, nach der Arbeit noch zu lernen. Aber er versucht, jeden Abend eine halbe Stunde Deutsch zu hören. Leila hilft ihm. Es macht ihm Spaß, mit ihr zu sprechen, und er hat keine Angst mehr, Fehler zu machen.","tasks":[{"q":"Ich versuche, mehr ___ ___. (lesen)","a":"zu lesen"},{"q":"Vergiss nicht, das Fenster ___. (zumachen)","a":"zuzumachen"},{"q":"Es ist wichtig, genug Wasser ___ ___. (trinken)","a":"zu trinken"},{"q":"Ich habe keine Zeit, ___. (einkaufen)","a":"einzukaufen"},{"q":"Wir haben vor, nach Italien ___ ___. (fahren)","a":"zu fahren"},{"q":"zu oder nicht? Ich möchte ___ schwimmen.","a":"(kein zu)"},{"q":"Umformen: Ich hoffe, dass ich die Prüfung bestehe.","a":"Ich hoffe, die Prüfung zu bestehen."},{"q":"[Mix] Es macht mir Spaß, ___ ___ Freunden ___ ___. (mit, meine, kochen)","a":"mit meinen / zu kochen"},{"q":"[Mix] Ich habe angefangen, ___ jeden Morgen ___ ___. (sich, bewegen)","a":"mich / zu bewegen"},{"q":"[Mix] Es wäre schön, dich wieder ___ ___. (sehen)","a":"zu sehen"}],"exam":[{"q":"Warum will Ravi das Zertifikat?","a":"Er will sich später um eine bessere Stelle bewerben."},{"q":"Was empfiehlt Frau Klein?","a":"Jeden Tag zu üben."},{"q":"Wovor hat Ravi keine Angst mehr?","a":"Fehler zu machen."},{"q":"Ergänze: Hast du Lust, heute Abend ___ ___? (ausgehen)","a":"auszugehen"},{"q":"Umformen: Ich freue mich, dass ich dich sehe.","a":"Ich freue mich, dich zu sehen."},{"q":"Ergänze: Es ist verboten, hier ___ ___. (rauchen)","a":"zu rauchen"},{"q":"Fehler? „Ich kann gut zu kochen.“","a":"Ich kann gut kochen."},{"q":"Was ist für Sie wichtig beim Deutschlernen? (Es ist wichtig, … zu …)","a":""},{"q":"Was haben Sie für das nächste Jahr vor?","a":""},{"q":"Wozu haben Sie manchmal keine Lust? Was machen Sie dann?","a":""}],"speak":["Was haben die Leute im Kurs vor? __Sie haben vor, …__","Was ist schwer / leicht beim Deutschlernen? __Es ist schwer, … zu …__","Was hast du vergessen zu machen?","Was macht dir Spaß zu lernen?"]},{"n":29,"level":"B1","title":"Finalsätze: um … zu und damit","theme":"Ziele und Zwecke","scene":"office","rec":[21,24,28],"expl":["**Finalsätze** nennen das **Ziel** (Wozu? / Warum?).","**um … zu + Infinitiv** – wenn das **Subjekt in beiden Teilen gleich** ist: __**Ich** lerne Deutsch, **um** in Deutschland **zu arbeiten**.__","**damit + Nebensatz** – wenn die **Subjekte verschieden** sind (bei gleichen Subjekten auch möglich): __Ich erkläre es langsam, **damit du** es **verstehst**.__","Im damit-Satz **kein Modalverb** wollen/sollen/können nötig. Frage: **Wozu?** Auch: **für + Nomen**: __für die Prüfung__."],"use":"Pläne und Motivation begründen (Präsentation, Bewerbung).","table":[["Subjekte","Hauptsatz","Finalsatz"],["gleich","Ravi spart Geld,","**um** nach Indien **zu fliegen**."],["gleich (trennbar)","Ich gehe früh ins Bett,","**um** früh **aufzustehen**."],["verschieden","Ravi spart Geld,","**damit** seine Eltern ihn **besuchen** können."],["verschieden","Sprich langsam,","**damit** ich dich **verstehe**."],["Nomen","Ich lerne","**für** die Prüfung."]],"examples":[{"de":"Ich lerne Deutsch, um bessere Chancen zu haben.","en":"I learn German to have better chances."},{"de":"Ravi macht Überstunden, um mehr Geld zu verdienen.","en":"Ravi works overtime to earn more money."},{"de":"Ich schreibe alles auf, damit ich nichts vergesse.","en":"I write everything down so that I don't forget anything."},{"de":"Die Chefin erklärt es noch einmal, damit alle es verstehen.","en":"The boss explains it again so everyone understands."},{"de":"Wozu brauchst du den Laptop? – Um zu arbeiten.","en":"What do you need the laptop for? – To work."},{"de":"Wir fahren früh los, um den Zug nicht zu verpassen.","en":"We leave early so as not to miss the train."},{"de":"Ich rufe dich an, damit du Bescheid weißt.","en":"I'll call you so you know."},{"de":"Er geht ins Fitnessstudio, um abzunehmen.","en":"He goes to the gym to lose weight."},{"de":"Anna kocht vor, damit die Kinder etwas essen können.","en":"Anna prepares food so the kids can eat."},{"de":"Ich brauche das Zertifikat für meine Bewerbung.","en":"I need the certificate for my application."}],"vocab":[{"de":"das Ziel, -e","en":"goal"},{"de":"der Zweck, -e","en":"purpose"},{"de":"wozu","en":"what for"},{"de":"die Chance, -n","en":"chance"},{"de":"sparen","en":"to save"},{"de":"verpassen","en":"to miss"},{"de":"Bescheid wissen / sagen","en":"to know / let know"},{"de":"aufschreiben","en":"to write down"},{"de":"die Karriere, -n","en":"career"},{"de":"die Beförderung, -en","en":"promotion"},{"de":"sich vorbereiten auf","en":"to prepare for"},{"de":"erreichen","en":"to reach, achieve"}],"reading":"Ravi hat ein großes Ziel: Er möchte Teamleiter werden. Um dieses Ziel zu erreichen, macht er einen Managementkurs. Er lernt auch weiter Deutsch, damit er besser mit den Kunden sprechen kann. Seine neue Kollegin Mia hilft ihm, damit er die Präsentationen gut vorbereitet. Ravi spart auch Geld, um im Dezember nach Mumbai zu fliegen. Er ruft seine Eltern jede Woche an, damit sie sich keine Sorgen machen.","tasks":[{"q":"Ich lerne viel, ___ die Prüfung ___ ___. (bestehen)","a":"um / zu bestehen"},{"q":"Ich spreche laut, ___ alle mich hören.","a":"damit"},{"q":"Er spart, ___ ein Auto ___ ___. (kaufen)","a":"um / zu kaufen"},{"q":"Wir helfen ihm, ___ er schneller fertig ist.","a":"damit"},{"q":"Sie steht früh auf, um pünktlich ___ ___. (sein)","a":"zu sein"},{"q":"Verbinde (um…zu): Ich gehe zum Bäcker. Ich kaufe Brot.","a":"Ich gehe zum Bäcker, um Brot zu kaufen."},{"q":"Verbinde (damit): Ich gebe dir meine Nummer. Du kannst mich anrufen.","a":"Ich gebe dir meine Nummer, damit du mich anrufen kannst."},{"q":"[Mix] Ich fahre ___ Bahnhof, um meine Mutter ___. (zu + der, abholen)","a":"zum / abzuholen"},{"q":"[Mix] Wir müssen früh losfahren, damit wir den Zug nicht ___. (verpassen)","a":"verpassen"},{"q":"[Mix] Es ist wichtig, Geld zu sparen, ___ man im Urlaub mehr hat.","a":"damit"}],"exam":[{"q":"Welches Ziel hat Ravi?","a":"Teamleiter werden."},{"q":"Warum lernt er weiter Deutsch?","a":"Damit er besser mit den Kunden sprechen kann."},{"q":"Warum ruft er seine Eltern an?","a":"Damit sie sich keine Sorgen machen."},{"q":"um…zu oder damit? Ich trinke Kaffee, ___ wach ___ ___.","a":"um / zu bleiben"},{"q":"um…zu oder damit? Ich mache das Licht an, ___ du lesen kannst.","a":"damit"},{"q":"Frage: „Um Deutsch zu lernen.“ → ?","a":"Wozu / Warum … ?"},{"q":"Umformen: Ich lerne, damit ich die Prüfung bestehe. (um…zu)","a":"Ich lerne, um die Prüfung zu bestehen."},{"q":"Welche Ziele haben Sie für die nächsten 5 Jahre? Wie wollen Sie sie erreichen?","a":""},{"q":"Wozu braucht man heute ein Smartphone? Nennen Sie 5 Zwecke.","a":""},{"q":"Was machen Sie, damit Ihre Familie glücklich ist?","a":""}],"speak":["Wozu sitzt die Frau am Computer? (Vermutung)","Wozu gehen Menschen ins Büro, statt zu Hause zu arbeiten?","Was tust du, um gesund zu bleiben?","Was machst du, damit deine Kollegen / Freunde dich mögen?"]},{"n":30,"level":"B1","title":"ohne … zu / (an)statt … zu","theme":"Gewohnheiten","scene":"kitchen","rec":[28,29],"expl":["**ohne … zu + Infinitiv** = etwas passiert nicht (without doing): __Er geht, **ohne** tschüss **zu sagen**.__","**(an)statt … zu + Infinitiv** = etwas passiert statt einer anderen Sache (instead of doing): __**Statt** zu kochen, bestellt er Pizza.__","Bei **verschiedenen Subjekten**: **ohne dass / statt dass** + Nebensatz: __Er nimmt das Auto, **ohne dass** sein Vater es **weiß**.__","Das Komma steht vor ohne/statt. Trennbare Verben: ohne an**zu**rufen."],"use":"Gewohnheiten kritisieren, Alternativen nennen, Geschichten erzählen.","table":[["Struktur","Beispiel","Bedeutung"],["ohne … zu","Sie isst, ohne zu sprechen.","without speaking"],["ohne … zu (trennbar)","Er kommt, ohne vorher anzurufen.","without calling"],["statt … zu","Statt zu lernen, sieht er fern.","instead of learning"],["ohne dass","Ich bin gegangen, ohne dass es jemand gemerkt hat.","without anyone noticing"],["statt dass","Statt dass er hilft, schläft er.","instead of him helping"]],"examples":[{"de":"Max isst, ohne die Hände zu waschen.","en":"Max eats without washing his hands."},{"de":"Statt zu kochen, bestellen wir Essen.","en":"Instead of cooking, we order food."},{"de":"Ravi ist ins Büro gegangen, ohne zu frühstücken.","en":"Ravi went to the office without having breakfast."},{"de":"Man sollte nicht einkaufen, ohne eine Liste zu schreiben.","en":"You shouldn't shop without writing a list."},{"de":"Anstatt den Bus zu nehmen, fahre ich Rad.","en":"Instead of taking the bus I cycle."},{"de":"Er hat den Kuchen gegessen, ohne dass ich es gesehen habe.","en":"He ate the cake without me seeing."},{"de":"Statt Fleisch zu essen, isst Ravi Linsen.","en":"Instead of eating meat, Ravi eats lentils."},{"de":"Sie hat das Handy gekauft, ohne den Preis zu vergleichen.","en":"She bought the phone without comparing prices."},{"de":"Statt im Bett zu liegen, geh doch spazieren!","en":"Instead of lying in bed, go for a walk!"},{"de":"Ohne zu üben, kann man kein Instrument lernen.","en":"Without practising you can't learn an instrument."}],"vocab":[{"de":"die Gewohnheit, -en","en":"habit"},{"de":"gesund / ungesund","en":"healthy / unhealthy"},{"de":"bestellen","en":"to order"},{"de":"das Fertiggericht, -e","en":"ready meal"},{"de":"die Liste, -n","en":"list"},{"de":"merken","en":"to notice"},{"de":"vergleichen","en":"to compare"},{"de":"der Preis, -e","en":"price"},{"de":"die Linsen (Pl.)","en":"lentils"},{"de":"vorbereiten","en":"to prepare"},{"de":"frisch","en":"fresh"},{"de":"selbst","en":"oneself"}],"reading":"Jonas hat schlechte Gewohnheiten. Oft geht er ins Büro, ohne zu frühstücken. Statt frisch zu kochen, isst er Fertiggerichte. Ravi sagt: „Statt jeden Tag Pizza zu bestellen, könntest du mit mir kochen!“ Am Samstag kochen sie zusammen. Jonas probiert das Curry, ohne zu fragen, wie scharf es ist. Sein Gesicht wird rot! Ravi gibt ihm Joghurt, ohne dass Jonas etwas sagen muss. Seitdem kocht Jonas öfter selbst.","tasks":[{"q":"Er geht, ___ tschüss ___ ___. (sagen)","a":"ohne / zu sagen"},{"q":"___ zu arbeiten, spielt er am Handy.","a":"Statt"},{"q":"Sie kauft ein, ohne eine Liste ___ ___. (schreiben)","a":"zu schreiben"},{"q":"Er kommt, ohne vorher ___. (anrufen)","a":"anzurufen"},{"q":"Statt ___ Bus ___ ___, gehe ich zu Fuß. (der, nehmen)","a":"den / zu nehmen"},{"q":"Verbinde (ohne…zu): Er fährt weg. Er tankt nicht.","a":"Er fährt weg, ohne zu tanken."},{"q":"Verbinde (ohne dass): Sie geht. Ihr Mann merkt es nicht.","a":"Sie geht, ohne dass ihr Mann es merkt."},{"q":"[Mix] Statt ___ ___ ärgern, solltest du ___ entspannen. (sich ×2, du)","a":"dich zu / dich"},{"q":"[Mix] Ich habe das Buch gelesen, um ___ ___ Prüfung vorzubereiten. (sich, auf die)","a":"mich auf die"},{"q":"[Mix] Er ist gegangen, ohne ___ Kollegen ___ ___. (seine, helfen – Dativ!)","a":"seinen Kollegen zu helfen"}],"exam":[{"q":"Was macht Jonas oft falsch?","a":"Er geht ohne Frühstück ins Büro / isst Fertiggerichte."},{"q":"Was schlägt Ravi vor?","a":"Zusammen kochen statt Pizza zu bestellen."},{"q":"Was passiert beim Curry?","a":"Es ist zu scharf, Jonas' Gesicht wird rot."},{"q":"Umformen: Er lernt nicht. Er schläft. (statt … zu)","a":"Statt zu lernen, schläft er."},{"q":"Umformen: Sie kauft das Kleid. Sie probiert es nicht an. (ohne … zu)","a":"Sie kauft das Kleid, ohne es anzuprobieren."},{"q":"ohne zu oder ohne dass? Ich habe gegessen, ___ die Kinder etwas ___.","a":"ohne dass / gemerkt haben"},{"q":"Ergänze: Statt ___ Auto ___ ___, fahre ich Rad. (das, nehmen)","a":"das Auto zu nehmen"},{"q":"Welche Gewohnheiten möchten Sie ändern? Was machen Sie statt …?","a":""},{"q":"Was machen viele Menschen, ohne nachzudenken?","a":""},{"q":"Was sollte man nie tun, ohne vorher zu fragen?","a":""}],"speak":["Was machen die Personen in der Küche? Kochen sie oder bestellen sie?","Was machst du oft, ohne zu überlegen?","Was machst du lieber, statt fernzusehen?","Gesund leben: Was sollte man statt … tun?"]},{"n":31,"level":"B1","title":"Verben mit Präpositionen + da- und wo-Wörter","theme":"Gefühle und Interessen","scene":"classroom","rec":[6,13,16,19,21,28],"expl":["Viele Verben haben eine **feste Präposition** mit festem Fall. Lerne sie als Einheit: **warten auf + Akk.**, **denken an + Akk.**, **sich freuen auf/über + Akk.**, **Angst haben vor + Dat.**, **träumen von + Dat.**, **teilnehmen an + Dat.**, **sprechen mit + Dat. über + Akk.**","**Frage:** Person → Präposition + **Pronomen** (__Auf **wen** wartest du?__). Sache → **wo(r)** + Präposition (__**Worauf** wartest du?__).","**Antwort/Verweis:** Person → Präp. + Pronomen (__auf **ihn**__). Sache → **da(r)** + Präp. (__**darauf**__). **r** wenn die Präposition mit Vokal beginnt: wo**r**an, da**r**über.","**da-Wort + dass/zu:** __Ich freue mich **darauf**, **dass** du kommst / dich **zu** sehen.__"],"use":"Interessen, Gefühle, Meinungen – und Nachfragen in der Prüfung (Worüber sprichst du?).","table":[["Verb + Präp.","Fall","Frage (Sache / Person)","Antwort (Sache / Person)"],["warten auf","Akk.","Worauf? / Auf wen?","darauf / auf ihn"],["sich interessieren für","Akk.","Wofür? / Für wen?","dafür / für sie"],["denken an","Akk.","Woran? / An wen?","daran / an ihn"],["sprechen über","Akk.","Worüber? / Über wen?","darüber / über ihn"],["Angst haben vor","Dat.","Wovor? / Vor wem?","davor / vor ihm"],["träumen von","Dat.","Wovon? / Von wem?","davon / von ihr"]],"examples":[{"de":"Ich warte auf den Bus. – Ich warte schon lange darauf.","en":"I'm waiting for the bus. – I've been waiting for it a long time."},{"de":"Worüber habt ihr gesprochen?","en":"What did you talk about?"},{"de":"Ravi denkt oft an seine Eltern.","en":"Ravi often thinks of his parents."},{"de":"Ich interessiere mich für Geschichte.","en":"I'm interested in history."},{"de":"Hast du Angst vor der Prüfung? – Nein, keine Angst davor.","en":"Are you afraid of the exam? – No."},{"de":"Leila träumt von einer eigenen Praxis.","en":"Leila dreams of her own practice."},{"de":"Mit wem hast du telefoniert?","en":"Who did you talk to on the phone?"},{"de":"Ich freue mich darauf, dich zu sehen.","en":"I'm looking forward to seeing you."},{"de":"Er nimmt an einem Kurs teil.","en":"He's taking part in a course."},{"de":"Kannst du dich um die Blumen kümmern? – Ja, ich kümmere mich darum.","en":"Can you look after the flowers? – Yes, I'll take care of it."}],"vocab":[{"de":"warten auf","en":"to wait for"},{"de":"denken an","en":"to think of"},{"de":"sich erinnern an","en":"to remember"},{"de":"sprechen über","en":"to talk about"},{"de":"sich beschweren über","en":"to complain about"},{"de":"Angst haben vor","en":"to be afraid of"},{"de":"träumen von","en":"to dream of"},{"de":"teilnehmen an","en":"to take part in"},{"de":"sich verabreden mit","en":"to arrange to meet"},{"de":"sich entschuldigen bei / für","en":"to apologise to / for"},{"de":"bitten um","en":"to ask for"},{"de":"sich gewöhnen an","en":"to get used to"}],"reading":"Im Kurs sprechen die Teilnehmer über ihre Gefühle. Frau Klein fragt: „Woran denkt ihr, wenn ihr an eure Heimat denkt?“ Ravi sagt: „Ich denke an das Essen und an meine Familie. Ich träume oft davon, mit ihnen am Strand zu sitzen.“ Leila erzählt: „Am Anfang hatte ich Angst vor dem Winter. Aber ich habe mich daran gewöhnt.“ Frau Klein fragt: „Und worauf freut ihr euch?“ Ravi: „Ich freue mich auf Dezember, denn da besuche ich meine Eltern.“","tasks":[{"q":"Ich warte ___ ___ Zug.","a":"auf den"},{"q":"Er interessiert sich ___ Musik.","a":"für"},{"q":"___ denkst du? – An meinen Urlaub.","a":"Woran"},{"q":"___ wem sprichst du? – Mit Anna.","a":"Mit"},{"q":"Hast du Angst vor Spinnen? – Ja, ich habe Angst ___.","a":"davor"},{"q":"Freust du dich auf die Reise? – Ja, ich freue mich sehr ___.","a":"darauf"},{"q":"Denkst du an deinen Bruder? – Ja, ich denke oft an ___.","a":"ihn"},{"q":"[Mix] Ich habe mich ___ ___ Nachbarn über den Lärm beschwert. (bei, der)","a":"bei dem / beim"},{"q":"[Mix] Ich erinnere mich gern ___, wie wir als Kinder gespielt haben.","a":"daran"},{"q":"[Mix] Wir haben ___ ___ Prüfung gesprochen. (über, die)","a":"über die"}],"exam":[{"q":"Woran denkt Ravi, wenn er an seine Heimat denkt?","a":"An das Essen und seine Familie."},{"q":"Wovor hatte Leila Angst?","a":"Vor dem Winter."},{"q":"Worauf freut sich Ravi?","a":"Auf Dezember (Besuch bei seinen Eltern)."},{"q":"Frage: Ich spreche über das Wetter.","a":"Worüber sprichst du?"},{"q":"Frage: Ich warte auf meine Freundin.","a":"Auf wen wartest du?"},{"q":"Antwort mit da-: Interessierst du dich für Politik?","a":"Ja, ich interessiere mich dafür. / Nein, …"},{"q":"Ergänze: Er träumt ___ ___ großen Haus.","a":"von einem"},{"q":"Wofür interessieren Sie sich? Worüber ärgern Sie sich?","a":""},{"q":"Woran erinnern Sie sich gern aus Ihrer Kindheit?","a":""},{"q":"Wovor haben viele Menschen Angst? Und Sie?","a":""}],"speak":["Worüber sprechen die Leute im Kurs? (Vermutung)","Frag den Partner mit wo-Wörtern: __Wofür …? Worauf …? Woran …?__","Worauf freust du dich nach der Prüfung?","An was musstest du dich in einem neuen Land / einer neuen Stadt gewöhnen?"]},{"n":32,"level":"B1","title":"Indirekte Fragen","theme":"Behörden und Informationen","scene":"office","rec":[4,21,25,31],"expl":["Indirekte Fragen sind **Nebensätze**: Das Verb steht **am Ende**. Sie sind **höflicher** als direkte Fragen.","**W-Frage** → das W-Wort bleibt: __Wann kommt der Bus?__ → __Können Sie mir sagen, **wann** der Bus **kommt**?__","**Ja/Nein-Frage** → **ob**: __Ist das Büro offen?__ → __Wissen Sie, **ob** das Büro offen **ist**?__","Einleitungen: Können Sie mir sagen, … · Wissen Sie, … · Ich möchte wissen, … · Ich frage mich, … · Weißt du zufällig, … Nach „Ich weiß nicht, …“ steht ein **Punkt**, keine Frage."],"use":"Bei Behörden, am Telefon, Informationen erfragen – sehr höflich.","table":[["Direkte Frage","Indirekte Frage"],["Wo ist das Bürgeramt?","Können Sie mir sagen, wo das Bürgeramt **ist**?"],["Welche Unterlagen brauche ich?","Ich möchte wissen, welche Unterlagen ich **brauche**."],["Muss ich einen Termin machen?","Wissen Sie, ob ich einen Termin machen **muss**?"],["Wann hat das Amt geöffnet?","Könnten Sie mir sagen, wann das Amt geöffnet **hat**?"],["Hat er angerufen?","Ich weiß nicht, ob er angerufen **hat**."]],"examples":[{"de":"Können Sie mir sagen, wo die Toiletten sind?","en":"Can you tell me where the toilets are?"},{"de":"Wissen Sie, ob ich hier parken darf?","en":"Do you know whether I can park here?"},{"de":"Ich möchte wissen, wie lange die Anmeldung dauert.","en":"I'd like to know how long registration takes."},{"de":"Weißt du zufällig, wann der Kurs anfängt?","en":"Do you happen to know when the course starts?"},{"de":"Ich frage mich, warum er nicht gekommen ist.","en":"I wonder why he didn't come."},{"de":"Könnten Sie mir erklären, was ich hier ausfüllen muss?","en":"Could you explain what I have to fill in here?"},{"de":"Ich weiß nicht, ob ich Zeit habe.","en":"I don't know whether I have time."},{"de":"Darf ich fragen, wie viel das kostet?","en":"May I ask how much that costs?"},{"de":"Sie hat gefragt, wer mitkommt.","en":"She asked who's coming along."},{"de":"Wissen Sie, welcher Bus zum Rathaus fährt?","en":"Do you know which bus goes to the town hall?"}],"vocab":[{"de":"die Behörde, -n","en":"authority"},{"de":"das Amt, ¨er","en":"office (public)"},{"de":"das Bürgeramt","en":"citizens' office"},{"de":"die Anmeldung, -en","en":"registration"},{"de":"das Formular, -e","en":"form"},{"de":"ausfüllen","en":"to fill in"},{"de":"die Unterlagen (Pl.)","en":"documents"},{"de":"der Ausweis, -e","en":"ID card"},{"de":"der Reisepass, ¨e","en":"passport"},{"de":"die Aufenthaltserlaubnis","en":"residence permit"},{"de":"unterschreiben","en":"to sign"},{"de":"die Wartenummer, -n","en":"queue number"}],"reading":"Ravi muss sich ummelden. Er ruft beim Bürgeramt an: „Guten Tag. Können Sie mir sagen, wann Sie geöffnet haben? Und ich möchte wissen, ob ich einen Termin brauche.“ – „Ja, Sie brauchen einen Termin. Den können Sie online buchen.“ – „Wissen Sie auch, welche Unterlagen ich mitbringen muss?“ – „Ihren Reisepass und die Bestätigung vom Vermieter.“ – „Darf ich noch fragen, wie lange es dauert?“ – „Ungefähr zehn Minuten.“ – „Vielen Dank!“","tasks":[{"q":"Wo ist die Post? → Wissen Sie, wo die Post ___?","a":"ist"},{"q":"Wann beginnt der Film? → Weißt du, wann der Film ___?","a":"beginnt"},{"q":"Ist Herr Weber da? → Können Sie mir sagen, ___ Herr Weber da ist?","a":"ob"},{"q":"Wie viel kostet das? → Ich möchte wissen, ___ ___ das kostet.","a":"wie viel"},{"q":"Kommt er mit? → Ich frage mich, ___ er ___.","a":"ob / mitkommt"},{"q":"Wo hast du das gekauft? → Sag mir, wo du das ___ ___.","a":"gekauft hast"},{"q":"Muss ich zahlen? → Wissen Sie, ob ich ___ ___?","a":"zahlen muss"},{"q":"[Mix] Können Sie mir sagen, ___ ___ Formular ich ausfüllen muss? (welch-, das)","a":"welches"},{"q":"[Mix] Ich weiß nicht, ___ ___ ich mich wenden soll. (an, wer)","a":"an wen"},{"q":"[Mix] Wissen Sie, ___ ich mich beschweren kann? (bei wem / wo)","a":"bei wem / wo"}],"exam":[{"q":"Warum ruft Ravi an?","a":"Er muss sich ummelden."},{"q":"Braucht er einen Termin?","a":"Ja."},{"q":"Welche Unterlagen braucht er?","a":"Reisepass und Bestätigung vom Vermieter."},{"q":"Indirekt: Wo wohnen Sie? (Darf ich fragen, …)","a":"Darf ich fragen, wo Sie wohnen?"},{"q":"Indirekt: Fährt dieser Bus zum Zoo? (Wissen Sie, …)","a":"Wissen Sie, ob dieser Bus zum Zoo fährt?"},{"q":"Indirekt: Warum ist der Zug zu spät? (Ich möchte wissen, …)","a":"Ich möchte wissen, warum der Zug zu spät ist."},{"q":"Fehler? „Können Sie mir sagen, wo ist der Bahnhof?“","a":"…, wo der Bahnhof ist?"},{"q":"Rufen Sie bei einer Sprachschule an und fragen Sie indirekt nach 4 Informationen.","a":""},{"q":"Sie sind im Bürgeramt. Fragen Sie höflich, was Sie tun müssen.","a":""},{"q":"Welche Erfahrungen haben Sie mit Behörden gemacht?","a":""}],"speak":["Die Frau arbeitet im Amt. Stelle ihr 4 indirekte Fragen.","Was möchtest du über das Leben in Deutschland wissen? __Ich möchte wissen, ob …__","Ich frage mich oft, … (3 Sätze)","Frag deinen Partner indirekt nach seinem Wochenende."]},{"n":33,"level":"B1","title":"Relativsätze","theme":"Menschen und Dinge beschreiben","scene":"family","rec":[5,6,13,15,21,23],"expl":["Ein **Relativsatz** beschreibt ein Nomen genauer. Er ist ein **Nebensatz** (Verb am Ende) und steht direkt **nach dem Nomen**.","Das **Relativpronomen** hat das **Genus/Numerus des Nomens**, aber den **Fall aus dem Relativsatz**: __Der Mann, **den** ich kenne (kennen + Akk.)__.","Formen = bestimmter Artikel, **außer**: Dativ Plural **denen**, Genitiv **dessen / deren**.","Mit Präposition: Präposition steht **vor** dem Relativpronomen: __die Freundin, **mit der** ich wohne__. Nach Orten auch **wo**: __die Stadt, **wo** (in der) ich wohne__."],"use":"Personen und Dinge genau beschreiben, Bildbeschreibung, Definitionen.","table":[["Fall","maskulin","feminin","neutral","Plural"],["Nominativ","der","die","das","die"],["Akkusativ","den","die","das","die"],["Dativ","dem","der","dem","**denen**"],["Genitiv","**dessen**","**deren**","**dessen**","**deren**"],["Beispiel","Der Mann, **der** dort steht, …","Die Frau, **der** ich helfe, …","Das Kind, **das** ich sehe, …","Die Leute, **mit denen** ich arbeite, …"]],"examples":[{"de":"Das ist der Kollege, der aus Hamburg kommt.","en":"That's the colleague who comes from Hamburg."},{"de":"Das ist die Frau, die ich im Kurs kennengelernt habe.","en":"That's the woman I met in the course."},{"de":"Der Mann, dem ich geholfen habe, war sehr nett.","en":"The man I helped was very nice."},{"de":"Das Buch, das du mir geschenkt hast, ist super.","en":"The book you gave me is great."},{"de":"Die Freunde, mit denen ich reise, kommen aus Indien.","en":"The friends I travel with come from India."},{"de":"Berlin ist eine Stadt, in der viele Nationen leben.","en":"Berlin is a city where many nations live."},{"de":"Das ist Anna, deren Sohn Fußball spielt.","en":"That's Anna, whose son plays football."},{"de":"Ich suche eine Wohnung, die nicht so teuer ist.","en":"I'm looking for a flat that isn't so expensive."},{"de":"Der Film, über den alle sprechen, ist langweilig.","en":"The film everyone talks about is boring."},{"de":"Mumbai ist die Stadt, wo ich geboren bin.","en":"Mumbai is the city where I was born."}],"vocab":[{"de":"die Person, -en","en":"person"},{"de":"der Mensch, -en","en":"human"},{"de":"freundlich / unfreundlich","en":"friendly / unfriendly"},{"de":"hilfsbereit","en":"helpful"},{"de":"lustig","en":"funny"},{"de":"ehrlich","en":"honest"},{"de":"geduldig","en":"patient"},{"de":"der Charakter, -e","en":"character"},{"de":"die Eigenschaft, -en","en":"quality"},{"de":"kennenlernen","en":"to get to know"},{"de":"sich verstehen mit","en":"to get on with"},{"de":"der Mitbewohner, -","en":"flatmate"}],"reading":"Ravi schreibt seiner Schwester eine E-Mail: „In Berlin habe ich Menschen kennengelernt, die mir sehr wichtig sind. Anna ist die Nachbarin, die mir immer hilft. Jonas ist der Kollege, mit dem ich am besten zusammenarbeite. Leila ist die Freundin, die ich im Deutschkurs kennengelernt habe und mit der ich oft spazieren gehe. Max, dessen Mutter Anna ist, ist ein Junge, der nur an Fußball denkt. Das sind die Leute, denen ich viel zu verdanken habe.“","tasks":[{"q":"Das ist der Mann, ___ neben mir wohnt.","a":"der"},{"q":"Das ist die Frau, ___ ich liebe.","a":"die"},{"q":"Das ist das Kind, ___ ich geholfen habe.","a":"dem"},{"q":"Hier ist der Stuhl, ___ ich gekauft habe.","a":"den"},{"q":"Das sind die Kinder, mit ___ ich spiele.","a":"denen"},{"q":"Das ist die Lehrerin, ___ Kurs ich besuche.","a":"deren"},{"q":"Verbinde: Ich habe einen Freund. Er wohnt in Wien.","a":"Ich habe einen Freund, der in Wien wohnt."},{"q":"[Mix] Das ist die Kollegin, ___ ich ___ Blumen geschenkt habe. (Dativ, die)","a":"der / die"},{"q":"[Mix] Die Wohnung, in ___ wir wohnen, ist größer ___ die alte.","a":"der / als"},{"q":"[Mix] Der Film, ___ ___ ich mich interessiere, läuft heute. (für)","a":"für den"}],"exam":[{"q":"Wer ist Anna?","a":"Die Nachbarin, die Ravi immer hilft."},{"q":"Wo hat Ravi Leila kennengelernt?","a":"Im Deutschkurs."},{"q":"Wer ist Max?","a":"Annas Sohn, der nur an Fußball denkt."},{"q":"Verbinde: Das ist der Bus. Ich fahre mit dem Bus zur Arbeit.","a":"Das ist der Bus, mit dem ich zur Arbeit fahre."},{"q":"Verbinde: Ich kenne eine Frau. Ihr Mann ist Koch.","a":"Ich kenne eine Frau, deren Mann Koch ist."},{"q":"Verbinde: Die Leute sind nett. Ich arbeite für die Leute.","a":"Die Leute, für die ich arbeite, sind nett."},{"q":"Definiere mit Relativsatz: ein Bäcker","a":"Ein Bäcker ist ein Mann, der Brot backt."},{"q":"Beschreiben Sie eine Person, die für Sie wichtig ist.","a":""},{"q":"Wie ist ein guter Freund? (Ein guter Freund ist jemand, der …)","a":""},{"q":"Beschreiben Sie die Stadt, in der Sie aufgewachsen sind.","a":""}],"speak":["Beschreibe die Personen mit Relativsätzen: __Die Frau, die links sitzt, …__","Rätsel: Beschreibe ein Ding, ohne den Namen zu sagen: __Das ist etwas, das …__","Beschreibe den Nachbarn, den du am liebsten magst.","Was für ein Mensch möchtest du sein?"]},{"n":34,"level":"B1","title":"Temporalsätze: als, wenn, bevor, nachdem, während, seit, bis","theme":"Lebenslauf und Erinnerungen","scene":"family","rec":[17,18,21,24,33],"expl":["Temporalsätze sind Nebensätze (Verb am Ende) und sagen, **wann** etwas passiert.","**als** = **einmal** in der **Vergangenheit**: __**Als** ich 18 war, …__ · **wenn** = Gegenwart/Zukunft oder **wiederholt** (immer wenn) in der Vergangenheit.","**bevor** = vorher · **nachdem** = nachher (+ **Plusquamperfekt**/Perfekt, siehe L35) · **während** = gleichzeitig · **seit(dem)** = von damals bis jetzt · **bis** = Endpunkt."],"use":"Lebenslauf erzählen, Erfahrungen, Präsentation („Als ich nach Deutschland kam, …“).","table":[["Konj.","Bedeutung","Beispiel"],["als","einmal, Vergangenheit","**Als** ich nach Berlin kam, war es kalt."],["wenn","immer / Zukunft","**Wenn** ich in Mumbai war, bin ich immer ans Meer gegangen."],["bevor","before","Ich trinke Chai, **bevor** ich arbeite."],["nachdem","after","**Nachdem** ich gegessen hatte, bin ich gegangen."],["während","while","**Während** ich koche, höre ich Musik."],["seit(dem)","since","**Seit** ich hier wohne, fahre ich Rad."],["bis","until","Warte, **bis** ich komme!"]],"examples":[{"de":"Als ich ein Kind war, wohnten wir in Pune.","en":"When I was a child we lived in Pune."},{"de":"Wenn ich traurig bin, rufe ich meine Mutter an.","en":"When I'm sad I call my mother."},{"de":"Immer wenn es regnete, spielten wir drinnen.","en":"Whenever it rained we played inside."},{"de":"Bevor ich nach Deutschland kam, habe ich Deutsch gelernt.","en":"Before I came to Germany I learned German."},{"de":"Nachdem ich die Schule beendet hatte, studierte ich.","en":"After I had finished school, I studied."},{"de":"Während Ravi kocht, telefoniert er mit Leila.","en":"While Ravi cooks, he talks to Leila on the phone."},{"de":"Seit ich in Berlin wohne, spreche ich jeden Tag Deutsch.","en":"Since I've lived in Berlin I speak German every day."},{"de":"Ich bleibe hier, bis der Regen aufhört.","en":"I'll stay here until the rain stops."},{"de":"Als ich die Stelle bekam, war ich sehr glücklich.","en":"When I got the job I was very happy."},{"de":"Wenn ich die Prüfung bestanden habe, feiern wir.","en":"When I've passed the exam, we'll celebrate."}],"vocab":[{"de":"der Lebenslauf, ¨e","en":"CV / life story"},{"de":"geboren","en":"born"},{"de":"aufwachsen","en":"to grow up"},{"de":"die Schule beenden","en":"to finish school"},{"de":"das Studium","en":"university studies"},{"de":"studieren","en":"to study"},{"de":"der Abschluss, ¨e","en":"degree"},{"de":"das Praktikum, Praktika","en":"internship"},{"de":"sich erinnern an","en":"to remember"},{"de":"die Erinnerung, -en","en":"memory"},{"de":"damals","en":"back then"},{"de":"die Jugend","en":"youth"}],"reading":"Ravi wurde 1998 in Mumbai geboren. Als er zehn war, zog die Familie nach Pune. Wenn er Ferien hatte, besuchte er immer seine Großeltern am Meer. Nachdem er die Schule beendet hatte, studierte er Maschinenbau. Während er studierte, machte er ein Praktikum bei einer deutschen Firma. Bevor er nach Berlin kam, lernte er ein Jahr Deutsch. Seit er hier lebt, ist sein Leben ganz anders. Er bleibt in Berlin, bis er Teamleiter ist – mindestens!","tasks":[{"q":"___ ich 20 war, bin ich nach Delhi gezogen.","a":"Als"},{"q":"___ ich Zeit habe, lese ich.","a":"Wenn"},{"q":"Immer ___ Oma kam, brachte sie Süßigkeiten mit.","a":"wenn"},{"q":"Putz dir die Zähne, ___ du schlafen gehst!","a":"bevor"},{"q":"___ ich wohne hier, habe ich viele Freunde. → korrigiere","a":"Seit ich hier wohne, habe ich viele Freunde."},{"q":"___ du duschst, mache ich das Frühstück.","a":"Während"},{"q":"Warte hier, ___ ich zurückkomme!","a":"bis"},{"q":"[Mix] Als ich klein ___, ___ ich keinen Computer. (sein, haben – Prät.)","a":"war / hatte"},{"q":"[Mix] Bevor ich ___ Haus verlasse, ziehe ich ___ die Jacke an. (das, sich – Dat.)","a":"das / mir"},{"q":"[Mix] Seitdem ich ___ Leila spreche, ist mein Deutsch ___. (mit, gut – Komp.)","a":"mit / besser"}],"exam":[{"q":"Wohin zog die Familie, als Ravi zehn war?","a":"Nach Pune."},{"q":"Was machte Ravi, wenn er Ferien hatte?","a":"Er besuchte seine Großeltern am Meer."},{"q":"Was machte er, bevor er nach Berlin kam?","a":"Er lernte ein Jahr Deutsch."},{"q":"als oder wenn? ___ ich gestern nach Hause kam, war niemand da.","a":"Als"},{"q":"als oder wenn? ___ ich nach Hause komme, koche ich immer.","a":"Wenn"},{"q":"Verbinde (während): Ich fahre Bus. Ich lese.","a":"Während ich Bus fahre, lese ich."},{"q":"Verbinde (bevor): Ich gehe ins Bett. Ich lese.","a":"Bevor ich ins Bett gehe, lese ich."},{"q":"Erzählen Sie Ihren Lebenslauf mit als, nachdem, bevor, seit.","a":""},{"q":"Woran erinnern Sie sich, wenn Sie an Ihre Schulzeit denken?","a":""},{"q":"Was machen Sie immer, wenn Sie Stress haben?","a":""}],"speak":["Erzähle eine Geschichte zur Familie: __Als die Kinder klein waren, …__","Was machst du, während du isst?","Was war, als du zum ersten Mal in einem neuen Land warst?","Was hat sich geändert, seit du Deutsch lernst?"]},{"n":35,"level":"B1","title":"Präteritum (alle Verben) und Plusquamperfekt","theme":"Geschichten erzählen","scene":"station","rec":[17,18,24,34],"expl":["**Präteritum** benutzt man vor allem **schriftlich** (Geschichten, Zeitung, Märchen). Regelmäßig: Stamm + **-te**: machte, wohnte. Unregelmäßig: eigener Stamm: ging, kam, fuhr, sah, fand (siehe Referenz 3). ich und er/sie/es haben **keine Endung**: ich ging, er ging.","**Plusquamperfekt** = die Vergangenheit **vor** der Vergangenheit: **hatte/war + Partizip II**: __Als ich ankam, **war** der Zug schon **abgefahren**.__","Typisch mit **nachdem**: Plusquamperfekt im nachdem-Satz, Präteritum/Perfekt im Hauptsatz."],"use":"Lesetexte in der Prüfung verstehen, Geschichten/E-Mails schreiben.","table":[["Zeit","regelmäßig (reisen)","unregelmäßig (fahren)","Funktion"],["Präsens","er reist","er fährt","jetzt"],["Präteritum","er reis**te**","er **fuhr**","Vergangenheit (schriftlich)"],["Perfekt","er ist gereist","er ist gefahren","Vergangenheit (mündlich)"],["Plusquamperfekt","er **war** gereist","er **war** gefahren","vor der Vergangenheit"],["Plusquamperfekt (haben)","er **hatte** gewartet","er **hatte** gegessen","vor der Vergangenheit"]],"examples":[{"de":"Letzten Winter fuhr Ravi nach Hamburg.","en":"Last winter Ravi went to Hamburg."},{"de":"Der Zug kam mit einer Stunde Verspätung an.","en":"The train arrived an hour late."},{"de":"Ravi wartete am Gleis und fror.","en":"Ravi waited on the platform and was freezing."},{"de":"Er hatte seine Handschuhe zu Hause vergessen.","en":"He had forgotten his gloves at home."},{"de":"Als er ankam, war das Museum schon geschlossen.","en":"When he arrived, the museum had already closed."},{"de":"Nachdem er gegessen hatte, ging er zum Hafen.","en":"After he had eaten he went to the harbour."},{"de":"Es war einmal ein König, der drei Töchter hatte.","en":"Once upon a time there was a king who had three daughters."},{"de":"Sie las den Brief und weinte.","en":"She read the letter and cried."},{"de":"Wir waren schon eingeschlafen, als das Telefon klingelte.","en":"We had already fallen asleep when the phone rang."},{"de":"Er fand die Adresse nicht, weil er den Zettel verloren hatte.","en":"He couldn't find the address because he had lost the note."}],"vocab":[{"de":"die Geschichte, -n","en":"story / history"},{"de":"das Märchen, -","en":"fairy tale"},{"de":"plötzlich","en":"suddenly"},{"de":"zum Glück","en":"luckily"},{"de":"leider","en":"unfortunately"},{"de":"verlieren (verlor)","en":"to lose"},{"de":"frieren (fror)","en":"to freeze"},{"de":"klingeln","en":"to ring"},{"de":"der Hafen, ¨","en":"harbour"},{"de":"das Museum, Museen","en":"museum"},{"de":"ankommen (kam an)","en":"to arrive"},{"de":"weinen","en":"to cry"}],"reading":"Letzten Winter fuhr Ravi nach Hamburg. Er hatte die Fahrkarte schon vor Wochen gekauft. Leider hatte der Zug eine Stunde Verspätung. Ravi wartete am Gleis und fror, denn er hatte seine Handschuhe vergessen. Als er endlich in Hamburg ankam, war das Museum schon geschlossen. Zum Glück fand er ein kleines Café am Hafen. Nachdem er einen heißen Tee getrunken hatte, ging er am Wasser spazieren. Plötzlich sah er ein riesiges Schiff. Es war ein schöner Abend.","tasks":[{"q":"Präteritum: Ich (wohnen) ___ in Pune.","a":"wohnte"},{"q":"Präteritum: Er (gehen) ___ nach Hause.","a":"ging"},{"q":"Präteritum: Wir (sehen) ___ einen Film.","a":"sahen"},{"q":"Präteritum: Sie (kommen, Sg.) ___ spät an.","a":"kam"},{"q":"Plusquamperfekt: Ich ___ schon ___. (essen)","a":"hatte / gegessen"},{"q":"Plusquamperfekt: Der Bus ___ schon ___. (abfahren)","a":"war / abgefahren"},{"q":"Nachdem er die Arbeit beendet ___, ___ er nach Hause. (haben, fahren – Prät.)","a":"hatte / fuhr"},{"q":"[Mix] Als ich ___ Bahnhof ankam, war der Zug schon weg. (an + der)","a":"am"},{"q":"[Mix] Er konnte nicht bezahlen, weil er ___ Geldbeutel verloren ___. (sein, haben)","a":"seinen / hatte"},{"q":"[Mix] Präteritum: Sie (sich freuen) ___ ___ über das Geschenk.","a":"freute sich"}],"exam":[{"q":"Warum fror Ravi?","a":"Er hatte seine Handschuhe vergessen."},{"q":"Warum konnte er nicht ins Museum?","a":"Es war schon geschlossen."},{"q":"Was machte er, nachdem er Tee getrunken hatte?","a":"Er ging am Wasser spazieren."},{"q":"Perfekt → Präteritum: Wir sind nach Rom gefahren.","a":"Wir fuhren nach Rom."},{"q":"Perfekt → Präteritum: Sie hat einen Brief geschrieben.","a":"Sie schrieb einen Brief."},{"q":"Plusquamperfekt: Ich kam an. Der Film (beginnen) … schon.","a":"Der Film hatte schon begonnen."},{"q":"Verbinde mit nachdem: Er frühstückte. Dann ging er los.","a":"Nachdem er gefrühstückt hatte, ging er los."},{"q":"Schreiben Sie eine kurze Geschichte (8 Sätze) im Präteritum: Ein Tag, an dem alles schiefging.","a":""},{"q":"Erzählen Sie ein Märchen aus Ihrem Land.","a":""},{"q":"Was war schon passiert, als Sie heute aufgewacht sind?","a":""}],"speak":["Erzähle eine Geschichte zum Bahnhof im Präteritum: __Der Mann wartete …__","Was war vorher passiert? (Plusquamperfekt)","Erzähle, was dir auf einer Reise einmal passiert ist.","Erfinde ein Ende für Ravis Hamburg-Geschichte."]},{"n":36,"level":"B1","title":"Gegensätze: obwohl und trotzdem","theme":"Arbeit und Freizeit im Gleichgewicht","scene":"office","rec":[20,21,34],"expl":["**obwohl** (although) leitet einen **Nebensatz** ein – Verb am Ende: __Ich gehe joggen, **obwohl** es **regnet**.__","**trotzdem** (nevertheless) ist ein **Adverb** – im Hauptsatz auf **Position 1** (Verb danach) oder in der Mitte: __Es regnet. **Trotzdem gehe** ich joggen. / Ich gehe **trotzdem** joggen.__","Beide zeigen einen **unerwarteten Gegensatz** (Gegenteil von weil/deshalb). Vergleiche: __weil__ = Grund, __obwohl__ = Gegengrund.","Auch: **aber** (Pos. 0) und **trotz + Genitiv** (L40)."],"use":"Differenziert argumentieren – bringt Punkte bei „Spektrum“ in der Prüfung.","table":[["Typ","Satz 1","Satz 2"],["obwohl (Nebensatz)","Ravi arbeitet,","**obwohl** er krank **ist**."],["obwohl zuerst","**Obwohl** er krank ist,","**arbeitet** er."],["trotzdem Pos. 1","Er ist krank.","**Trotzdem arbeitet** er."],["trotzdem Mitte","Er ist krank.","Er arbeitet **trotzdem**."],["aber (Pos. 0)","Er ist krank,","**aber** er arbeitet."]],"examples":[{"de":"Obwohl ich müde bin, lerne ich noch.","en":"Although I'm tired, I'm still studying."},{"de":"Jonas hat viel Arbeit. Trotzdem macht er pünktlich Feierabend.","en":"Jonas has a lot of work. Nevertheless he finishes on time."},{"de":"Ich esse Schokolade, obwohl ich eine Diät mache.","en":"I eat chocolate although I'm on a diet."},{"de":"Es war kalt, trotzdem sind wir geschwommen.","en":"It was cold; we swam anyway."},{"de":"Obwohl Ravi wenig Zeit hat, geht er jede Woche joggen.","en":"Although Ravi has little time, he goes jogging every week."},{"de":"Das Gehalt ist gut. Trotzdem ist sie nicht zufrieden.","en":"The salary is good. Nevertheless she's not satisfied."},{"de":"Er kam zur Arbeit, obwohl er Fieber hatte.","en":"He came to work although he had a fever."},{"de":"Ich habe gut geschlafen und bin trotzdem müde.","en":"I slept well and am still tired."},{"de":"Obwohl die Wohnung teuer ist, haben wir sie genommen.","en":"Although the flat is expensive, we took it."},{"de":"Sie lernt nie – trotzdem besteht sie jede Prüfung.","en":"She never studies – yet she passes every exam."}],"vocab":[{"de":"das Gleichgewicht","en":"balance"},{"de":"die Work-Life-Balance","en":"work-life balance"},{"de":"der Feierabend","en":"end of the working day"},{"de":"zufrieden / unzufrieden","en":"satisfied / unsatisfied"},{"de":"die Diät, -en","en":"diet"},{"de":"erschöpft","en":"exhausted"},{"de":"die Belastung, -en","en":"strain"},{"de":"entspannen","en":"to relax"},{"de":"die Teilzeit / Vollzeit","en":"part-time / full-time"},{"de":"flexibel","en":"flexible"},{"de":"der Druck","en":"pressure"},{"de":"sich leisten","en":"to afford"}],"reading":"Mia arbeitet Vollzeit, obwohl sie zwei kleine Kinder hat. Sie ist oft erschöpft. Trotzdem ist sie mit ihrer Arbeit zufrieden, denn ihre Arbeitszeiten sind flexibel. Jonas dagegen hat keine Kinder, aber er macht viele Überstunden. Obwohl sein Gehalt gut ist, möchte er weniger arbeiten. Ravi sagt: „Ich arbeite gern viel. Trotzdem nehme ich mir am Wochenende immer Zeit für Freunde.“ Mia antwortet: „Das ist klug. Obwohl die Arbeit wichtig ist, ist das Leben wichtiger.“","tasks":[{"q":"Ich gehe spazieren, ___ es kalt ist.","a":"obwohl"},{"q":"Es ist kalt. ___ gehe ich spazieren.","a":"Trotzdem"},{"q":"Er ist nicht gekommen, ___ er Zeit hatte.","a":"obwohl"},{"q":"Verbinde (obwohl): Sie ist krank. Sie arbeitet.","a":"Obwohl sie krank ist, arbeitet sie. / Sie arbeitet, obwohl sie krank ist."},{"q":"Verbinde (trotzdem): Das Hotel war teuer. Wir haben es gebucht.","a":"Das Hotel war teuer. Trotzdem haben wir es gebucht."},{"q":"weil oder obwohl? Ich trinke Kaffee, ___ ich müde bin.","a":"weil"},{"q":"weil oder obwohl? Ich kann nicht schlafen, ___ ich müde bin.","a":"obwohl"},{"q":"[Mix] Obwohl ich ___ gestern früh ins Bett gegangen ___, bin ich müde. (sein)","a":"bin"},{"q":"[Mix] Er hat ___ ___ Kollegen geholfen, obwohl er keine Zeit hatte. (sein, Dativ)","a":"seinem"},{"q":"[Mix] Obwohl es teuer ___, ___ ich gern eine größere Wohnung. (sein, haben – Konj. II)","a":"ist / hätte"}],"exam":[{"q":"Warum ist Mia zufrieden?","a":"Weil ihre Arbeitszeiten flexibel sind."},{"q":"Was möchte Jonas, obwohl sein Gehalt gut ist?","a":"Weniger arbeiten."},{"q":"Wofür nimmt sich Ravi Zeit?","a":"Für Freunde am Wochenende."},{"q":"Umformen (trotzdem → obwohl): Er hat Geld. Trotzdem kauft er nichts.","a":"Obwohl er Geld hat, kauft er nichts."},{"q":"Umformen (obwohl → trotzdem): Obwohl es regnet, fahren wir los.","a":"Es regnet. Trotzdem fahren wir los."},{"q":"Ergänze: Sie ist zufrieden, ___ sie wenig verdient.","a":"obwohl"},{"q":"Fehler? „Trotzdem ich arbeite viel.“","a":"Trotzdem arbeite ich viel."},{"q":"Was machen Sie, obwohl Sie wissen, dass es nicht gut ist?","a":""},{"q":"Ist eine gute Work-Life-Balance wichtig? Argumentieren Sie mit obwohl/trotzdem.","a":""},{"q":"Vollzeit oder Teilzeit: Nennen Sie Vor- und Nachteile.","a":""}],"speak":["Die Frau arbeitet noch, obwohl …? (Vermutung)","Beschreibe das Bild mit trotzdem: __Es ist schon spät. Trotzdem …__","Was hast du gemacht, obwohl du keine Lust hattest?","Sollte man im Urlaub E-Mails lesen? Pro/Contra."]},{"n":37,"level":"B1","title":"Konsequenzen: deshalb, deswegen, darum, sonst","theme":"Umwelt und Verkehr","scene":"city","rec":[20,21,29,36],"expl":["**deshalb, deswegen, darum** (therefore) zeigen eine **Folge**. Sie sind **Adverbien**: Position 1 → Verb danach (**Inversion**): __Es regnet, **deshalb nehme** ich den Bus.__","Vergleiche: **weil** (Grund, Nebensatz) ↔ **deshalb** (Folge, Hauptsatz): __Ich nehme den Bus, **weil** es **regnet**. = Es regnet, **deshalb nehme** ich den Bus.__","**sonst** (otherwise) zeigt eine negative Folge: __Beeil dich, **sonst verpassen** wir den Zug.__","Auch **also** (so) und **daher** funktionieren gleich."],"use":"Argumentieren (Umwelt, Verkehr, Gesundheit), Präsentation: Vorteile/Nachteile.","table":[["Konnektor","Satz 1 (Grund)","Satz 2 (Folge)"],["deshalb","Die Luft ist schlecht,","**deshalb fahre** ich Rad."],["deswegen","Ich will Geld sparen.","**Deswegen kaufe** ich kein Auto."],["darum","Der Bus ist voll,","**darum gehen** wir zu Fuß."],["sonst","Wir müssen Energie sparen,","**sonst wird** der Strom teurer."],["weil (Vergleich)","Ich fahre Rad,","**weil** die Luft schlecht **ist**."]],"examples":[{"de":"Ich will die Umwelt schützen, deshalb fahre ich Fahrrad.","en":"I want to protect the environment, so I cycle."},{"de":"Die Mieten in der Stadt sind hoch, deswegen ziehen viele aufs Land.","en":"City rents are high, so many move to the country."},{"de":"Es gibt oft Stau, darum nehme ich die S-Bahn.","en":"There are often traffic jams, so I take the S-Bahn."},{"de":"Mach das Licht aus, sonst verbrauchen wir zu viel Strom.","en":"Turn off the light, otherwise we use too much electricity."},{"de":"Ravi hat kein Auto, deshalb ist er flexibel mit dem Zug.","en":"Ravi has no car, so he's flexible by train."},{"de":"Plastik ist schlecht für das Meer, deshalb benutzen wir Stofftaschen.","en":"Plastic is bad for the sea, so we use cloth bags."},{"de":"Wir müssen den Müll trennen, sonst gibt es Ärger mit dem Vermieter.","en":"We must separate rubbish, otherwise there's trouble with the landlord."},{"de":"Der Zug war billig, darum sind wir nicht geflogen.","en":"The train was cheap, so we didn't fly."},{"de":"Er hat den Bus verpasst, deswegen ist er zu spät gekommen.","en":"He missed the bus, so he came late."},{"de":"Beeil dich, sonst ist der Markt geschlossen!","en":"Hurry up or the market will be closed!"}],"vocab":[{"de":"die Umwelt","en":"environment"},{"de":"schützen","en":"to protect"},{"de":"der Müll","en":"rubbish"},{"de":"trennen","en":"to separate"},{"de":"der Stau, -s","en":"traffic jam"},{"de":"die Energie","en":"energy"},{"de":"der Strom","en":"electricity"},{"de":"verbrauchen","en":"to consume"},{"de":"das Plastik","en":"plastic"},{"de":"der Klimawandel","en":"climate change"},{"de":"öffentliche Verkehrsmittel","en":"public transport"},{"de":"umweltfreundlich","en":"eco-friendly"}],"reading":"In Berlin fahren viele Menschen mit dem Fahrrad, denn die Stadt hat viele Radwege. Ravi hatte in Mumbai ein Motorrad. In Berlin gibt es gute öffentliche Verkehrsmittel, deshalb braucht er kein Fahrzeug. Er möchte die Umwelt schützen, darum trennt er seinen Müll genau. Am Anfang war das schwer: „Gelbe Tonne, blaue Tonne, Biotonne – das ist kompliziert!“ Anna hat es ihm erklärt: „Du musst den Müll richtig trennen, sonst ärgert sich der Hausmeister.“","tasks":[{"q":"Es regnet, ___ bleibe ich zu Hause. (Folge)","a":"deshalb"},{"q":"Ich bin krank. ___ ___ ich nicht zur Arbeit. (deswegen, gehen)","a":"Deswegen gehe"},{"q":"Zieh eine Jacke an, ___ frierst du.","a":"sonst"},{"q":"Umformen (deshalb): Ich lerne, weil ich eine Prüfung habe.","a":"Ich habe eine Prüfung, deshalb lerne ich."},{"q":"Umformen (weil): Der Zug ist teuer, darum fahre ich mit dem Bus.","a":"Ich fahre mit dem Bus, weil der Zug teuer ist."},{"q":"Fehler? „Ich habe Hunger, deshalb ich esse.“","a":"…, deshalb esse ich."},{"q":"Verbinde (sonst): Wir müssen jetzt gehen. Wir kommen zu spät.","a":"Wir müssen jetzt gehen, sonst kommen wir zu spät."},{"q":"[Mix] Ravi möchte fit bleiben, deshalb ___ er jeden Tag ___ Fahrrad. (fahren, mit dem)","a":"fährt / mit dem"},{"q":"[Mix] Obwohl Autos praktisch sind, ___ ich keins. (wollen)","a":"will"},{"q":"[Mix] Der Müll wird getrennt, ___ er recycelt werden kann. (Zweck)","a":"damit"}],"exam":[{"q":"Warum braucht Ravi in Berlin kein Fahrzeug?","a":"Es gibt gute öffentliche Verkehrsmittel."},{"q":"Warum trennt er den Müll?","a":"Er möchte die Umwelt schützen."},{"q":"Was passiert, wenn man den Müll nicht trennt?","a":"Der Hausmeister ärgert sich."},{"q":"weil oder deshalb? Ich spare Energie, ___ Strom teuer ist.","a":"weil"},{"q":"weil oder deshalb? Strom ist teuer, ___ spare ich Energie.","a":"deshalb"},{"q":"Ergänze: Fahr langsam, ___ bekommst du eine Strafe.","a":"sonst"},{"q":"Verbinde (darum): Die Luft ist schmutzig. Viele Leute tragen Masken.","a":"Die Luft ist schmutzig, darum tragen viele Leute Masken."},{"q":"Was tun Sie für die Umwelt? Begründen Sie mit deshalb/weil.","a":""},{"q":"Auto oder Fahrrad in der Stadt? Präsentieren Sie Vor- und Nachteile.","a":""},{"q":"Wie ist die Umweltsituation in Ihrem Heimatland?","a":""}],"speak":["Beschreibe den Verkehr auf dem Bild: Was ist gut / schlecht für die Umwelt?","Der Bus ist voll, deshalb …? Mach 3 Folgen.","Was passiert, wenn wir nichts tun? __Wir müssen … sonst …__","Wie kommst du zur Arbeit und warum? (deshalb)"]},{"n":38,"level":"B1","title":"Zweiteilige Konnektoren","theme":"Medien und Internet","scene":"office","rec":[20,22,36,37],"expl":["Zweiteilige Konnektoren verbinden zwei Informationen elegant:","**sowohl … als auch** (both … and) · **nicht nur … sondern auch** (not only … but also) · **entweder … oder** (either … or) · **weder … noch** (neither … nor) · **zwar … aber** (it's true … but) · **je … desto** (the … the, siehe L42).","**weder … noch** ist schon negativ – **kein** zusätzliches nicht! **zwar … aber** ist perfekt für Vor- und Nachteile.","Wortstellung: Die Konnektoren stehen meist vor dem Satzteil, den sie betreffen: __Ich spreche **sowohl** Hindi **als auch** Englisch.__"],"use":"Prüfung Teil 2 (Präsentation): Vor- und Nachteile, Meinung – bringt höhere Punkte!","table":[["Konnektor","Bedeutung","Beispiel"],["sowohl … als auch","both … and","Ich nutze **sowohl** Instagram **als auch** WhatsApp."],["nicht nur … sondern auch","not only … but also","Das Handy ist **nicht nur** praktisch, **sondern auch** gefährlich."],["entweder … oder","either … or","**Entweder** lese ich Zeitung **oder** ich höre Podcasts."],["weder … noch","neither … nor","Er hat **weder** Facebook **noch** Instagram."],["zwar … aber","admittedly … but","Das Internet ist **zwar** nützlich, **aber** es macht süchtig."]],"examples":[{"de":"Ich lese Nachrichten sowohl online als auch in der Zeitung.","en":"I read news both online and in the newspaper."},{"de":"Soziale Medien sind nicht nur unterhaltsam, sondern auch informativ.","en":"Social media are not only entertaining but also informative."},{"de":"Entweder schaue ich eine Serie oder ich lese ein Buch.","en":"Either I watch a series or I read a book."},{"de":"Mein Opa hat weder ein Handy noch einen Computer.","en":"My grandpa has neither a mobile nor a computer."},{"de":"Das Smartphone ist zwar praktisch, aber man verliert viel Zeit.","en":"The smartphone is practical, but you lose a lot of time."},{"de":"Ravi telefoniert nicht nur mit seinen Eltern, sondern auch mit seiner Oma.","en":"Ravi calls not only his parents but also his grandma."},{"de":"Wir können entweder einen Film streamen oder ins Kino gehen.","en":"We can either stream a film or go to the cinema."},{"de":"Online-Shopping ist zwar bequem, aber schlecht für kleine Läden.","en":"Online shopping is convenient but bad for small shops."},{"de":"Weder Jonas noch Mia haben die E-Mail bekommen.","en":"Neither Jonas nor Mia got the email."},{"de":"Leila spricht sowohl Persisch als auch Deutsch fließend.","en":"Leila speaks both Persian and German fluently."}],"vocab":[{"de":"die Medien (Pl.)","en":"media"},{"de":"soziale Netzwerke","en":"social networks"},{"de":"die Nachricht, -en","en":"news / message"},{"de":"die Zeitung, -en","en":"newspaper"},{"de":"die Serie, -n","en":"series"},{"de":"streamen","en":"to stream"},{"de":"das Smartphone, -s","en":"smartphone"},{"de":"die App, -s","en":"app"},{"de":"herunterladen","en":"to download"},{"de":"süchtig","en":"addicted"},{"de":"der Datenschutz","en":"data protection"},{"de":"die Informationsquelle, -n","en":"source of information"}],"reading":"Ravi nutzt sowohl WhatsApp als auch Videoanrufe, um mit seiner Familie zu sprechen. Das Internet ist für ihn nicht nur praktisch, sondern auch wichtig gegen das Heimweh. Seine Oma hat zwar ein Smartphone, aber sie benutzt es kaum. Jonas dagegen hat weder Instagram noch TikTok. Er sagt: „Entweder ich lese ein Buch oder ich treffe Freunde. Soziale Medien sind zwar interessant, aber man verliert zu viel Zeit.“ Ravi findet: „Es kommt darauf an, wie man sie nutzt.“","tasks":[{"q":"Ich trinke ___ Tee ___ Kaffee. (both … and)","a":"sowohl / als auch"},{"q":"Er hat ___ Zeit ___ Geld. (neither … nor)","a":"weder / noch"},{"q":"___ kommst du mit ___ du bleibst hier.","a":"Entweder / oder"},{"q":"Das Auto ist ___ alt, ___ es fährt gut.","a":"zwar / aber"},{"q":"Sie ist ___ klug, ___ sehr nett. (not only … but also)","a":"nicht nur / sondern auch"},{"q":"Verbinde (weder … noch): Ich habe keinen Fernseher. Ich habe kein Radio.","a":"Ich habe weder einen Fernseher noch ein Radio."},{"q":"Fehler? „Ich esse weder Fleisch noch nicht Fisch.“","a":"Ich esse weder Fleisch noch Fisch."},{"q":"[Mix] Das Handy ist zwar ___ (teuer, Komp.) als das alte, aber es ist auch besser.","a":"teurer"},{"q":"[Mix] Wir können entweder ___ Kino gehen oder ___ Hause bleiben.","a":"ins / zu"},{"q":"[Mix] Soziale Medien sind nicht nur gut, sondern auch gefährlich, deshalb ___ man vorsichtig sein. (sollen, Rat)","a":"sollte"}],"exam":[{"q":"Wie spricht Ravi mit seiner Familie?","a":"Über WhatsApp und Videoanrufe."},{"q":"Welche sozialen Medien hat Jonas?","a":"Keine (weder Instagram noch TikTok)."},{"q":"Was sagt Jonas über soziale Medien?","a":"Sie sind zwar interessant, aber man verliert zu viel Zeit."},{"q":"Ergänze: Ich lerne ___ mit Büchern ___ mit Apps. (both)","a":"sowohl / als auch"},{"q":"Ergänze: ___ rufe ich dich an ___ ich schreibe dir.","a":"Entweder / oder"},{"q":"Umformen (zwar … aber): Streaming ist billig. Es gibt zu viel Auswahl.","a":"Streaming ist zwar billig, aber es gibt zu viel Auswahl."},{"q":"Ergänze: Das Buch ist ___ spannend ___ lustig. (neither)","a":"weder / noch"},{"q":"Präsentieren Sie: „Soziale Medien – Vor- und Nachteile“ (mit zwar … aber, nicht nur … sondern auch).","a":""},{"q":"Welche Medien nutzen Sie und wofür?","a":""},{"q":"Sollten Kinder ein Smartphone haben? Diskutieren Sie.","a":""}],"speak":["Was machen die zwei am Computer? __Sie … entweder … oder …__","Wie nutzt du dein Handy? Benutze 3 zweiteilige Konnektoren.","Homeoffice: zwar … aber …","Wie haben sich die Medien seit deiner Kindheit geändert?"]},{"n":39,"level":"B1","title":"Das Passiv","theme":"Prozesse und Produktion","scene":"kitchen","rec":[6,17,35,37],"expl":["Im **Passiv** ist die **Handlung** wichtig, nicht die Person: __Das Brot **wird gebacken**.__","Form **Präsens:** **werden + Partizip II** · **Präteritum:** **wurde + Partizip II** · **Perfekt:** **ist + Partizip II + worden** · **mit Modalverb:** **muss + Partizip II + werden**.","Das **Akkusativ-Objekt** im Aktiv wird zum **Subjekt** (Nominativ) im Passiv: __Man repariert **den** Wagen → **Der** Wagen wird repariert.__","Die Person (falls wichtig) mit **von + Dativ**: __Das Essen wird **von meiner Mutter** gekocht.__"],"use":"Rezepte, Prozesse, Regeln, Nachrichten beschreiben; Präsentationen und Lesetexte.","table":[["Zeit","Aktiv","Passiv"],["Präsens","Man kocht den Reis.","Der Reis **wird gekocht**."],["Präteritum","Man baute das Haus 1900.","Das Haus **wurde** 1900 **gebaut**."],["Perfekt","Man hat das Auto repariert.","Das Auto **ist repariert worden**."],["Modalverb","Man muss den Müll trennen.","Der Müll **muss getrennt werden**."],["mit Person","Mein Vater kocht das Essen.","Das Essen wird **von meinem Vater** gekocht."]],"examples":[{"de":"Zuerst wird der Reis gewaschen.","en":"First the rice is washed."},{"de":"Dann werden die Zwiebeln geschnitten.","en":"Then the onions are chopped."},{"de":"Das Brandenburger Tor wurde 1791 gebaut.","en":"The Brandenburg Gate was built in 1791."},{"de":"In Deutschland wird viel Brot gegessen.","en":"A lot of bread is eaten in Germany."},{"de":"Der Müll wird jeden Dienstag abgeholt.","en":"The rubbish is collected every Tuesday."},{"de":"Das Paket ist schon geschickt worden.","en":"The parcel has already been sent."},{"de":"Hier darf nicht geraucht werden.","en":"Smoking is not allowed here."},{"de":"Das Essen wurde von Ravi gekocht.","en":"The food was cooked by Ravi."},{"de":"Die Formulare müssen unterschrieben werden.","en":"The forms must be signed."},{"de":"Tee wird in Indien seit Jahrhunderten getrunken.","en":"Tea has been drunk in India for centuries."}],"vocab":[{"de":"herstellen","en":"to produce"},{"de":"die Produktion","en":"production"},{"de":"die Fabrik, -en","en":"factory"},{"de":"schneiden (geschnitten)","en":"to cut"},{"de":"braten (gebraten)","en":"to fry"},{"de":"würzen","en":"to season"},{"de":"mischen","en":"to mix"},{"de":"backen (gebacken)","en":"to bake"},{"de":"servieren","en":"to serve"},{"de":"bauen","en":"to build"},{"de":"reparieren","en":"to repair"},{"de":"liefern","en":"to deliver"}],"reading":"So wird Masala Chai gemacht: Zuerst wird Wasser in einem Topf gekocht. Dann werden Ingwer, Kardamom und Zimt dazugegeben. Danach wird schwarzer Tee hinzugefügt. Nach drei Minuten wird Milch dazugegossen. Zum Schluss wird der Chai mit Zucker gesüßt und heiß serviert. Ravi erklärt Anna das Rezept. Anna sagt: „In Deutschland wird Tee meistens ohne Milch getrunken.“ Ravi lacht: „In Indien wird Chai überall verkauft – sogar im Zug!“","tasks":[{"q":"Präsens Passiv: Man trinkt hier viel Kaffee. → Hier ___ viel Kaffee ___.","a":"wird / getrunken"},{"q":"Präsens Passiv: Man schneidet die Tomaten. → Die Tomaten ___ ___.","a":"werden geschnitten"},{"q":"Präteritum Passiv: Man baute die Brücke 1950. → Die Brücke ___ 1950 ___.","a":"wurde / gebaut"},{"q":"Perfekt Passiv: Man hat den Brief geschickt. → Der Brief ___ ___ ___.","a":"ist geschickt worden"},{"q":"Modal Passiv: Man muss das Fenster schließen. → Das Fenster ___ ___ ___.","a":"muss geschlossen werden"},{"q":"Mit von: Die Ärztin untersucht den Patienten. → Der Patient ___ ___ ___ Ärztin untersucht.","a":"wird von der"},{"q":"Aktiv oder Passiv? „Ich werde Lehrer.“","a":"Aktiv (werden = become)"},{"q":"[Mix] Zuerst ___ die Zwiebeln geschnitten, danach ___ sie gebraten. (werden)","a":"werden / werden"},{"q":"[Mix] Der Tisch wurde ___ ___ Wand gestellt. (an, die)","a":"an die"},{"q":"[Mix] Das Paket konnte nicht geliefert werden, weil niemand zu Hause ___. (sein – Prät.)","a":"war"}],"exam":[{"q":"Was wird zuerst gemacht?","a":"Wasser wird gekocht."},{"q":"Wann wird Milch dazugegeben?","a":"Nach drei Minuten."},{"q":"Wie wird Tee in Deutschland meistens getrunken?","a":"Ohne Milch."},{"q":"Passiv: Der Mechaniker repariert das Auto.","a":"Das Auto wird vom Mechaniker repariert."},{"q":"Passiv (Prät.): Man erfand das Telefon im 19. Jahrhundert.","a":"Das Telefon wurde im 19. Jahrhundert erfunden."},{"q":"Passiv (Modal): Man muss die Rechnung bezahlen.","a":"Die Rechnung muss bezahlt werden."},{"q":"Aktiv: Die Kinder werden von der Lehrerin abgeholt.","a":"Die Lehrerin holt die Kinder ab."},{"q":"Beschreiben Sie im Passiv ein Rezept aus Ihrem Land.","a":""},{"q":"Wie wird in Ihrem Land ein Fest gefeiert?","a":""},{"q":"Was wird in Ihrer Stadt / Ihrem Land produziert?","a":""}],"speak":["Was wird in der Küche gemacht? __Das Gemüse wird …__","Wie wird ein Brot gebacken? Beschreibe den Prozess.","Was wird in deiner Familie am Wochenende gemacht?","Was muss vor einer Party gemacht werden?"]},{"n":40,"level":"B1","title":"Genitiv und Präpositionen: wegen, trotz, während, statt","theme":"Nachrichten und Alltag","scene":"station","rec":[5,13,23,36,37],"expl":["Der **Genitiv** zeigt **Besitz**: __das Auto **des** Mannes, die Tasche **der** Frau__. Maskulin/neutral bekommen **-s/-es** am Nomen. Bei Namen: **Ravis** Wohnung. Umgangssprachlich oft **von + Dativ**: __das Auto von dem Mann__.","**Genitiv-Präpositionen:** **wegen** (because of), **trotz** (despite), **während** (during), **(an)statt** (instead of), **innerhalb/außerhalb** (inside/outside).","Adjektive im Genitiv enden fast immer auf **-en**: __wegen des schlecht**en** Wetters__.","Vergleiche: __wegen des Regens__ = __weil es regnet__ · __trotz des Regens__ = __obwohl es regnet__."],"use":"Nachrichten verstehen, formelle Texte, Gründe/Gegengründe kurz ausdrücken.","table":[["Fall","maskulin","feminin","neutral","Plural"],["Genitiv (bestimmt)","des Zug**es**","der Bahn","des Wetter**s**","der Züge"],["Genitiv (unbestimmt)","eines Mann**es**","einer Frau","eines Kind**es**","– (von + Dat.)"],["wegen","wegen des Streiks","wegen der Baustelle","wegen des Unfalls","wegen der Ferien"],["trotz","trotz des Regens","trotz der Kälte","trotz des Wetters","trotz der Probleme"],["während","während des Films","während der Fahrt","während des Essens","während der Ferien"]],"examples":[{"de":"Wegen des Streiks fahren heute keine Züge.","en":"Because of the strike no trains are running today."},{"de":"Trotz der Verspätung war Ravi pünktlich im Büro.","en":"Despite the delay Ravi was on time at the office."},{"de":"Während der Fahrt hat er ein Buch gelesen.","en":"During the journey he read a book."},{"de":"Das ist die Wohnung meines Bruders.","en":"That's my brother's flat."},{"de":"Statt eines Autos kaufe ich ein Fahrrad.","en":"Instead of a car I'm buying a bike."},{"de":"Wegen des schlechten Wetters wurde das Konzert abgesagt.","en":"The concert was cancelled due to bad weather."},{"de":"Die Farbe des Mantels gefällt mir.","en":"I like the colour of the coat."},{"de":"Innerhalb einer Woche müssen Sie antworten.","en":"You must reply within a week."},{"de":"Leilas Praxis ist in der Nähe des Bahnhofs.","en":"Leila's practice is near the station."},{"de":"Trotz des Stresses ist er gut gelaunt.","en":"Despite the stress he's in a good mood."}],"vocab":[{"de":"der Streik, -s","en":"strike"},{"de":"die Baustelle, -n","en":"construction site"},{"de":"der Unfall, ¨e","en":"accident"},{"de":"absagen","en":"to cancel"},{"de":"die Durchsage, -n","en":"announcement"},{"de":"der Fahrgast, ¨e","en":"passenger"},{"de":"der Ersatzverkehr","en":"replacement service"},{"de":"die Störung, -en","en":"disruption"},{"de":"die Kälte / die Hitze","en":"cold / heat"},{"de":"das Unwetter, -","en":"storm"},{"de":"die Nähe","en":"vicinity"},{"de":"gut gelaunt","en":"in a good mood"}],"reading":"Durchsage am Bahnhof: „Liebe Fahrgäste, wegen eines Streiks fallen heute viele Züge aus. Wegen der Baustelle zwischen Berlin und Hamburg gibt es einen Ersatzverkehr mit Bussen. Wir bitten um Ihr Verständnis.“ Ravi ärgert sich. Trotz des Streiks muss er heute nach Hamburg fahren, denn der Termin seines Kunden ist wichtig. Er nimmt statt des Zuges einen Fernbus. Während der Fahrt bereitet er die Präsentation vor. Trotz der Probleme kommt er rechtzeitig an.","tasks":[{"q":"Das ist das Auto ___ Nachbarn. (der)","a":"des"},{"q":"Die Tasche ___ Lehrerin ist rot. (die)","a":"der"},{"q":"Wegen ___ Regens bleiben wir zu Hause. (der)","a":"des"},{"q":"Trotz ___ Kälte gehen wir spazieren. (die)","a":"der"},{"q":"Während ___ Essens spricht man nicht. (das)","a":"des"},{"q":"Umformen (wegen): Ich komme später, weil es einen Stau gibt.","a":"Wegen eines Staus komme ich später."},{"q":"Umformen (trotz): Obwohl es regnet, joggt er.","a":"Trotz des Regens joggt er."},{"q":"[Mix] Wegen ___ schlecht___ Wetters wurde das Spiel abgesagt.","a":"des schlechten"},{"q":"[Mix] Das ist die Wohnung ___ Freundin, ___ ich oft besuche. (mein-, Relativpronomen)","a":"meiner / die"},{"q":"[Mix] Statt ___ Taxis ___ ___ wir den Bus. (ein, nehmen – Perfekt)","a":"eines / haben genommen"}],"exam":[{"q":"Warum fallen heute viele Züge aus?","a":"Wegen eines Streiks."},{"q":"Womit fährt Ravi statt mit dem Zug?","a":"Mit einem Fernbus."},{"q":"Was macht er während der Fahrt?","a":"Er bereitet die Präsentation vor."},{"q":"Ergänze: Wegen ___ Krankheit (meine) kann ich nicht kommen.","a":"meiner"},{"q":"Ergänze: Der Bruder ___ Freund___ (mein) ist Arzt.","a":"meines Freundes"},{"q":"Umformen (während): Als der Film lief, ist er eingeschlafen.","a":"Während des Films ist er eingeschlafen."},{"q":"Umformen (weil): Wegen der Hitze bleiben wir drinnen.","a":"Weil es heiß ist, bleiben wir drinnen."},{"q":"Sie hatten eine schwierige Reise. Erzählen Sie mit wegen, trotz, während.","a":""},{"q":"Was machen Sie während der Ferien?","a":""},{"q":"Schreiben Sie eine Entschuldigungs-E-Mail: Sie kommen wegen … zu spät.","a":""}],"speak":["Hör dir die Durchsage an (Lesetext) und erkläre sie einem Freund.","Was machen die Leute während des Wartens?","Warum hat der Zug vielleicht Verspätung? __Wegen …__","Trotz welcher Probleme reist du gern?"]},{"n":41,"level":"B1","title":"Futur I und die vielen Funktionen von werden","theme":"Zukunftspläne","scene":"classroom","rec":[11,25,28,29,39],"expl":["**Futur I** = **werden (Position 2) + Infinitiv (Ende)**: __Ich **werde** nach Indien **fliegen**.__ Oft reicht das **Präsens + Zeitangabe** (__Morgen fliege ich …__). Futur benutzt man für **Pläne, Versprechen, Vorhersagen** und **Vermutungen** (+ wohl): __Er **wird wohl** krank **sein**.__","**werden hat 4 Funktionen:** 1) Vollverb **werden** = become (__Ich werde Arzt.__) 2) **Futur** (__Ich werde lernen.__) 3) **Passiv** (__Das Haus wird gebaut.__) 4) **Konjunktiv II** würde (__Ich würde gern …__).","Im Nebensatz steht werden am Ende: __…, dass ich die Prüfung bestehen **werde**.__"],"use":"Prüfung: über Pläne und Zukunft sprechen, Versprechen, Vermutungen bei Bildern.","table":[["Funktion","Form","Beispiel"],["Vollverb (become)","werden + Nomen/Adjektiv","Ravi **wird** Teamleiter. Es **wird** kalt."],["Futur I","werden + Infinitiv","Ich **werde** im Mai **heiraten**."],["Vermutung","werden + wohl + Infinitiv","Sie **wird wohl** im Stau **stehen**."],["Passiv","werden + Partizip II","Der Reis **wird gekocht**."],["Konjunktiv II","würde + Infinitiv","Ich **würde** gern **kommen**."]],"examples":[{"de":"Ich werde nächstes Jahr die B2-Prüfung machen.","en":"I'll take the B2 exam next year."},{"de":"Es wird morgen regnen.","en":"It will rain tomorrow."},{"de":"Keine Sorge, ich werde dir helfen!","en":"Don't worry, I'll help you!"},{"de":"Leila wird bald Fachärztin.","en":"Leila will soon become a specialist."},{"de":"Jonas ist nicht da. Er wird wohl krank sein.","en":"Jonas isn't here. He's probably ill."},{"de":"Wir werden sehen.","en":"We'll see."},{"de":"In zehn Jahren werden Autos selbst fahren.","en":"In ten years cars will drive themselves."},{"de":"Ich hoffe, dass ich einen guten Job finden werde.","en":"I hope I'll find a good job."},{"de":"Das Projekt wird nächste Woche präsentiert.","en":"The project will be presented next week. (Passiv Präsens mit Zukunftsbedeutung)"},{"de":"Ich verspreche dir, dass ich pünktlich sein werde.","en":"I promise I'll be on time."}],"vocab":[{"de":"die Zukunft","en":"future"},{"de":"der Plan, ¨e","en":"plan"},{"de":"planen","en":"to plan"},{"de":"versprechen","en":"to promise"},{"de":"die Vorhersage, -n","en":"forecast"},{"de":"vermuten","en":"to assume"},{"de":"wahrscheinlich","en":"probably"},{"de":"bald","en":"soon"},{"de":"in Zukunft","en":"in future"},{"de":"der Traumjob, -s","en":"dream job"},{"de":"selbstständig","en":"self-employed"},{"de":"heiraten","en":"to marry"}],"reading":"Frau Klein fragt am letzten Kurstag: „Was werdet ihr nach dem Kurs machen?“ Ravi antwortet: „Ich werde im Dezember die Prüfung machen und danach werde ich meine Eltern besuchen. Nächstes Jahr werde ich hoffentlich Teamleiter.“ Leila sagt: „Ich werde als Ärztin arbeiten. Aber zuerst muss mein Diplom anerkannt werden.“ Ein Teilnehmer fehlt. Frau Klein vermutet: „Er wird wohl noch schlafen!“ Alle lachen. „Ich bin sicher, dass ihr alle die Prüfung bestehen werdet.“","tasks":[{"q":"Futur: Ich fahre nach Paris. → Ich ___ nach Paris ___.","a":"werde / fahren"},{"q":"Futur: Wir lernen morgen. → Wir ___ morgen ___.","a":"werden / lernen"},{"q":"Vermutung: Er ist wohl zu Hause. → Er ___ wohl zu Hause ___.","a":"wird / sein"},{"q":"Funktion? „Sie wird Lehrerin.“","a":"Vollverb (become)"},{"q":"Funktion? „Die Tür wird geöffnet.“","a":"Passiv"},{"q":"Funktion? „Ich würde gern tanzen.“","a":"Konjunktiv II"},{"q":"Nebensatz: Ich glaube, dass es morgen ___ ___. (regnen, Futur)","a":"regnen wird"},{"q":"[Mix] Ich werde ___ ___ Prüfung gut vorbereiten. (sich, auf die)","a":"mich auf die"},{"q":"[Mix] Nachdem ich die Prüfung bestanden habe, ___ ich ___ Freunden feiern. (werden, mit mein-)","a":"werde / mit meinen"},{"q":"[Mix] Wenn ich mehr Geld ___, ___ ich ein Haus kaufen. (haben, werden – Konj. II)","a":"hätte / würde"}],"exam":[{"q":"Was wird Ravi im Dezember machen?","a":"Die Prüfung machen."},{"q":"Was muss zuerst mit Leilas Diplom passieren?","a":"Es muss anerkannt werden."},{"q":"Was vermutet Frau Klein über den fehlenden Teilnehmer?","a":"Er wird wohl noch schlafen."},{"q":"Futur: Das Wetter wird schön. → morgen","a":"Das Wetter wird morgen schön (sein)."},{"q":"Vermutung: Wo ist Anna? (im Büro)","a":"Sie wird wohl im Büro sein."},{"q":"Ergänze: Ich verspreche, dass ich dich anrufen ___.","a":"werde"},{"q":"Bestimme die Funktion: „Das Essen wurde serviert.“","a":"Passiv (Präteritum)"},{"q":"Wie wird Ihr Leben in 10 Jahren aussehen?","a":""},{"q":"Wie wird die Welt im Jahr 2050 sein? Machen Sie Vorhersagen.","a":""},{"q":"Was werden Sie nach der B1-Prüfung machen?","a":""}],"speak":["Was werden die Teilnehmer nach dem Kurs machen? (Vermutung)","Was wird wohl die Lehrerin sagen?","Mach 3 Versprechen: __Ich werde …__","Wie wird Berlin / Mumbai in 30 Jahren aussehen?"]},{"n":42,"level":"B1","title":"je … desto + Abschluss: Eine Präsentation halten","theme":"Alles zusammen: Leben in Deutschland","scene":"classroom","rec":[17,21,22,25,33,36,37,38,40,41],"expl":["**je … desto/umso + Komparativ**: Der **je-Teil** ist ein **Nebensatz** (Verb am Ende), der **desto-Teil** hat **Inversion** (Verb direkt nach dem Komparativ): __**Je mehr** ich **übe**, **desto besser spreche** ich.__","Diese Lektion ist dein **Abschluss**: Eine B1-Präsentation (Goethe Teil 2) mit **allen** Strukturen. Folien: 1) Thema vorstellen 2) Eigene Erfahrung 3) Situation im Heimatland 4) Vor- und Nachteile + Meinung 5) Abschluss + Dank.","Pro Folie ca. 3–4 Sätze. Benutze **Konnektoren** (zuerst, außerdem, deshalb, obwohl, zwar … aber), **Perfekt/Präteritum** für Erfahrungen, **Komparativ** für Vergleiche, **Konjunktiv II** für Meinungen."],"use":"Prüfung Sprechen Teil 2 + 3 (Präsentation und Rückfragen).","table":[["Folie","Redemittel","Grammatik"],["1 Thema","Ich spreche heute über das Thema … Meine Präsentation hat drei Teile: …","zuerst, dann, zum Schluss"],["2 Erfahrung","Ich habe die Erfahrung gemacht, dass … Als ich nach Deutschland kam, …","Perfekt, als, dass"],["3 Heimatland","In Indien ist das anders: … Dort … mehr / weniger als hier.","Komparativ, Relativsatz"],["4 Vor-/Nachteile","Ein Vorteil ist, dass … Zwar …, aber … Meiner Meinung nach sollte man …","zwar…aber, sollte, obwohl"],["5 Abschluss","Zum Schluss möchte ich sagen: Je …, desto … Vielen Dank fürs Zuhören! Haben Sie Fragen?","je…desto"],["Rückfragen (Teil 3)","Danke für die Frage. Das ist eine gute Frage. Ich glaube, dass …","dass, weil"]],"examples":[{"de":"Je länger ich in Berlin wohne, desto besser gefällt es mir.","en":"The longer I live in Berlin, the more I like it."},{"de":"Je mehr man liest, desto größer wird der Wortschatz.","en":"The more you read, the bigger your vocabulary gets."},{"de":"Je früher du anfängst, umso schneller bist du fertig.","en":"The earlier you start, the sooner you're done."},{"de":"Je teurer die Wohnung ist, desto kleiner ist sie oft.","en":"The more expensive the flat, often the smaller it is."},{"de":"Ich spreche heute über das Thema „Allein leben“.","en":"Today I'm talking about \"living alone\"."},{"de":"Als ich nach Deutschland kam, habe ich zum ersten Mal allein gewohnt.","en":"When I came to Germany I lived alone for the first time."},{"de":"In Indien wohnen junge Leute meistens bei ihren Eltern, bis sie heiraten.","en":"In India young people mostly live with their parents until they marry."},{"de":"Allein leben ist zwar ruhig, aber manchmal fühlt man sich einsam.","en":"Living alone is quiet, but sometimes you feel lonely."},{"de":"Meiner Meinung nach sollte jeder das einmal erleben.","en":"In my opinion everyone should experience it once."},{"de":"Vielen Dank fürs Zuhören. Haben Sie noch Fragen?","en":"Thank you for listening. Any questions?"}],"vocab":[{"de":"die Präsentation, -en","en":"presentation"},{"de":"die Folie, -n","en":"slide"},{"de":"das Thema, Themen","en":"topic"},{"de":"die Erfahrung, -en","en":"experience"},{"de":"das Heimatland, ¨er","en":"home country"},{"de":"der Vorteil, -e / der Nachteil, -e","en":"advantage / disadvantage"},{"de":"einsam","en":"lonely"},{"de":"unabhängig","en":"independent"},{"de":"die Verantwortung","en":"responsibility"},{"de":"zusammenfassen","en":"to summarise"},{"de":"zuhören","en":"to listen"},{"de":"die Rückfrage, -n","en":"follow-up question"}],"reading":"**Musterpräsentation (Ravi): „Allein leben – ja oder nein?“** Ich spreche heute über das Thema „Allein leben“. Zuerst erzähle ich von meiner Erfahrung, dann von der Situation in Indien, und zum Schluss sage ich meine Meinung. Als ich vor einem Jahr nach Berlin gekommen bin, habe ich zum ersten Mal allein gewohnt. Am Anfang war das schwer, weil ich weder kochen noch waschen konnte. In Indien ist das anders: Die meisten jungen Leute, die nicht verheiratet sind, wohnen bei ihren Eltern. Das ist nicht nur billiger, sondern man ist auch nie allein. Ein Vorteil vom Alleinleben ist, dass man unabhängig ist. Ein Nachteil ist, dass man sich manchmal einsam fühlt. Obwohl ich meine Familie vermisse, möchte ich diese Erfahrung nicht verlieren. Meiner Meinung nach sollte jeder junge Mensch einmal allein wohnen, denn je mehr Verantwortung man hat, desto schneller wird man erwachsen. Vielen Dank fürs Zuhören!","tasks":[{"q":"Je mehr ich schlafe, ___ fitter ___ ich. (sein)","a":"desto / bin"},{"q":"Je ___ (spät) es wird, desto ___ (müde) werde ich.","a":"später / müder"},{"q":"Verbinde: Man übt viel. Man spricht gut. (je … desto)","a":"Je mehr man übt, desto besser spricht man."},{"q":"Verbinde: Die Stadt ist groß. Das Leben ist teuer.","a":"Je größer die Stadt ist, desto teurer ist das Leben."},{"q":"Fehler? „Je mehr ich lerne, desto ich weiß mehr.“","a":"…, desto mehr weiß ich."},{"q":"Ergänze: Ein Vorteil ist, ___ man unabhängig ist.","a":"dass"},{"q":"Ergänze: Allein leben ist ___ ruhig, ___ manchmal einsam.","a":"zwar / aber"},{"q":"[Mix] Als ich nach Berlin ___ ___, konnte ich nicht kochen. (kommen, Perfekt)","a":"gekommen bin"},{"q":"[Mix] Die Leute, ___ ich hier kennengelernt habe, sind wie eine Familie.","a":"die"},{"q":"[Mix] Wegen ___ hoh___ Mieten wohnen viele Studenten in WGs.","a":"der hohen"}],"exam":[{"q":"Wann hat Ravi zum ersten Mal allein gewohnt?","a":"Als er vor einem Jahr nach Berlin gekommen ist."},{"q":"Warum war es am Anfang schwer?","a":"Weil er weder kochen noch waschen konnte."},{"q":"Was ist Ravis Meinung?","a":"Jeder junge Mensch sollte einmal allein wohnen."},{"q":"Welche zwei Vorteile hat das Wohnen bei den Eltern (laut Text)?","a":"Es ist billiger und man ist nie allein."},{"q":"Bilde einen je…desto-Satz zum Thema Sport.","a":"z. B. Je mehr ich Sport mache, desto gesünder fühle ich mich."},{"q":"Halten Sie eine Präsentation (3 Min.): „Homeoffice – Vor- und Nachteile“.","a":""},{"q":"Halten Sie eine Präsentation: „Kinder und Smartphones“.","a":""},{"q":"Halten Sie eine Präsentation: „Online einkaufen oder im Geschäft?“","a":""},{"q":"Geben Sie Ihrem Partner Feedback zu seiner Präsentation und stellen Sie eine Frage.","a":""},{"q":"Beantworten Sie eine Rückfrage zu Ihrer Präsentation: „Würden Sie wieder allein wohnen?“","a":""}],"speak":["Halte eine Mini-Präsentation über deinen Deutschkurs mit allen 5 Folien.","Benutze mindestens: Perfekt, weil, obwohl, zwar … aber, Komparativ, Konjunktiv II, je … desto.","Nimm dich auf (3 Minuten), hör zu und prüfe: Verb auf Position 2? Verb am Ende im Nebensatz?","Gib Feedback: __Deine Präsentation war sehr interessant, weil … Ich habe eine Frage: …__"]}];
